/* ───────────────────────── 1. DESIGN TOKENS ───────────────────────── */

const T = {
  limestone: "#F9F6EC",          // Warm Ivory — shared surface foundation
  paper: "#FFFCF6",
  sand: "#E8E2D6",               // Soft Stone — quiet surfaces
  sandDeep: "#DED2BE",
  ink: "#1F2321",                // Ink — shared text anchor
  muted: "#756E64",
  green: "#17463A",
  deep: "#0E3129",
  brass: "#B8944A",
  brassSoft: "#D8BE86",
  clay: "#A65F45",
  ok: "#3D725E",
  warn: "#A6522D",
  line: "rgba(33,30,25,.12)",
  lineSoft: "rgba(33,30,25,.07)",
  ar: '"29LT Zarid Sans","Tajawal",Tahoma,Arial,sans-serif',
  en: '"29LT Zarid Sans","Inter",system-ui,sans-serif',
};

/* ── One foundation, two accent themes ──
   The pre-sign-in entry (Start, Language, Sign in, Create account, profile setup) uses
   the shared Rihab Makkah brand. Once an account enters the app, its persona's accent
   theme is applied to the same semantic tokens every component already reads, so
   no screen hard-codes a persona colour. Anchors are the approved palette; the few
   derived shades exist only where text needs AA contrast on Warm Ivory.
     accentPrimary   fills: primary buttons, active chips, avatar, toggles
     onAccent        text/icons placed on accentPrimary
     accentText      the accent used as text or an icon on light surfaces
     accentDeep      the deepest accent: hero surfaces carrying light text
     accentSecondary secondary fills and tints
     secondaryText   the secondary accent as text or an icon
     accentTint      quiet accent wash behind selected or highlighted content */
const BRAND_THEME = {
  green: "#17463A", deep: "#0E3129", onDeep: "#F6EFE0", brass: "#B8944A", brassSoft: "#D8BE86", clay: "#A65F45",
  heroBg: "linear-gradient(135deg, #1D5446 0%, #133B31 55%, #0E2E26 100%)", heroInk: "#F6EFE0", heroSub: "#E3C78C",
  heroCtaBg: "#F6EFE0", heroCtaInk: "#133B31", heroBadge: "linear-gradient(145deg, #E3C78C, #B8944A)", heroBadgeInk: "#133B31",
  tint: "rgba(23,70,58,.08)",
};
const PERSONA_THEME = {
  resident: {
    accentPrimary: "#315C49", onAccent: "#F6EFE0", accentText: "#315C49", accentDeep: "#244638",
    accentSecondary: "#8FA58F", secondaryText: "#56705A", accentTint: "rgba(49,92,73,.09)",
    heroBg: "linear-gradient(135deg, #315C49 0%, #244638 100%)", heroInk: "#F6EFE0", heroSub: "#C9D6C6",
    heroCtaBg: "#F6EFE0", heroCtaInk: "#244638", heroBadge: "linear-gradient(145deg, #C9D6C6, #8FA58F)", heroBadgeInk: "#244638",
  },
  visitor: {
    accentPrimary: "#B8893D", onAccent: "#1F2321", accentText: "#8A6326", accentDeep: "#8A6326",
    accentSecondary: "#B96F52", secondaryText: "#A25A3F", accentTint: "rgba(216,196,154,.42)",
    heroBg: "linear-gradient(135deg, #EBDDBC 0%, #D8C49A 100%)", heroInk: "#1F2321", heroSub: "#7E5A22",
    heroCtaBg: "#B8893D", heroCtaInk: "#1F2321", heroBadge: "linear-gradient(145deg, #B96F52, #B8893D)", heroBadgeInk: "#FFFCF6",
  },
};
Object.assign(T, BRAND_THEME, { glass: "rgba(249,246,236,.975)" });
let THEMED = undefined;
/* map a persona onto the semantic tokens (and the older names components use) */
function applyTheme(persona) {
  if (THEMED === (persona || null)) return;
  THEMED = persona || null;
  const p = PERSONA_THEME[persona];
  if (!p) { Object.assign(T, BRAND_THEME, { accentPrimary: BRAND_THEME.deep, onAccent: BRAND_THEME.onDeep, accentText: BRAND_THEME.green, accentDeep: BRAND_THEME.deep, accentSecondary: BRAND_THEME.brass, secondaryText: BRAND_THEME.brass, accentTint: BRAND_THEME.tint }); return; }
  Object.assign(T, p, {
    green: p.accentText, deep: p.accentPrimary, onDeep: p.onAccent, brass: p.secondaryText, brassSoft: p.accentSecondary,
    clay: persona === "visitor" ? "#A25A3F" : p.accentDeep, tint: p.accentTint,
  });
}
applyTheme(null);
const themeVars = () => ({
  "--accent-primary": T.accentPrimary, "--accent-secondary": T.accentSecondary, "--accent-deep": T.accentDeep,
  "--on-accent": T.onAccent, "--accent-text": T.accentText, "--surface-base": T.limestone, "--text-primary": T.ink, "--border-soft": T.sand,
});

const R = { ctl: 8, box: 12, boxLg: 14, media: 16, mediaLg: 20, pill: 999 };

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800&family=Inter:wght@400;500;600;700&display=swap');

.em *, .em *::before, .em *::after { box-sizing: border-box; }
.em { font-family: ${T.ar}; color: ${T.ink}; -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
.em[dir="ltr"] { font-family: ${T.en}; }
.em .lat { font-family: ${T.en}; }
.em button { font: inherit; color: inherit; cursor: pointer; background: none; border: none; padding: 0; -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.em input, .em textarea, .em select { font: inherit; color: inherit; }
.em ::-webkit-scrollbar { width: 0; height: 0; }
.em .scroll { scrollbar-width: none; -ms-overflow-style: none; overscroll-behavior-y: contain; }
.em .row { display: flex; align-items: center; }
.em img, .em svg { max-width: 100%; }

/* the phone frame is the layout container: rail cards size against it (cqi), and layout
   containment makes it the containing block for fixed overlays, so sheets and scrims cover
   the visible frame (not the whole browser window) on a wide screen too */
.em [data-phone] { container-type: inline-size; contain: layout; }
/* real-place tiles (logo, category): sized by their own width, so a thumbnail shows
   only the mark and a card or hero also names the kind of place */
.em .vt { container-type: inline-size; }
.em .vt-label { display: none; font-size: 11.5px; font-weight: 700; line-height: 1.35; text-align: center; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@container (min-width: 118px) { .em .vt-label { display: block; } }
/* a small supplied photo fills a card, but in a large frame it is shown whole over a soft
   copy of itself rather than enlarged past its own resolution */
@container (min-width: 300px) { .em .lo-fg { object-fit: contain !important; } }
/* a supplied logo: whole, never stretched, never past its own pixels (2x screens); in a
   large frame it sits smaller and higher, clear of the title over the lower part */
.em .pl-logo { position: absolute; inset: 0; display: grid; place-items: center; padding-bottom: 6%; }
.em .pl-logo img { display: block; width: auto; height: auto; max-width: min(72%, var(--lw)); max-height: min(56%, var(--lh)); object-fit: contain; }
@container (min-width: 300px) { .em .pl-logo { padding-bottom: 20%; } .em .pl-logo img { max-width: min(56%, var(--lw)); max-height: min(36%, var(--lh)); } }
.em { --rail-tile: clamp(144px, calc((100cqi - 40px) / 2.3), 204px); --rail-feature: clamp(236px, calc((100cqi - 28px) / 1.28), 340px); }
.em[dir="rtl"] { --rail-end: left; --rail-start: right; }
.em[dir="ltr"] { --rail-end: right; --rail-start: left; }

/* every screen is a phone screen: nothing may exceed the viewport inline size */
.em .screen { width: 100%; max-width: 100%; overflow-x: clip; }
.em .pad { padding-inline: 16px; }

/* touch: no primary control smaller than a comfortable thumb */
.em .press { transition: transform .16s cubic-bezier(.2,.8,.2,1), opacity .16s ease; }
.em .press:active { transform: scale(.97); opacity: .9; }
.em .lift { transition: transform .22s cubic-bezier(.2,.8,.2,1); }
.em .lift:active { transform: scale(.985); }
.em .tap { position: relative; }
.em .tap::after { content: ""; position: absolute; inset: 50% 50% 50% 50%; width: 44px; height: 44px; transform: translate(50%, -50%); }
.em[dir="ltr"] .tap::after { transform: translate(-50%, -50%); }
/* chevrons are drawn for RTL (back ›, forward ‹); English mirrors them, and the send
   arrow points the way the text runs */
.em[dir="ltr"] svg.lucide-chevron-left, .em[dir="ltr"] svg.lucide-chevron-right, .em[dir="rtl"] svg.lucide-send { transform: scaleX(-1); }
.em input { text-overflow: ellipsis; }
/* the touch area reaches past the 22px pin: inset is measured from the padding box
   (22 − 2×2 border = 18px), so −13px makes it 44px; a selected pin gets 50px */
.em .pin::after { content: ""; position: absolute; inset: -13px; border-radius: 99px; }

/* horizontal rails — direction-agnostic, edge padding inside the scroller so the
   last card can always be reached in both RTL and LTR */
.em .rail {
  display: flex; gap: 12px; overflow-x: auto; overflow-y: hidden;
  padding-inline: 16px; padding-block-end: 4px;
  scroll-snap-type: x proximity; scroll-padding-inline-start: 16px;
  -webkit-overflow-scrolling: touch; touch-action: pan-x pan-y;
  scrollbar-width: none; overscroll-behavior-x: contain;
}
.em .rail::-webkit-scrollbar { display: none; }
.em .rail > * { scroll-snap-align: start; flex: 0 0 auto; }
.em .rail::after { content: ""; flex: 0 0 4px; }
/* edge fades, set by useRailFades only while content actually continues past an edge,
   so a card or chip at the edge reads as "more this way", never as an accidental cut */
.em .rail[data-fade="end"] { -webkit-mask-image: linear-gradient(to var(--rail-end), #000 calc(100% - var(--fade-end, 44px)), transparent); mask-image: linear-gradient(to var(--rail-end), #000 calc(100% - var(--fade-end, 44px)), transparent); }
.em .rail[data-fade="start"] { -webkit-mask-image: linear-gradient(to var(--rail-start), #000 calc(100% - var(--fade-start, 28px)), transparent); mask-image: linear-gradient(to var(--rail-start), #000 calc(100% - var(--fade-start, 28px)), transparent); }
.em .rail[data-fade="both"] { -webkit-mask-image: linear-gradient(to var(--rail-end), transparent 0, #000 var(--fade-start, 28px), #000 calc(100% - var(--fade-end, 44px)), transparent 100%); mask-image: linear-gradient(to var(--rail-end), transparent 0, #000 var(--fade-start, 28px), #000 calc(100% - var(--fade-end, 44px)), transparent 100%); }

.em .clamp1 { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.em .clamp2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.em .clamp3 { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.em .clamp4 { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.em .break { overflow-wrap: anywhere; word-break: break-word; }

@keyframes emUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes emIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes emSheet { from { transform: translateY(100%); } to { transform: none; } }
@keyframes emScrim { from { opacity: 0; } to { opacity: 1; } }
@keyframes emShimmer { 0% { background-position: 120% 0; } 100% { background-position: -120% 0; } }
@keyframes emSpin { to { transform: rotate(360deg); } }
@keyframes emPush { from { opacity: .4; transform: translateX(var(--push, 18px)); } to { opacity: 1; transform: none; } }
@keyframes emRise { 0% { transform: translateY(0); opacity: 0; } 12% { opacity: 1; } 100% { transform: translateY(-190px); opacity: 0; } }
@keyframes emLangFlowR { to { stroke-dashoffset: 0; } }
@keyframes emLangFlowL { to { stroke-dashoffset: 0; } }
.em .up { animation: emUp .34s cubic-bezier(.2,.8,.2,1) backwards; }
.em .fade { animation: emIn .3s ease backwards; }
.em .sheetIn { animation: emSheet .3s cubic-bezier(.2,.9,.25,1) backwards; }
.em .scrimIn { animation: emScrim .22s ease backwards; }
.em .spin { animation: emSpin 1s linear infinite; }
.em .push { animation: emPush .26s cubic-bezier(.2,.8,.2,1) backwards; }
.em .shim { background: linear-gradient(90deg, ${T.sand} 25%, ${T.limestone} 50%, ${T.sand} 75%); background-size: 240% 100%; animation: emShimmer 1.4s linear infinite; }

@media (prefers-reduced-motion: reduce) {
  .em .up, .em .fade, .em .sheetIn, .em .scrimIn, .em .shim, .em .spin, .em .push { animation: none !important; }
  .em [style*="emRise"] { animation: none !important; opacity: .35 !important; }
  .em .press, .em .lift { transition: none !important; }
}
`;

