/* Context photographs — only for places whose own record says they are inside the
   complex or district the photograph shows. A place merely near a landmark gets none. */
const CLOCK_CTX = { slot: "makkah_clocktower_day", ar: "برج الساعة (أبراج البيت)", en: "the Clock Tower (Abraj Al Bait) complex", relAr: "يقع المكان داخل هذا المجمع", relEn: "the place is inside this complex" };
