const NOUR_CTX = { slot: "makkah_jabal_nour", ar: "جبل النور", en: "Jabal al-Nour", relAr: "يقع المكان في حي جبل النور الذي يحمل اسم هذا الجبل", relEn: "the place is in the Jabal al-Nour district, named after this mountain" };
