/* context photographs for the venues whose own record places them in that complex or district */
VENUES.forEach((v) => { const c = CONTEXT_OF[v.id]; if (c) { v.pt = c.slot; v.ptc = true; } });
/* a supplied place photo or brand logo outranks a context photo or a category tile;
   a place's own existing photograph is never replaced */
[...PLACES, ...VENUES].forEach((v) => {
  const a = PLACE_ASSET_BY_ID[v.id];
  if (!a || (v.pt && !v.ptc)) return;
  if (a.kind === "photo") { v.pt = "pa_" + a.stem; v.ptc = false; } else { delete v.pt; v.ptc = false; }
});

/* ───────── 4.6 Expansion into the working object model ───────── */

const TYPE_BY_PREFIX = { p: "place", r: "restaurant", c: "restaurant", x: "experience", e: "event", a: "activity", g: "recurring", o: "offer", s: "service", st: "place", gen: "place" };

function inferType(id, fallback) {
  if (fallback) return fallback;
  const head = id.split("-")[0];
  return TYPE_BY_PREFIX[head] || "place";
}

/* What a real place is, as a person would name it (café, bookstore, mall…). Read from
   the record's own kind (`t`) first, then its name; the object type ("restaurant",
   "place") is a ranking bucket and too coarse to show for real places. */
const REAL_KINDS = [
  [/مكتبة/, (o) => (o.cat === "market" ? ["مكتبة", "Bookstore"] : ["مكتبة", "Library"])],
  [/متحف/, () => ["متحف", "Museum"]],
  [/معرض/, () => ["معرض", "Exhibition"]],
  [/مقهى|محمصة|كافيه|كوفي/, () => ["مقهى", "Café"]],
  [/مخبز|مخابز/, () => ["مخبز", "Bakery"]],
  [/حلويات|حلاوة/, () => ["حلويات", "Sweets"]],
  [/مطعم|مطاعم|وجبات/, () => ["مطعم", "Restaurant"]],
  [/سوبرماركت|هايبر/, () => ["سوبرماركت", "Supermarket"]],
  [/مركز تسوق|مركز ترفيه|مول\b|مول$/, () => ["مركز تسوق", "Mall"]],
  [/سوق|أسواق/, () => ["سوق", "Market"]],
  [/حديقة/, () => ["حديقة", "Park"]],
  [/ممشى/, () => ["ممشى", "Walkway"]],
  [/مدينة رياضية|ملعب/, () => ["مدينة رياضية", "Sports city"]],
  [/محطة|قطار/, () => ["محطة قطار", "Train station"]],
  [/مسجد/, () => ["مسجد", "Mosque"]],
  [/وجهة ثقافية/, () => ["وجهة ثقافية", "Cultural district"]],
  [/كسوة/, () => ["مجمع", "Complex"]],
  [/^جبل/, () => ["جبل", "Mountain"]],
  [/موقع|بئر|قناة/, () => ["موقع تاريخي", "Historic site"]],
];
function realKindLabel(o) {
  const byCat = { cafe: ["مقهى", "Café"], food: ["مطعم", "Restaurant"] }[o.cat];
  for (const text of [o.t || "", o.n || ""]) {
    for (const [re, f] of REAL_KINDS) if (re.test(text)) { const [a, e] = f(o); return tx(a, e); }
  }
  if (byCat) return tx(byCat[0], byCat[1]);
  if (o.cat === "heritage") return tx("موقع تاريخي", "Historic site");
  return null;
}
const TYPE_LABEL = bilingual({
  place: "مكان", restaurant: "مطعم", experience: "تجربة", event: "فعالية",
  activity: "نشاط", recurring: "مجموعة متكررة", offer: "عرض", service: "خدمة", community: "مجتمع", contribution: "مساهمة",
}, {
  place: "Place", restaurant: "Restaurant", experience: "Experience", event: "Event",
  activity: "Activity", recurring: "Recurring group", offer: "Offer", service: "Service", community: "Community", contribution: "Contribution",
});

const AL_TYPE = bilingual({
  place: "المكان", restaurant: "المطعم", experience: "التجربة", event: "الفعالية",
  activity: "النشاط", recurring: "المجموعة", offer: "العرض", service: "الخدمة",
}, {
  place: "this place", restaurant: "this restaurant", experience: "this experience", event: "this event",
  activity: "this activity", recurring: "this group", offer: "this offer", service: "this service",
});
const alType = (o) => AL_TYPE[o.type] || tx("العنصر", "this item");

const ACTION_LABEL = bilingual({
  go: "الاتجاهات", book: "احجز", register: "سجّل", join: "انضم", redeem: "استخدم العرض",
  contact: "تواصل", official: "افتح الموقع الرسمي",
}, {
  go: "Directions", book: "Book", register: "Register", join: "Join", redeem: "Use offer",
  contact: "Contact", official: "Open the official site",
});

const priceNeedsUnit = (raw, type) => raw.price > 0 && !raw.priceUnit && (type === "service" || raw.cat === "stay" || (type === "place" && raw.act === "book"));
const SCHEDULE_LABELS = ["الموعد", "الوردية", "الفترة", "ينتهي"];
/* The practical-facts "when" row for a dated item, read from its timing so the page
   can never disagree with itself. Recurring items keep their written cadence. */
function scheduleRow(o) {
  const tm = o.timing;
  if (!tm || !["session", "window"].includes(tm.kind)) return null;
  const life = lifecycleOf(o);
  if (tm.kind === "session") {
    const s = new Date(tm.start), e = new Date(tm.end);
    const end = mkHour(e) === 0 ? tx("منتصف الليل", "midnight") : clockAr(e);
    return { label: D("الموعد"), value: `${dayLabelAr(s)} ${clockAr(s)} — ${end}` };
  }
  const from = new Date(tm.from), to = new Date(tm.to);
  if (o.type === "offer") return { label: D("ينتهي"), value: life === "expired" ? tx("انتهى العرض", "Offer ended") : dayLabelAr(to) };
  if (life === "ended") return { label: D("الفترة"), value: tx("انتهت", "Ended") };
  return { label: D("الفترة"), value: from <= NOW ? tx(`حتى ${dayLabelAr(to)}`, `Until ${midEn(dayLabelAr(to))}`) : `${dayLabelAr(from)} — ${dayLabelAr(to)}` };
}

function expand(raw, forcedType) {
  const type = inferType(raw.id, forcedType);
  const r = rng(raw.id);
  const claims = [];
  /* a dated item's "when" comes from its timing alone (see scheduleRow), never a written copy */
  const fx = (raw.fx || []).filter(([label]) => !(SCHEDULE_LABELS.includes(label) && ["session", "window"].includes(raw.tm?.kind)));
  const push = (field, cls, value, ageDays, fresh) =>
    claims.push({ id: `${raw.id}:${field}:${cls}`, obj: raw.id, field, cls, value, at: daysAgo(ageDays), fresh: fresh || "F3" });

  push("identity", raw.venue ? "rihab" : raw.real ? "official" : "provider", raw.n, raw.venue ? 0 : raw.real ? 120 : 45, "F4");
  fx.forEach((f, i) => {
    const [label, value, cls, ageDays, fresh] = f;
    claims.push({ id: `${raw.id}:f${i}`, obj: raw.id, field: label, cls, value, at: daysAgo(ageDays), fresh: fresh || "F3" });
  });

  const built = {
    ...raw,
    type,
    name: raw.n,
    tagline: raw.t || "",
    about: raw.ab || "",
    neighborhood: raw.nb,
    category: raw.cat,
    provider: raw.pr || null,
    scene: raw.sc || "skyline",
    photo: listingPhoto(raw, type),
    photoExact: !!raw.pt && !raw.ptc,
    real: !!raw.real,
    generated: !!raw.generated,
    /* a price that depends on what is booked (a service, a stay, a bookable hall) is shown
       only with what it covers (priceUnit); without one the amount stays with the provider
       and the app never shows a bare number */
    price: raw.price === undefined || priceNeedsUnit(raw, type) ? null : raw.price,
    priceOnRequest: priceNeedsUnit(raw, type),
    /* a dated session's length is its schedule's length, so no screen can disagree */
    duration: raw.tm?.kind === "session" ? Math.round((new Date(raw.tm.end) - new Date(raw.tm.start)) / MIN) : raw.dur === undefined ? null : raw.dur,
    suit: raw.su || [],
    action: raw.act || "go",
    outbound: raw.out || null,
    timing: raw.tm || null,
    facts: fx.map(([label, value, cls, ageDays, fresh]) => ({ label, value, cls, at: daysAgo(ageDays), fresh: fresh || "F3" })),
    claims,
    communities: raw.com || [],
    novelty: raw.nov ?? 0.5,
    popularity: raw.pop ?? 0.5,
    capacity: raw.cap ?? null,
    joinedCount: raw.joined ?? null,
    members: raw.members ?? null,
    groupState: raw.state ?? null,
    lastActivityDays: raw.lastActivityDays ?? null,
    linked: raw.linked || null,
    geo: (() => {
      const nb = NB[raw.nb] || NB["haram-area"];
      return { x: clamp(nb.x + (r() - 0.5) * 0.11, 0.04, 0.96), y: clamp(nb.y + (r() - 0.5) * 0.11, 0.05, 0.95) };
    })(),
  };
  /* language-aware reads: the same object serves both languages */
  Object.defineProperty(built, "typeLabel", { enumerable: true, get() { return (this.real && realKindLabel(this)) || TYPE_LABEL[this.type]; } });
  ["name", "tagline", "about"].forEach((f) => {
    const v = built[f];
    Object.defineProperty(built, f, { enumerable: true, get: () => D(v) });
  });
  built.facts = built.facts.map((f) => ({ ...f, get label() { return D(f.label); }, get value() { return D(f.value); } }));
  built.claims = built.claims.map((c) => ({ ...c, get field() { return D(c.field); }, get value() { return D(c.value); } }));
  return built;
}

const INVENTORY = [
  ...PLACES.map((o) => expand(o, "place")),
  ...RESTAURANTS.map((o) => expand(o, "restaurant")),
  ...CAFES.map((o) => expand(o, "restaurant")),
  ...EXPERIENCES.map((o) => expand(o, "experience")),
  ...EVENTS.map((o) => expand(o, "event")),
  ...ACTIVITIES.map((o) => expand(o, "activity")),
  ...RECURRING.map((o) => expand(o, "recurring")),
  ...OFFERS.map((o) => expand(o, "offer")),
  ...SERVICES.map((o) => expand(o, "service")),
  ...STAYS.map((o) => expand(o, "place")),
  ...MORE.map((o) => expand(o)),
  ...VENUES.map((o) => expand(o, ["food", "cafe"].includes(o.cat) ? "restaurant" : "place")),
  ...generateStaples().map((o) => expand(o, "place")),
];

const OBJ = byId(INVENTORY);
INVENTORY.forEach((o) => { if (o.real) EXACT_PHOTO_ONLY.add(o.id); });
const getObj = (id) => OBJ[id] || null;


/* ───────── 4.8 Offers & deals — one shared model ─────────
   Every deal the app shows (badges on cards, the decision-page panel, the Home and
   Discover deal rails, My Plan and the Assistant) reads these records. A record is
   linked to an inventory object; the older offer-type objects (o-*) point back to
   their record through `offerObj`, so both read the same value, terms and validity.
   Values, packages and validity are ILLUSTRATIVE prototype data, not live commercial
   offers, and the UI says so. Lifecycle is derived from validity against the
   prototype clock; expired and not-yet-started offers are never promoted. */
