/* The demo offer calendar. Every offer — the offer pages and the offers attached to
   places — gets an end date between 1 Nov 2026 and 30 Apr 2027. When one has expired it
   renews for another period of the same length, so the demo always has offers running. */
const OFFER_SLOTS = (() => {
  const slots = [
    ...INVENTORY.filter((o) => o.type === "offer" && o.timing?.offerOrder != null).map((o) => ({ id: o.id, order: o.timing.offerOrder, tm: o.timing })),
    ...OFFER_SEED.filter(([, , , s]) => !s.offerObj).map(([id, , , s]) => ({ id, order: s.to ?? 10 })),
  ].sort((a, b) => a.order - b.order || (a.id < b.id ? -1 : 1));
  const span = OFFER_LAST_END - OFFER_FIRST_END, out = {};
  slots.forEach((x, i) => {
    let end = OFFER_FIRST_END + Math.round((slots.length > 1 ? (i * span) / (slots.length - 1) : 0) / DAY) * DAY;
    let start = OFFER_START;
    const len = Math.round((end - start) / DAY) * DAY;     // whole days, so a renewed offer still ends at 23:59
    if (t0 >= end) { const k = Math.floor((t0 - end) / len) + 1; start += k * len; end += k * len; }
    out[x.id] = { from: new Date(start), to: new Date(end) };
    if (x.tm) Object.assign(x.tm, out[x.id]);
  });
  return out;
})();

const DEALS = OFFER_SEED.map(([id, obj, kind, s]) => {
  const oo = s.offerObj ? getObj(s.offerObj) : null;
  const win = oo?.timing?.kind === "window" ? oo.timing : null;
  return {
    id, obj, kind, pct: s.pct ?? null, now: s.now ?? null, was: s.was ?? null,
    badge: s.badge, title: s.title, desc: s.desc, incl: s.incl || [], terms: s.terms,
    who: s.who || "all", exclusive: !!s.excl, when: s.when || null, redeem: s.redeem || "venue",
    start: win ? new Date(win.from) : OFFER_SLOTS[id].from, end: win ? new Date(win.to) : OFFER_SLOTS[id].to,
    offerObj: s.offerObj || null, source: "prototype",
  };
});
const DEAL_BY_ID = byId(DEALS);
const L2 = (pair) => (pair ? (isEn() ? pair[1] : pair[0]) : "");
function offerStatus(of) {
  const s = of.start.getTime(), e = of.end.getTime();
  if (e < t0) return "expired";
  if (s > t0) return "upcoming";
  if (e - t0 < 36 * HOUR) return "ending";
  return "active";
}
const offerLive = (of) => ["active", "ending"].includes(offerStatus(of));
/* the live offer shown for an object (its own record, or the record of an o-* offer) */
function offerFor(objOrId) {
  const id = typeof objOrId === "string" ? objOrId : objOrId?.id;
  if (!id) return null;
  const own = DEALS.filter((of) => (of.obj === id || of.offerObj === id) && offerLive(of));
  return own.sort((a, b) => (b.exclusive - a.exclusive) || ((b.pct || 0) - (a.pct || 0)))[0] || null;
}
const liveOffers = () => DEALS.filter(offerLive);
/* price the offer implies for its object — only computed from represented prices */
function offerPrice(of) {
  const o = getObj(of.obj);
  /* a stay, service or bookable place has no single unit price, so an offer's own price
     is read as the price of the whole package it describes (e.g. one night + breakfast for two) */
  if (of.now != null && of.was != null) return { now: of.now, was: of.was, pkg: !!o?.priceOnRequest };
  if (of.pct && o?.price) return { now: Math.round(o.price * (100 - of.pct) / 100), was: o.price };
  return null;
}
function offerExpiry(of) {
  const st = offerStatus(of);
  const left = of.end.getTime() - t0;
  if (st === "upcoming") return tx(`يبدأ ${whenAr(of.start)}`, `Starts ${whenMid(of.start)}`);
  if (st === "expired") return tx("انتهى العرض", "Offer ended");
  if (left < 24 * HOUR) { const h = Math.max(1, Math.round(left / HOUR)); return tx(`ينتهي خلال ${arCount(h, "hour", { bare: true })}`, `Ends in ${h} h`); }
  /* counted in Makkah calendar days, so the number always agrees with the end date shown
     next to it, whatever the time of day */
  const d = Math.round((mkDayStart(of.end) - mkDayStart(NOW)) / DAY);
  return d <= 1 ? tx("ينتهي غدًا", "Ends tomorrow") : tx(`ساري لمدة ${arCount(d, "day")}`, `Valid ${plural(d, "more day")}`);
}
const PKG_NOTE = ["للباقة كاملة", "for the whole package"];
/* one-line summary used by cards, Plan and the Assistant */
function offerSummary(of) {
  const p = offerPrice(of);
  return Dj([L2(of.badge), p ? tx(`${ar(p.now)} ريال بدل ${ar(p.was)}${p.pkg ? " " + PKG_NOTE[0] : ""}`, `SAR ${p.now} instead of ${p.was}${p.pkg ? " " + PKG_NOTE[1] : ""}`) : null, offerExpiry(of)]);
}


/* Provider-published content enters the same inventory the whole app reads. */
function registerObject(raw, forcedType) {
  const o = expand(raw, forcedType);
  INVENTORY.push(o);
  OBJ[o.id] = o;
  return o;
}
function patchObjectFact(objId, label, value) {
  const o = OBJ[objId];
  if (!o) return;
  const claim = { id: `${objId}:prov:${hash(label + value)}`, obj: objId, field: label, cls: "provider", value, at: new Date(t0), fresh: "F3" };
  o.claims = [...o.claims, claim];
  const i = o.facts.findIndex((f) => f.label === label);
  if (i > -1) o.facts[i] = { ...o.facts[i], value, cls: "provider", at: new Date(t0) };
  else o.facts.push({ label, value, cls: "provider", at: new Date(t0), fresh: "F3" });
}
function setGroupState(objId, groupState) {
  const o = OBJ[objId];
  if (o) { o.groupState = groupState; o.state = groupState; }
}

/* distance — approximate, between an object and a point the user chose (their
   neighbourhood or a named area); never computed without one. */
function distanceKm(o, from) {
  if (!from) return null;
  const a = from;
  const dx = (o.geo.x - a.x) * 14, dy = (o.geo.y - a.y) * 14;
  return Math.round(Math.sqrt(dx * dx + dy * dy) * 10) / 10;
}
const walkMinutes = (km) => Math.round(km * 12);

