/* A starter plan for a new account, built only from the inventory and the same
   ranking Home and the Assistant use. Inputs: resident/visitor, the chosen area,
   and the reading language. Items are added as "planned" — never joined, booked or
   confirmed. Age and nationality are not used to pick content. */
/* each slot: [what fits it, prefer a real Makkah place when one fits]. The slots follow
   the persona and the interests chosen in onboarding — never age or nationality. */
function starterSlots(p) {
  const persona = personaOf(p) || "resident";
  const ints = (p.interests || []).filter((i) => interestDef(i, persona));
  if (persona === "visitor") {
    return [
      [(o) => MUST_DO_SET.has(o.id), true],                                                   // a Makkah essential
      [(o) => ["food", "cafe"].includes(o.category), true],                                    // eat
      [(o) => o.type !== "recurring" && (ints[0] ? interestMatches(o, ints[0], "visitor") : o.type === "experience"), false],
      [(o) => o.type !== "recurring" && (ints[1] ? interestMatches(o, ints[1], "visitor") : ["market", "nature", "family"].includes(o.category)), true],
    ];
  }
  const own = ints.find((x) => !["food", "community", "volunteer"].includes(x));
  return [
    [(o) => ["recurring", "activity"].includes(o.type) || o.category === "volunteer", false],   // take part locally
    [(o) => ["food", "cafe"].includes(o.category), true],                                      // eat
    [(o) => (own ? interestMatches(o, own, "resident") : ["culture", "heritage", "learn", "craft"].includes(o.category)), false],  // what you're into
    [(o) => ["nature", "sport", "market", "family"].includes(o.category), true],               // get out
  ];
}
function buildStarterPlan(state) {
  const p = state.profile;
  const ctx = deriveContext(state);
  const en = p.lang === "en";
  const pool = INVENTORY.filter((o) => isPromotable(o) && !["offer", "service"].includes(o.type) && o.category !== "stay" && !o.generated && o.id !== "haram" &&
    !(en && o.suit.includes("arabic") && !o.suit.includes("bilingual")) && !(ctx.dismissed && ctx.dismissed[o.id]));
  const slots = starterSlots(p);
  /* a visitor without an area: rank food and places by their distance from the Haram */
  if (p.mode === "visitor" && !ctx.from) ctx.from = { x: NB["haram-area"].x, y: NB["haram-area"].y };
  const chosen = [];
  const hoods = {};
  for (const [test, preferReal] of slots) {
    const fits = pool.filter((o) => test(o) && !chosen.includes(o.id));
    const real = preferReal ? fits.filter((o) => o.real && (!ctx.nb || p.mode === "visitor" || o.neighborhood === ctx.nb)) : [];
    const ok = (x) => (hoods[x.o.neighborhood] || 0) < 2;
    const opts = { limit: 12, maxPerCategory: 12, maxPerNeighborhood: 12 };
    const pick = rank(real, ctx, opts).find(ok) || rank(fits, ctx, opts).find(ok);
    if (!pick) continue;
    chosen.push(pick.o.id);
    hoods[pick.o.neighborhood] = (hoods[pick.o.neighborhood] || 0) + 1;
  }
  return chosen.map((id) => ({ id: `st-${id}`, obj: id, state: "planned", at: new Date(t0), source: "starter" }));
}

/* ═══════════════════════════════════════════════════════════════════════════
   APP CONTEXT + UI PRIMITIVES
   ═══════════════════════════════════════════════════════════════════════════ */

const App = createContext(null);
const useApp = () => useContext(App);
/* an original post in another language reads in its own direction (English left-to-right,
   Urdu right-to-left) whatever the app's language; text-align follows the direction */
const RTL_LANGS = ["ar", "ur", "fa", "he"];
const textDirOf = (orig) => (orig ? { dir: RTL_LANGS.includes(orig.lang) ? "rtl" : "ltr", lang: orig.lang } : { dir: "auto" });
/* Screen state that belongs to a place in the navigation stack: kept when another screen
   opens on top and restored on Back (search text, filters, map or list, page). */
function useViewState(key, init) {
  const mem = useContext(App)?.viewMem;
  const [v, setV] = useState(() => (mem && key in mem ? mem[key] : typeof init === "function" ? init() : init));
  useEffect(() => { if (mem) mem[key] = v; }, [mem, key, v]);
  return [v, setV];
}

/* Translates the rendered tree when the app is being read in English. Strings
   that are not in the dictionary stay exactly as their author wrote them. */
const TR_PROPS = ["placeholder", "aria-label", "title", "alt", "label", "sub", "action", "body", "msg", "note"];
/* Function components render their own subtree long after the parent element
   was created, so walking the element tree alone never reaches the strings
   inside them. Each component type is therefore swapped once for a stable
   wrapper that localizes whatever that component returns. The wrapper is
   cached per type, so React keeps seeing the same component identity and no
   state is lost between renders. */
const TR_WRAP = new WeakMap();
function trType(type) {
  if (typeof type !== "function" || type.__tr) return type;
  let w = TR_WRAP.get(type);
  if (!w) {
    w = (props) => trNode(type(props));
    w.__tr = true;
    try { Object.defineProperty(w, "name", { value: type.name || "Tr" }); } catch { /* name is read-only in some engines */ }
    TR_WRAP.set(type, w);
  }
  return w;
}
function trNode(node) {
  if (typeof node === "string") return D(node);
  if (Array.isArray(node)) return node.map(trNode);
  if (!React.isValidElement(node)) return node;
  const props = node.props || {};
  if (props.translate === "no") return node;   // names and other text the person wrote stay as written
  const patch = {};
  let changed = false;
  for (const k of TR_PROPS) {
    const v = props[k];
    const e = enText(v);
    if (e) { patch[k] = e; changed = true; }
  }
  if (props.children !== undefined) {
    const kids = trNode(props.children);
    if (kids !== props.children) { patch.children = kids; changed = true; }
  }
  const wrapped = trType(node.type);
  if (wrapped !== node.type) {
    /* keep the element's own key only when it has one: createElement turns key: null
       into the string "null", and unkeyed siblings sharing that key made React keep
       stale copies (e.g. a second bottom nav) in English */
    return React.createElement(wrapped, node.key != null ? { ...props, ...patch, key: node.key } : { ...props, ...patch });
  }
  return changed ? React.cloneElement(node, patch) : node;
}
function Localize({ children }) {
  return isEn() ? trNode(children) : children;
}

function Pill({ children, tone = T.muted, bg, icon: Icon, size = 11, strong }) {
  return (
    <span className="row" style={{
      gap: 4, fontSize: size, fontWeight: strong ? 800 : 700, color: tone,
      background: bg || "transparent", border: bg ? "none" : `1px solid ${tone}33`,
      padding: bg ? "3px 8px" : "2px 7px", borderRadius: R.pill, whiteSpace: "nowrap", lineHeight: 1.6,
    }}>
      {Icon && <Icon size={size + 1} strokeWidth={2.2} />}
      {children}
    </span>
  );
}

function Chip({ children, active, onClick, icon: Icon, tone = T.ink }) {
  return (
    <button className="press" onClick={onClick} aria-pressed={active ? "true" : "false"} style={{
      display: "inline-flex", alignItems: "center", gap: 6, padding: "7px 13px", borderRadius: R.pill,
      background: active ? T.deep : T.paper, color: active ? T.onDeep : tone,
      border: `1px solid ${active ? T.deep : T.line}`, fontSize: 13, fontWeight: 700, whiteSpace: "nowrap",
    }}>
      {Icon && <Icon size={14} strokeWidth={2.2} />}
      {children}
    </button>
  );
}

function SectionTitle({ title, sub, action, onAction, tone = T.ink }) {
  return (
    <div className="row" style={{ justifyContent: "space-between", alignItems: "flex-end", gap: 10, padding: "0 16px", marginBottom: 10 }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: 20, fontWeight: 800, color: tone, letterSpacing: "-.01em" }}>{title}</div>
        {sub && <div style={{ fontSize: 12.5, color: T.muted, marginTop: 3, lineHeight: 1.6 }}>{sub}</div>}
      </div>
      {action && <button className="press tap" onClick={onAction}
        style={{ fontSize: 12.5, fontWeight: 800, color: T.green, whiteSpace: "nowrap", minHeight: 36, paddingInline: 4 }}>{action}</button>}
    </div>
  );
}

function Divider({ m = 16 }) { return <div style={{ height: 1, background: T.lineSoft, margin: `${m}px 16px` }} />; }

function TrustChip({ state, small }) {
  const s = TRUST_STATE[state] || TRUST_STATE.insufficient;
  const Icon = s.icon;
  return (
    <span className="row" style={{
      gap: 4, fontSize: small ? 10.5 : 11.5, fontWeight: 700, color: s.tone,
      background: `${s.tone}14`, padding: small ? "2px 7px" : "3px 9px", borderRadius: R.pill, whiteSpace: "nowrap",
    }}>
      <Icon size={small ? 11 : 12.5} strokeWidth={2.4} />{s.label}
    </span>
  );
}

function FreshnessChip({ o, small }) {
  const { state } = useApp();
  const tr = objectTrust(o, state.resolved);
  if (!["conflicting", "possibly_stale"].includes(tr.state)) return null;
  return <TrustChip state={tr.state} small={small} />;
}

/* on a photo a chip sits on a solid light background, so its text stays legible on any image */
const ON_PHOTO_BG = "rgba(255,250,240,.94)";
function LifecycleChip({ o, onPhoto }) {
  const l = lifecycleOf(o);
  if (l === "active") return null;
  const tones = { live: T.clay, soon: T.brass, ending: T.warn, expired: T.warn, ended: T.muted, archived: T.muted, paused: T.muted, dormant: T.muted, upcoming: T.green };
  return <Pill tone={tones[l] || T.muted} bg={onPhoto ? ON_PHOTO_BG : `${tones[l] || T.muted}18`}>{LIFECYCLE_LABEL[l]}</Pill>;
}

function Toast({ msg, onDone }) {
  // the shell passes a fresh onDone on every render; keying the timer on it restarted
  // the countdown with each re-render, so a toast could linger over later screens
  const done = useRef(onDone); done.current = onDone;
  useEffect(() => { if (!msg) return; const t = setTimeout(() => done.current(), 2400); return () => clearTimeout(t); }, [msg]);
  if (!msg) return null;
  return (
    <div className="fade" data-toast style={{
      position: "absolute", insetInline: 24, bottom: 96, zIndex: 90, background: T.deep, color: T.onDeep,
      padding: "11px 15px", borderRadius: R.box, fontSize: 13, fontWeight: 600, textAlign: "center",
      boxShadow: "0 18px 40px rgba(20,16,10,.3)", lineHeight: 1.6,
    }}>{msg}</div>
  );
}

function Sheet({ open, onClose, title, children, tall }) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === "Escape") onClose && onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 95, display: "flex", alignItems: "flex-end" }}>
      <div className="scrimIn" onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(20,16,12,.46)" }} />
      <div className="sheetIn" style={{
        position: "relative", width: "100%", maxHeight: tall ? "92%" : "80%", display: "flex", flexDirection: "column",
        background: T.paper, borderTopLeftRadius: 24, borderTopRightRadius: 24, boxShadow: "0 -18px 50px rgba(20,16,10,.26)",
      }}>
        <div style={{ padding: "10px 16px 10px", flex: "0 0 auto" }}>
          <div style={{ width: 40, height: 4.5, borderRadius: 99, background: T.line, margin: "0 auto 12px" }} />
          <div className="row" style={{ justifyContent: "space-between", gap: 10 }}>
            <div className="clamp2" style={{ fontSize: 17.5, fontWeight: 800, lineHeight: 1.45 }}>{title}</div>
            <button className="press tap" onClick={onClose} aria-label="إغلاق"
              style={{ width: 32, height: 32, borderRadius: R.pill, display: "grid", placeItems: "center", background: T.limestone, color: T.muted, flex: "0 0 32px" }}>
              <X size={17} />
            </button>
          </div>
        </div>
        <div className="scroll" style={{ padding: `0 16px calc(28px + env(safe-area-inset-bottom, 0px))`, overflowY: "auto", overflowX: "clip", flex: 1 }}>
          {children}
        </div>
      </div>
    </div>
  );
}

function EmptyState({ icon: Icon = Compass, title, body, action, onAction }) {
  return (
    <div style={{ padding: "38px 26px", textAlign: "center" }}>
      <div style={{ width: 54, height: 54, borderRadius: 18, background: T.sand, display: "grid", placeItems: "center", margin: "0 auto 14px" }}>
        <Icon size={24} color={T.green} strokeWidth={1.8} />
      </div>
      <div style={{ fontSize: 16.5, fontWeight: 800, marginBottom: 6 }}>{title}</div>
      <div style={{ fontSize: 13.5, color: T.muted, lineHeight: 1.75 }}>{body}</div>
      {action && <button className="press" onClick={onAction} style={{ marginTop: 16, background: T.deep, color: T.onDeep, padding: "10px 18px", borderRadius: R.ctl, fontSize: 13.5, fontWeight: 800 }}>{action}</button>}
    </div>
  );
}

function Loading({ lines = 3 }) {
  return (
    <div style={{ padding: "0 16px" }}>
      <div className="shim" style={{ height: 150, borderRadius: R.media, marginBottom: 12 }} />
      {Array.from({ length: lines }).map((_, i) => (
        <div key={i} className="shim" style={{ height: 13, width: `${86 - i * 16}%`, borderRadius: 6, marginBottom: 9 }} />
      ))}
    </div>
  );
}

function Stars({ n = 0 }) {
  return <span className="row" style={{ gap: 2 }}>{Array.from({ length: 5 }).map((_, i) => <Star key={i} size={11} fill={i < n ? T.brass : "none"} color={T.brass} strokeWidth={1.6} />)}</span>;
}

/* Why-this — the explanation stays one short human sentence. */
function WhyThis({ reasons, inline }) {
  const [open, setOpen] = useState(false);
  if (!reasons?.length) return null;
  if (inline) return <div style={{ fontSize: 12, color: T.ok, fontWeight: 700 }}>{reasons[0]}</div>;
  return (
    <div style={{ marginTop: 8 }}>
      <button className="press row" onClick={() => setOpen(!open)} style={{ gap: 5, fontSize: 12, color: T.muted, fontWeight: 700 }}>
        <Sparkles size={12} color={T.brass} /> لماذا ظهر لك؟ {open ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
      </button>
      {open && (
        <ul className="up" style={{ margin: "7px 0 0", paddingInlineStart: 18, color: T.muted, fontSize: 12.5, lineHeight: 1.85 }}>
          {reasons.slice(0, 3).map((r, i) => <li key={i}>{r}</li>)}
          <li>يمكنك تعديل ما يتذكّره رحاب مكة من «حسابي».</li>
        </ul>
      )}
    </div>
  );
}

/* Object metadata line — type · area · timing · distance */
function MetaLine({ o, showDistance, lines = 2 }) {
  const { state } = useApp();
  const bits = [];
  bits.push(o.typeLabel);
  if (NB[o.neighborhood]) bits.push(NB[o.neighborhood].name);
  const tl = timingLabel(o);
  if (tl) bits.push(tl);
  const home = NB[state.profile.nb];
  if (showDistance && home && o.neighborhood !== state.profile.nb) { const km = distanceKm(o, home); bits.push(tx(`~${ar(km)} كم من ${home.name}`, `~${km} km from ${D(home.name)}`)); }
  if (priceLabel(o)) bits.push(priceLabel(o));
  return <div className={lines === 3 ? "clamp3" : "clamp2"} style={{ fontSize: 11.5, color: T.muted, fontWeight: 600, lineHeight: 1.6 }}>{Dj(bits)}</div>;
}

/* ───────── Object presentations ─────────
   Photography leads. Text sits on or beside the image. Not every block is a card. */

function SaveButton({ o, size = 18, onDark }) {
  const { state, dispatch, toast } = useApp();
  const on = !!state.saved[o.id];
  return (
    <button className="press tap" aria-label={on ? "إزالة من المحفوظات" : "حفظ"}
      onClick={(e) => { e.stopPropagation(); dispatch({ type: "save", obj: o.id }); toast(on ? "أزلناه من المحفوظات" : "حُفظ — الحفظ لا يعني حجزًا أو انضمامًا"); }}
      style={{
        width: size + 16, height: size + 16, borderRadius: R.pill, display: "grid", placeItems: "center",
        background: onDark ? "rgba(20,16,12,.42)" : T.paper, border: onDark ? "none" : `1px solid ${T.line}`,
        color: on ? T.brass : onDark ? "#F6EFE0" : T.muted, backdropFilter: onDark ? "blur(4px)" : "none",
      }}>
      {on ? <BookmarkCheck size={size} strokeWidth={2.2} /> : <Bookmark size={size} strokeWidth={2} />}
    </button>
  );
}

function PlanStateChip({ o, onPhoto }) {
  const { state } = useApp();
  const item = state.plan.find((p) => p.obj === o.id);
  if (!item) return null;
  const s = PLAN_STATE[item.state];
  const Icon = s.icon;
  return <Pill tone={s.tone} bg={onPhoto ? ON_PHOTO_BG : `${s.tone}16`} icon={Icon}>{s.label}</Pill>;
}

