      <div style={{ marginTop: 4 }}><MetaLine o={o} lines={3} /></div>
      {x.why?.length ? <div className="clamp2" style={{ fontSize: 11.5, color: T.ok, fontWeight: 700, marginTop: 4, lineHeight: 1.55 }}>{x.why[0]}</div> : null}
