function cityAsk(n, E) {
  const offer = E.offer.length > 0;
  if (/(^| )(طلباتي|my requests?)( |$)|what have i requested|الطلبات اللي سجلتها|وين طلبي/.test(n)) return "city_my_requests";
  if (/(استثمار|استثماري|استثماريه|استثمر|نستثمر|مستثمر|فرص (ال)?اعمال|فرصه تجاريه|فرص تجاريه|مشروع تجاري|مشاريع تجاريه|شراكه تجاريه|افتح (مقهي|كافيه|مطعم|محل|متجر|مشروع)|invest|business opportunit|business partnership|open an? (cafe|coffee shop|restaurant|shop|store|business)|start an? business)/.test(n)) return "city_invest";
  if (/(سياره|سيارات|(^| )car( |$)|cars|bike|دراجه)/.test(n)) return null;
  if (!offer && (/(للايجار|ايجار|استاجر|نستاجر|للبيع|تمليك|للتمليك|فيلا|فلل|عقار|عقارات|اسكن في مكه|نسكن في مكه|اعيش في مكه|نعيش في مكه|انتقل (الي |ل)?مكه|ننتقل (الي |ل)?مكه|سكن دائم|اقامه ممتده|اقامه طويله|for rent|to rent|renting|rent an? |for sale|real estate|villa|live in makkah|move to makkah|moving to makkah|relocat|extended stay|long stay|longer stay)/.test(n)
      || (/(^| )(اشتري|نشتري|buy)( |$)/.test(n) && /(^| )(ال)?(شقه|بيت|ارض|apartment|flat|house|home|land)( |$)/.test(n))
      || (/(مفروشه|مفروش|furnished)/.test(n) && /(شهر|اشهر|شهري|شهور|monthly|months?|long|longer)/.test(n)))) return "city_housing";
  if (/(افتح السوق|تبويب السوق|سوق رحاب مكه|سوق التطبيق|(وش|ايش|شو) (في|فيه) السوق|اشرح (لي )?السوق|what s in the market|open the market|the market tab|market tab|explain the market|in the market)/.test(n)) return "market_overview";
  if (/(اطلب (ال)?خدمه|طلب (ال)?خدمه|كيف اطلب|request a service|order a service)/.test(n)) return "market_services";
  if (!offer && ((MK_BUY.test(n) && MK_PRODUCT.test(n)) || MK_GIFT.test(n))) return "market_products";
  return null;
}

/* one turn: text in, answer out (actions are dispatched here, through the app's reducer) */
function agentTurn(text, env) {
  const { state, ctx, dispatch } = env;
  const S = AGENT_SESSION.mem;
  const q = AGENT.prep(text);
  const lang = q.lang;
  const T2 = (a, e) => (lang === "en" ? e : a);
  const E = AGENT.entitiesOf(q);
  S.turn += 1;
  /* several branches of one chain: the one nearest the person's area comes first */
  if (E.brand && ctx.nb && NB[ctx.nb]) E.objects.sort((a, b) => distanceKm(getObj(a), NB[ctx.nb]) - distanceKm(getObj(b), NB[ctx.nb]));

  /* ── intent matching ── */
  const hasQuery = !!S.lastQuery, hasRanked = S.ranked.length > 0;
  const reqOK = (it) => !it.req || it.req.every((r) =>
    r === "last_intent" ? !!S.lastIntent : r === "last_result" ? !!(S.lastObject || hasRanked || S.lastShape) : r === "last_ranked_results" ? hasRanked : true);
  let scored = AGENT.INTENTS.map((it) => {
    let s = AGENT.scoreIntent(it, q);
    if (!reqOK(it)) s *= 0.5;
    return { it, s };
  }).sort((a, b) => b.s - a.s);
  /* «فرص مكة» answers only requests that are about it (cityAsk), never a lookalike sentence */
  const cityId = cityAsk(q.n, E);
  if (!cityId) scored = scored.filter((x) => x.it.c !== "opportunities");
  let pick = scored[0];
  const words = q.t.length;
  /* "أبغى …" / "I want …" opens a new request, however short */
  const newRequest = /^(ابغي|ابغا|ابي|بغيت|ودي|عطني|وريني|i want|i'd like|id like|show me|find me|find|any)( |$)/.test(q.n);
  const referential = !newRequest && (words <= 4 || /^(و|طيب|طب|وش عن|طيب وش|and|what about|how about|ok|okay|so)( |$)/.test(q.n));
  const force = (id) => ({ it: AGENT.BY_ID[id], s: 0.9 });

  /* explicit context/refinement on a short turn reuses the previous task */
  const weakAction = pick.it.t === "action" && !E.actions.length && pick.s < 0.8;
  if (hasQuery && referential && pick.s < 0.8 && (!["action", "fixed"].includes(pick.it.t) || weakAction) || (hasQuery && referential && pick.it.c === "conversation_context")) {
    if (E.ordinal === 1 && !E.actions.length) pick = force("followup_second_result");
    else if (E.ordinal === 2 && !E.actions.length) pick = force("followup_third_result");
    else if (E.nb && pick.it.c !== "conversation_context" && !agentKeyword(q.n)) pick = force("followup_area_change_repeat");
    else if (E.time && pick.it.c !== "conversation_context") pick = force("followup_time_change_repeat");
    else if (E.offer.length && !E.actions.length && pick.it.id !== "offers_terms_details") pick = force("followup_with_offer");
    else if (E.types.length && pick.it.c !== "conversation_context") pick = force("followup_category_only");
    else if (E.suit.includes("family") || E.party === "family") pick = force("followup_family_only");
    else if (E.suit.includes("kids") || E.party === "kids") pick = force("followup_kids_only");
  }
  /* persona and phrasing overrides — the bank matched the words, these fix the task */
  const FOOD_WORDS = /(مطعم|مطاعم|اكل|غدا|عشا|فطور|قهوه|كافيه|مقهي|جوعان|restaurant|food|eat|lunch|dinner|breakfast|cafe|coffee)/;
  if (agentKeyword(q.n) === "walk" && !E.actions.length) pick = force("activities_sport_walk");
  else if (E.nb && /^food_/.test(pick.it.id) && !FOOD_WORDS.test(q.n)) pick = force("area_specific_discovery");
  if (/(يوم واحد|يوم وحد|يوم بس|one day|a day in makkah|1 day)/.test(q.n) && !E.actions.length) pick = force("visitor_half_day");
  /* "near me" phrasing is a proximity request, whatever else the bank matched */
  if (/(near me|nearby|close to me|around me|قريب مني|قريبه مني|جنبي|حولي)/.test(q.n) && !/(جديد|new)/.test(q.n) && !E.offer.length && !E.actions.length && !E.objects.length) pick = force("discover_nearby");
  /* an offers intent without any offer word is a request for the thing itself */
  if (/^offers_/.test(pick.it.id) && !E.offer.length) pick = force(E.suit.includes("kids") || E.party === "kids" ? "family_kids" : E.suit.includes("family") || /عائل|family/.test(q.n) ? "family_general" : "discover_what_to_do_now");
  /* naming a kind of place ("حدائق", "museum") starts a new search rather than repeating the last one */
  if (agentKeyword(q.n) && /^followup_(area_change_repeat|category_only|time_change_repeat|repeat|kids_only|family_only)/.test(pick.it.id)) pick = force(E.nb ? "area_specific_discovery" : "discover_what_to_do_now");
  /* an action verb with a referent wins over lookalike discovery phrasing */
  const actionIntent = scored.find((x) => x.it.t === "action" && x.s > 0.42 && x.it.c !== "user_context");
  if (actionIntent && (E.actions.length || (actionIntent.s >= 0.62 && pick.it.c !== "conversation_context")) && (E.ordinal != null || E.objects.length || S.lastObject || hasRanked) && actionIntent.s > pick.s - 0.12) pick = actionIntent;
  /* "this offer — is it for families?" asks about the offer on the table, not for a new list */
  if (E.offer.length && (S.lastOffer || S.lastObject) && /(^| )(هذا|هذي|ذا|ذي|this|that)( |$)/.test(q.n) && !E.actions.length) pick = force("offers_terms_details");
  /* "what's in my plan" is the plan itself, not an explanation of the feature */
  if (pick.it.id === "app_plan_help" && /(^| )(في|فيها|عندي|have|in|on)( |$)/.test(q.n) && !/(فايده|فائده|اشرح|يعني|explain|what is|how)/.test(q.n)) pick = force("plan_summary");
  /* "what does the community say" about the thing we're discussing */
  if (["app_community_help", "community_active_discussions"].includes(pick.it.id) && (E.objects.length || S.lastObject || hasRanked) && /(يقول|يقولون|تقول|رأي|راي|say|saying|think)/.test(q.n)) pick = force("community_what_people_say");
  /* a request that only names a place or a chain ("أبغى مكتبة جرير", "I want Starbucks") is about
     that place — not a theme its letters happen to resemble ("جرير" is not «جري»), and not an
     action nobody asked for */
  const ASK_WORDS = new Set([...["ابغي", "ابغا", "ابي", "بغيت", "ودي", "وين", "فين", "اقرب", "عطني", "وريني", "دلني", "معلومات", "عن", "وش", "ايش", "هو", "هي", "تعرف", "اعرف",
    "want", "find", "where", "show", "nearest", "closest", "like", "id", "i'd", "looking", "go", "tell", "about", "info", "information", "what", "know"].flatMap((w) => AGENT.toks(AGENT.norm(w)))]);
  let placeAsk = false;    // the person named a place: answer about it (placeAnswer)
  const onlyNames = E.objects.length > 0 && E.objDistinct && [...q.ts].every((t) => E.objTokens.has(t) || ASK_WORDS.has(t));
  if (onlyNames && !E.actions.length && !E.offer.length && E.ordinal == null
    && !["community", "plan", "offers"].includes(pick.it.c) && !(pick.it.t === "action" && pick.s >= 0.8)) { pick = force("followup_more_detail"); placeAsk = true; }
  /* a named kind of place ("أبغى مول", "a museum") is a search for that kind, not a food or sport theme */
  const kindAsked = agentKeyword(q.n);
  if (kindAsked && kindAsked !== "walk" && !E.objects.length && !E.actions.length && !E.offer.length && !FOOD_WORDS.test(q.n)
    && /^(food_|cafe_|activities_)/.test(pick.it.id)) pick = force(E.nb ? "area_specific_discovery" : ({ museum: "places_cultural", exhibition: "places_cultural", books: "places_market_shopping", mall: "places_market_shopping", grocery: "places_market_shopping" })[kindAsked] || "discover_what_to_do_now");
  /* asking for somewhere to stay ("Where can I stay near the Haram?", «أبغى سكن قريب من الحرم») is
     a search for stays in either language — not a shopping theme or a change of your own area */
  if (E.types.includes("stay") && !E.objects.length && !E.actions.length && !E.offer.length && !/(^| )(انا|i'm|im|i am)( |$)/.test(q.n))
    { E.types = ["stay"]; pick = force("discover_what_to_do_now"); }   // "a place to stay" is a stay, not a place
  /* "what do people say about …" is the community's view of that thing */
  if (/(يقول|يقولون|تقول|say|saying)/.test(q.n) && /(الناس|ناس|المجتمع|people|others|community)/.test(q.n) && (E.objects.length || S.lastObject) && !E.actions.length) pick = force("community_what_people_say");
  /* «فرص مكة»: homes, business opportunities, my requests */
  if (cityId && !E.actions.filter((a) => a !== "open").length && E.ordinal == null) { placeAsk = false; pick = force(cityId); }
  /* nothing matched but the text names things: build discovery from the entities */
  if (pick.s < 0.34) {
    if (E.objects.length) { pick = force("followup_more_detail"); placeAsk = true; }
    else if (E.offer.length) pick = force("offers_all_active");
    else if (E.types.length || E.cats.length || E.suit.length || E.nb) pick = force(E.nb && !E.types.length ? "area_specific_discovery" : "discover_what_to_do_now");
    else pick = force(q.t.length <= 1 && q.n.length <= 3 ? "fallback_spelling_noise" : "fallback_unclear");
  }
  const it = pick.it;
  const h = it.h;
  const msg = { role: "agent", text: "", cards: [], shape: it.s || null, intent: it.id };
  const say = (vars = {}, variant) => {
    const rs = (it.r[lang] && it.r[lang].length ? it.r[lang] : it.r.ar) || [""];
    let t = rs[variant ?? (S.turn % rs.length)];
    t = t.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] != null && vars[k] !== "" ? vars[k] : "—"));
    return t.replace(/\s+([.،,])/g, "$1");
  };
  const nameOf = (o) => (lang === "en" ? (EN_TXT[o.n] || enText(o.n) || o.n) : o.n);
  const names = (ids) => ids.map((id) => nameOf(getObj(id))).join(lang === "en" ? ", " : "، ");
  const referent = () => {
    if (E.ordinal != null) return S.ranked[E.ordinal] ? getObj(S.ranked[E.ordinal]) : null;
    if (E.objects.length) return getObj(E.objects[0]);
    if (S.lastObject) return getObj(S.lastObject);
    if (S.ranked.length === 1) return getObj(S.ranked[0]);
    return null;
  };
  const ambiguous = () => S.ranked.length > 1 && E.ordinal == null && !E.objects.length && !S.lastObject;
  const noOrdinal = () => {
    msg.text = S.ranked.length
      ? T2(`آخر نتيجة فيها ${ar(Math.min(3, S.ranked.length))} فقط — ما فيه خيار بهذا الترتيب.`, `The last answer only had ${Math.min(3, S.ranked.length)} — there's no option at that position.`)
      : T2("ما عندي قائمة سابقة أرتّب منها. قل لي وش تدوّر عليه أولًا.", "I don't have a previous list to pick from. Tell me what you're looking for first.");
    msg.clarify = true; return msg;
  };
  const clarify = () => {
    msg.text = T2(`تقصد أي واحد؟ اكتب «الأول» أو «الثاني» أو اسم المكان — عندي ${ar(Math.min(3, S.ranked.length))} خيارات من آخر نتيجة.`,
      `Which one do you mean? Say "the first", "the second" or the name — I have ${Math.min(3, S.ranked.length)} options from the last answer.`);
    msg.clarify = true;
    return msg;
  };
  const finishList = (items, query, vars = {}, opts = {}) => {
    const shown = items.slice(0, opts.n || 3);
    S.lastQuery = query; S.ranked = items.slice(0, 8).map((x) => x.id); S.shown = shown.map((x) => x.id); S.offset = 0;
    S.lastObject = shown.length === 1 ? shown[0].id : null; S.lastShape = "ranked_list";
    const offerFirst = shown.find((x) => offerFor(x.id)); S.lastOffer = query.offer && offerFirst ? offerFor(offerFirst.id).id : S.lastOffer;
    if (!shown.length) {
      msg.text = query.offer
        ? T2("ما فيه عرض نشط في بيانات رحاب مكة يطابق طلبك بهذا الشكل. جرّب منطقة أخرى أو شرطًا أخف.", "No active offer in Rihab Makkah matches that request. Try another area or a looser condition.")
        : T2("ما لقيت شيئًا يطابق كل هذه الشروط في المحتوى الحالي. جرّب شرطًا أخف أو منطقة أخرى.", "Nothing in the current content matches all of that. Try a looser condition or another area.");
      msg.empty = true;
      return msg;
    }
    const list = names(shown.map((x) => x.id));
    if (query.sort === "near" && !agentFrom(query, ctx)) {
      /* proximity was asked for, but no area is known — say so instead of claiming nearness */
      msg.text = T2(`ما أعرف حيّك أو منطقتك بعد، فهذه أنسب الخيارات لك وليست مرتّبة حسب القرب: ${list}. قل لي الحي — مثل «بالعزيزية» — وأرتّبها بالقرب منه.`,
        `I don't know your neighbourhood or area yet, so these are the best fits rather than the closest: ${list}. Tell me the area — for example "in Al-Aziziyah" — and I'll sort them by distance from it.`);
      msg.cards = shown.map((x) => ({ id: x.id, why: x.why }));
      msg.shape = query.offer ? "offer" : "ranked_list";
      return msg;
    }
    msg.text = say({ recommendations: list, offers: list, ranked_results: list, result: list, neighborhood: query.nb ? NB[query.nb].name : NB[ctx.nb]?.name, category: vars.category, time_context: vars.time_context, current_item: vars.current_item, previous_entity: vars.previous_entity, community: vars.community, ...vars });
    if (opts.lead) msg.text = opts.lead + " " + msg.text;
    msg.cards = shown.map((x) => ({ id: x.id, why: x.why }));
    msg.shape = query.offer ? "offer" : "ranked_list";
    return msg;
  };
  const runList = (query, vars, opts) => {
    const { items, relaxed } = runAgentQuery(query, ctx, state);
    let lead = opts?.lead || "";
    if (relaxed === "area") lead = T2(`ما لقيت في ${NB[query.nb].name} نفسها؛ هذه الأقرب لها.`, `Nothing in ${NB[query.nb].name} itself; these are the closest.`);
    if (!items.length && (query.suit?.length || query.suitAny?.length) && !query.offer) {
      const loose = runAgentQuery({ ...query, suit: [], suitAny: null }, ctx, state);
      if (loose.items.length) return finishList(loose.items, { ...query, suit: [] }, vars, { lead: T2("ما فيه خيار يذكر كل الشروط صراحةً؛ هذه أقرب البدائل:", "Nothing states every condition explicitly; these are the closest alternatives:") });
    }
    return finishList(items, query, vars, { ...opts, lead });
  };
  const outing = (hours, around) => {
    const c2 = around ? { ...ctx, planNeighborhoods: [around.neighborhood] } : ctx;
    const outs = buildOutings(c2, state, hours);
    const out = outs[0];
    if (!out) { msg.text = T2("ما قدرت أركب مسارًا من المحتوى الحالي يناسب وقتك. جرّب وقتًا أطول أو منطقة أخرى.", "I couldn't assemble a route from current content for your time. Try a longer window or another area."); return msg; }
    S.lastOuting = out.objects.map((o) => o.id); S.ranked = S.lastOuting; S.lastObject = null; S.lastShape = "composed_plan";
    msg.text = say({ outing_steps: out.objects.map((o, i) => `${ar(i + 1)}. ${nameOf(o)}`).join(lang === "en" ? " → " : " ← "), total_time: minutesAr(out.minutes), object: around ? nameOf(around) : "" });
    msg.outing = { ids: S.lastOuting, minutes: out.minutes };
    msg.shape = "composed_plan";
    return msg;
  };
  const objCard = (o, why) => { msg.cards = [{ id: o.id, why: why || [] }]; };
  /* A named place, answered from what the app holds about it: what and where it is, whether
     it is open or when it next happens, length, price, a running offer, what it is like,
     what the community has said and where it stands in the plan. The card under the
     answer carries the actions (details, save, plan, join or book, directions). A chain
     lists its branches, nearest first when the area is known. */
  /* every part of a place answer is read in the language the question was asked in */
  const inLang = (fn) => { const cur = isEn() ? "en" : "ar"; if (cur === lang) return fn(); setLang(lang); try { return fn(); } finally { setLang(cur); } };
  const placeAnswer = () => inLang(() => {
    const ids = E.objects.filter((id) => getObj(id));
    if (!ids.length) return null;
    const sep = lang === "en" ? ", " : "، ";
    if (E.brand && ids.length > 1) {
      const branches = ids.map(getObj);
      const shown = branches.slice(0, 3);
      const brandName = lang === "en" ? (EN_TXT[shown[0].n] || shown[0].n).split(" — ")[0] : E.brand;
      const where = (o) => `${nameOf(o)} (${NB[o.neighborhood]?.name || ""})`;
      const near = ctx.nb && NB[ctx.nb];
      msg.text = T2(
        `${brandName}: ${countAr(branches.length, "فرع واحد", "فرعان", "فروع", "فرعًا")} في رحاب مكة. ${near ? `الأقرب إلى ${NB[ctx.nb].name}` : "منها"}: ${shown.map(where).join(sep)}. افتح الفرع اللي يناسبك للتفاصيل والاتجاهات.`,
        `${brandName}: ${branches.length} ${branches.length === 1 ? "branch" : "branches"} in Rihab Makkah. ${near ? `Nearest to ${D(NB[ctx.nb].name)}` : "Including"}: ${shown.map(where).join(sep)}. Open the one that suits you for details and directions.`);
      msg.cards = shown.map((o) => ({ id: o.id, why: [] }));
      S.ranked = branches.map((o) => o.id); S.shown = shown.map((o) => o.id); S.lastObject = null; S.lastShape = "ranked_list";
      msg.shape = "ranked_list";
      return msg;
    }
    const o = getObj(ids[0]);
    S.lastObject = o.id; S.ranked = [o.id]; S.shown = [o.id]; S.lastShape = "single_entity";
    const life = lifecycleOf(o), next = nextOccurrence(o), open = isOpenNow(o), of = offerFor(o);
    const kind = o.typeLabel;
    const status = ["ended", "archived", "expired"].includes(life) ? T2("انتهى", "it has ended")
      : life === "paused" ? T2("متوقف مؤقتًا", "paused for now") : life === "dormant" ? T2("غير نشط حاليًا", "not active at the moment")
      : life === "live" ? T2("جارٍ الآن", "happening now")
      : next ? T2(`الموعد القادم ${dayLabelAr(next)} ${clockAr(next)}`, `next: ${dayLabelAr(next).replace(/^(Today|Tomorrow)\b/, (x) => x.toLowerCase())} ${clockAr(next)}`)
      : open === true ? T2("مفتوح الآن", "open now") : open === false ? T2("مغلق الآن", "closed now") : null;
    const facts = [status, o.duration && o.timing?.kind !== "hours" ? minutesAr(o.duration) : null, priceLabel(o)].filter(Boolean);
    const contribs = contributionsFor(o.id, state).filter((k) => k.type !== "question").length;   // experiences, not questions
    const pi = state.plan.find((p) => p.obj === o.id && !["cancelled"].includes(p.state));
    const parts = [
      `${nameOf(o)}: ${[kind, NB[o.neighborhood] && !nameOf(o).includes(NB[o.neighborhood].name) ? (lang === "en" ? D(NB[o.neighborhood].name) : NB[o.neighborhood].name) : null, ...facts].filter(Boolean).join(" — ")}.`,
      o.ab ? D(o.ab) : null,
      of ? T2(`عليه عرض: ${L2(of.badge)} (${offerExpiry(of)}).`, `Offer: ${L2(of.badge)} (${offerExpiry(of)}).`) : null,
      contribs ? T2(`في المجتمع ${countAr(contribs, "تجربة واحدة", "تجربتان", "تجارب", "تجربة")} عنه.`, `The community has ${plural(contribs, "experience")} of it.`) : null,
      pi ? T2(`في خطتك: ${D(PLAN_STATE[pi.state].label)}.`, `In your plan: ${D(PLAN_STATE[pi.state].label)}.`) : null,
    ].filter(Boolean);
    msg.text = parts.join(" ").replace(/\.\./g, ".");
    objCard(o); msg.shape = "single_entity";
    return msg;
  });
  S.lastIntent = it.id; S.lastEntities = E;

  /* the hours or the price of a named place: answered from its own data, never guessed */
  const asksHours = /(يفتح|يقفل|يسكر|يغلق|دوام|ساعات|اوقات|مواعيد|\bopen|clos(e|ing)|hours)/.test(q.n) || (E.objects.length > 0 && /(^| )(متي|when)( |$)/.test(q.n));
  const asksPrice = /(سعر|اسعار|بكم|كم يكلف|كم سعر|price|cost|how much)/.test(q.n);
  if ((asksHours || asksPrice) && !E.offer.length && (E.objects.length || S.lastObject)) {
    const r = referent();
    if (r) return inLang(() => {
      S.lastObject = r.id; objCard(r);
      const of = offerFor(r), op = of ? offerPrice(of) : null;
      const hm = (h) => clockAr(new Date(Date.UTC(2026, 0, 1, Math.floor(h) % 24, Math.round((h % 1) * 60)) - TZ));
      if (asksPrice) {
        msg.text = r.priceOnRequest ? T2(`سعر ${nameOf(r)} يحدده مقدّم الخدمة حسب ما تحتاجه. تقدر تتواصل معه من صفحته.`, `${nameOf(r)}'s price comes from the provider, depending on what you need. You can contact them from its page.`)
          : r.price === 0 ? T2(`${nameOf(r)} بدون رسوم.`, `${nameOf(r)} is free.`)
          : r.price != null ? T2(`${nameOf(r)}: ${priceLabel(r)}.`, `${nameOf(r)}: ${priceLabel(r)}.`)
          : T2(`ما عندي أسعار ${nameOf(r)}. الأفضل تسأل المكان مباشرة.`, `I don't have prices for ${nameOf(r)}. Best to ask the place directly.`);
        if (of) msg.text += " " + T2(`وعليه عرض: ${L2(of.badge)}${op ? ` — ${ar(op.now)} ريال بدل ${ar(op.was)}${op.pkg ? " " + PKG_NOTE[0] : ""}` : ""} (${offerExpiry(of)}).`, `There's an offer: ${L2(of.badge)}${op ? ` — SAR ${op.now} instead of ${op.was}${op.pkg ? " " + PKG_NOTE[1] : ""}` : ""} (${offerExpiry(of)}).`);
        return msg;
      }
      const tm = r.timing, next = nextOccurrence(r), open = isOpenNow(r);
      msg.text = tm?.kind === "hours"
        ? (tm.open === 0 && tm.close >= 24 ? T2(`${nameOf(r)} مفتوح على مدار الساعة.`, `${nameOf(r)} is open around the clock.`)
          : T2(`${nameOf(r)} يفتح من ${hm(tm.open)} إلى ${hm(tm.close)} — ${open ? "مفتوح الآن" : "مغلق الآن"}.`, `${nameOf(r)} opens ${hm(tm.open)} to ${hm(tm.close)} — ${open ? "open now" : "closed now"}.`))
        : lifecycleOf(r) === "live" ? T2(`${nameOf(r)} جارٍ الآن.`, `${nameOf(r)} is happening now.`)
        : ["ended", "archived", "expired"].includes(lifecycleOf(r)) ? T2(`${nameOf(r)} انتهى.`, `${nameOf(r)} has ended.`)
        : ["paused", "dormant"].includes(lifecycleOf(r)) ? T2(`${nameOf(r)} متوقف حاليًا، ولا يوجد لقاء قادم.`, `${nameOf(r)} is paused, with no upcoming meeting.`)
        : next ? T2(`موعد ${nameOf(r)} القادم: ${whenAr(next)}.`, `${nameOf(r)} is next on ${whenMid(next)}.`)
        : T2(`ما عندي ساعات عمل ${nameOf(r)}. الأفضل تسأل المكان مباشرة قبل ما تروح.`, `I don't have opening hours for ${nameOf(r)}. Best to ask the place directly before you go.`);
      return msg;
    });
  }

  /* "near me" with no area given anywhere: we don't know and don't guess */
  if (it.h === "recommend_nearby" && !E.nb && !ctx.nb) {
    msg.text = T2("ما أعرف وين أنت الآن، ولا نستخدم موقعك المباشر. قل لي المنطقة — مثل «أنا في أجياد» أو «قرب الحرم» أو «في العزيزية» — وأرتّب لك ما حولها.",
      "I don't know where you are right now, and we don't use your live location. Tell me the area — for example \"I'm in Ajyad\", \"near the Haram\" or \"in Al-Aziziyah\" — and I'll line up what's around it.");
    msg.clarify = true; return msg;
  }
  /* what's new — only what has a basis for being new: a coming date, a recent post,
     or a real place added in Rihab Makkah's latest update */
  if (/(^| )(وش |ايش |شو )?(ال)?جديد( |$)|what'?s new|anything new|new around|new near/.test(q.n) && !E.offer.length) {
    const P = personaOf(state.profile);
    const nbq = E.nb || ctx.nb;
    const area = NB[nbq];
    const near = (o) => !area || o.neighborhood === nbq || distanceKm(o, area) < 3;
    const pool = INVENTORY.filter((o) => isPromotable(o) && o.type !== "offer" && near(o));
    const soon = rank(pool.filter((o) => ["event", "activity", "recurring"].includes(o.type) && happensThisWeek(o)), { ...ctx, nb: nbq }, { limit: 3, maxPerCategory: 2, maxPerNeighborhood: 3 });
    const added = rank(pool.filter((o) => o.venue), { ...ctx, nb: nbq }, { limit: 3, maxPerCategory: 1, maxPerNeighborhood: 3 });
    const items = [...soon.map((x) => ({ id: x.o.id, why: [T2(`قادم ${whenAr(nextOccurrence(x.o))}`, `Coming up ${whenMid(nextOccurrence(x.o))}`)] })),
      ...added.map((x) => ({ id: x.o.id, why: [T2("جديد على رحاب مكة", "New on Rihab Makkah")] }))];
    S.lastQuery = { nb: nbq }; S.ranked = items.map((x) => x.id); S.shown = items.slice(0, 4).map((x) => x.id); S.lastObject = null; S.lastShape = "ranked_list";
    if (!items.length) { msg.text = T2("ما عندي جديد مؤكد حولك الآن. أعرض لك ما يحدث هذا الأسبوع؟", "I don't have anything confirmed as new around you right now. Shall I show what's on this week?"); msg.clarify = true; return msg; }
    msg.text = T2(`الجديد ${area ? `حول ${area.name}` : "في مكة"}: ${names(items.slice(0, 4).map((x) => x.id))}. ${P === "visitor" ? "تقدر تضيف أي واحد لرحلتك." : "القادم بمواعيده، والأماكن أُضيفت في آخر تحديث للتطبيق — ولا نسمّي شيئًا «جديدًا» بلا أساس."}`,
      `New ${area ? `around ${D(area.name)}` : "in Makkah"}: ${names(items.slice(0, 4).map((x) => x.id))}. ${P === "visitor" ? "You can add any of them to your trip." : "Upcoming items show their dates; the places were added in the app's latest update — nothing is called new without a reason."}`);
    msg.cards = items.slice(0, 4); msg.shape = "ranked_list";
    return msg;
  }
  /* "a cultural experience and then a restaurant": compose the two, the second close to the first */
  const thenMatch = q.n.match(/^(.*?)(?: و?بعدها | و?بعده | ثم | وبعد كذا | then | after that | followed by )(.*)$/);
  if (thenMatch && FOOD_WORDS.test(thenMatch[2]) && !FOOD_WORDS.test(thenMatch[1])) {
    const first = thenMatch[1];
    const cats = /(ثقاف|تاريخ|تراث|متحف|معرض|cultur|histor|heritage|museum)/.test(first) ? ["culture", "heritage"]
      : /(سوق|اسواق|تسوق|market|shop)/.test(first) ? ["market"] : /(طبيعه|جبل|مشي|nature|walk|hike)/.test(first) ? ["nature", "heritage", "sport"] : null;
    const a1 = rank(INVENTORY.filter((o) => isPromotable(o) && o.type !== "offer" && (cats ? cats.includes(o.category) : ["experience", "place"].includes(o.type) && !["food", "cafe", "stay", "services"].includes(o.category))), ctx, { limit: 6, maxPerCategory: 6 })[0];
    if (a1) {
      const o1 = a1.o;
      const food = INVENTORY.filter((o) => isPromotable(o) && ["food", "cafe"].includes(o.category) && o.type !== "offer").sort((x, y) => distanceKm(x, o1.geo) - distanceKm(y, o1.geo) || (y.real - x.real));
      const o2 = food[0];
      if (o2) {
        S.lastOuting = [o1.id, o2.id]; S.ranked = S.lastOuting; S.lastObject = null; S.lastShape = "composed_plan"; S.lastQuery = { cats };
        msg.text = T2(`رتبتها لك بهذا الترتيب: ١. ${nameOf(o1)} ← ٢. ${nameOf(o2)} — الثاني من أقرب أماكن الأكل للأول تقريبًا (${NB[o2.neighborhood]?.name || "مكة"}). ${o2.real ? "لم نتحقق من ساعات المطعم؛ راجعها قبل الذهاب." : ""}`,
          `Here's the order: 1. ${nameOf(o1)} → 2. ${nameOf(o2)} — the second is one of the closest places to eat to the first (roughly, ${D(NB[o2.neighborhood]?.name || "Makkah")}). ${o2.real ? "We haven't verified the restaurant's hours; check before you go." : ""}`).trim();
        msg.cards = [{ id: o1.id, why: a1.why || [] }, { id: o2.id, why: [] }];
        msg.outing = { ids: S.lastOuting, minutes: (o1.duration || 60) + (o2.duration || 45) };
        msg.shape = "composed_plan";
        return msg;
      }
    }
  }

  /* ── handlers ── */
  if (it.t === "fixed") {
    msg.text = say();
    if (/^fallback|frustration|acknowledgement_no/.test(it.id)) msg.clarify = true;
    return msg;
  }
  switch (h) {
    case "city_answer": return inLang(() => {
      /* «فرص مكة»: each answer names what is there and links to the screen; every request stays
         on the device, and nothing is said about money for an opportunity */
      const KEPT = T2("تقدر تعدّل أي طلب أو تسحبه من «طلباتي».", "You can edit or withdraw any of them in My requests.");
      const join = (xs) => xs.join(lang === "en" ? ", " : "، ");
      const titles = (kind, ids) => join(ids.map((id) => requestTarget(kind, id)?.title).filter(Boolean));
      S.lastObject = null; S.ranked = []; S.lastQuery = null; S.lastShape = "city"; msg.shape = "city";
      if (it.id === "city_my_requests") {
        const rs = state.requests || [];
        if (!rs.length) {
          msg.text = T2("ما سجّلت أي طلب بعد. تقدر تطلب منتجًا أو خدمة من «السوق»، أو تسجّل اهتمامك بسكن أو فرصة في «فرص مكة»، وتلقاه في «طلباتي».", "You haven't recorded any requests yet. You can request a product or a service in the Market, or register interest in a home or an opportunity in Makkah Opportunities, and find it in My requests.");
          msg.links = [{ label: T2("افتح فرص مكة", "Open Makkah Opportunities"), to: { s: "city", tab: "live" } }]; return msg;
        }
        msg.text = T2(`في «طلباتي» ${countAr(rs.length, "طلب واحد", "طلبان", "طلبات", "طلبًا")}: ${join(rs.map((r) => requestTarget(r.kind, r.ref)?.title).filter(Boolean))}. ${KEPT}`,
          `You have ${rs.length === 1 ? "one request" : `${rs.length} requests`} in My requests: ${join(rs.map((r) => requestTarget(r.kind, r.ref)?.title).filter(Boolean))}. ${KEPT}`);
        msg.links = [{ label: T2("افتح طلباتي", "Open my requests"), to: { s: "requests" } }]; return msg;
      }
      if (it.id === "market_overview") {
        msg.text = T2("«السوق» فيه ثلاثة أقسام: «التجارب» للجولات والورش والفعاليات وتُحجز أو يُنضم لها من صفحتها، و«الخدمات» مثل المرشدين والنقل والضيافة والترجمة وتطلبها من صفحتها، و«المنتجات» المحلية مثل التمور والهدايا والحرف. أما السكن وفرص الأعمال ففي «فرص مكة» على الرئيسية.",
          "The Market has three parts: Experiences — tours, workshops and events you book or join from their page; Services — guides, transport, hospitality and translation you request from their page; and local Products such as dates, gifts and crafts. Homes and business opportunities are in Makkah Opportunities on Home.");
        msg.links = [{ label: T2("التجارب", "Experiences"), to: { s: "market", tab: "experiences" } }, { label: T2("الخدمات", "Services"), to: { s: "market", tab: "services" } }, { label: T2("المنتجات", "Products"), to: { s: "market", tab: "products" } }];
        return msg;
      }
      if (it.id === "market_services") {
        const top = rank(marketServices(), ctx, { limit: 3, maxPerCategory: 3 });
        msg.text = T2(`الخدمات في «السوق» ← «الخدمات»: مرشدون ونقل وضيافة وترجمة وغيرها، منها: ${titles("service", top.map((x) => x.o.id))}. افتح الخدمة واضغط «اطلب الخدمة». ${KEPT}`,
          `Services are in the Market, under Services: guides, transport, hospitality, translation and more, including ${titles("service", top.map((x) => x.o.id))}. Open a service and tap Request this service. ${KEPT}`);
        msg.city = { kind: "service", ids: top.map((x) => x.o.id) };
        msg.links = [{ label: T2("افتح الخدمات", "Open Services"), to: { s: "market", tab: "services" } }]; return msg;
      }
      if (it.id === "market_products") {
        const ids = productsAsked(q.n).slice(0, 4);
        msg.text = T2(`في «السوق» ← «المنتجات»: ${titles("product", ids)}. افتح المنتج وسجّل طلبك منه، ويُحفظ في «طلباتي» وتقدر تعدّله أو تسحبه في أي وقت.`,
          `In the Market, under Products: ${titles("product", ids)}. Open a product and record your request from it; it's saved in My requests, where you can edit or withdraw it at any time.`);
        msg.city = { kind: "product", ids };
        msg.links = [{ label: T2("افتح المنتجات", "Open Products"), to: { s: "market", tab: "products" } }]; return msg;
      }
      if (it.id === "city_housing") {
        const deal = /(للبيع|تمليك|للتمليك|for sale|to own|(^| )(اشتري|نشتري|buy)( |$))/.test(q.n) ? "own" : /(مفروش|furnished|شهر|اشهر|monthly|months|اقامه (طويله|ممتده)|long stay|longer stay|extended)/.test(q.n) ? "stay" : /(ايجار|استاجر|نستاجر|rent)/.test(q.n) ? "rent" : null;
        const villa = /(فيلا|فلل|villa)/.test(q.n);
        const fits = (h) => (!deal || h.deal === deal) && (!villa || h.kind[1] === "Villa");
        let ids = HOMES.filter((h) => fits(h) && (!E.nb || h.nb === E.nb)).map((h) => h.id);
        let lead = "";
        if (!ids.length && E.nb) { ids = HOMES.filter(fits).map((h) => h.id); lead = T2(`ما عندي سكن في ${NB[E.nb].name} حاليًا؛ هذه من أحياء أخرى. `, `There's nothing in ${D(NB[E.nb].name)} right now; these are in other areas. `); }
        if (!ids.length) ids = HOMES.map((h) => h.id);
        if (!deal && personaOf(state.profile) === "visitor") ids.sort((a, b) => (HOME_BY[b].deal === "stay") - (HOME_BY[a].deal === "stay"));
        ids = ids.slice(0, 3);
        const one = ids.length === 1;
        msg.text = lead + T2(`في «فرص مكة» ← «عِش في مكة»: ${titles("home", ids)}. افتح ${one ? "صفحته" : "أي واحد منها"} وسجّل اهتمامك أو اطلب التفاصيل، وتلقى طلبك في «طلباتي».`,
          `In Makkah Opportunities, under Live in Makkah: ${titles("home", ids)}. Open ${one ? "its page" : "any of them"} to register interest or request details, and you'll find your request in My requests.`);
        msg.city = { kind: "home", ids };
        msg.links = [{ label: T2("افتح «عِش في مكة»", "Open Live in Makkah"), to: { s: "city", tab: "live" } }]; return msg;
      }
      if (it.id === "city_invest") {
        const CAT_RX = { hospitality: /(فندق|فنادق|ضيافه|سياح|زوار|معتمرين|hotel|hospitality|tourism|visitors?)/, commercial: /(محل|محلات|وحدات تجاريه|مساحات تجاريه|تجاري|commercial|shop units?|retail space)/,
          retail: /(مقهي|كافيه|مطعم|مطاعم|متجر|تجزئه|خدمات|cafe|coffee|restaurant|store|retail|services)/, development: /(تطوير|سكني|عقاري|شراكه|شراكات|development|residential|construction|partnership)/ };
        const cats = Object.keys(CAT_RX).filter((c) => CAT_RX[c].test(q.n));
        const ids = OPPORTUNITIES.filter((o) => !cats.length || cats.includes(o.cat)).map((o) => o.id).slice(0, 3);
        const money = /(ربح|ارباح|عائد|عوائد|عايد|عوايد|مربح|مربحه|كم يكسب|كم يجيب|جدوي|تكلفه|راس مال|roi|returns?|profit|profitable|yield|worth investing|feasib|how much (does it|would it|money)|capital)/.test(q.n);
        msg.text = (money ? T2("ما أقدّم أرقامًا عن الأرباح أو العوائد أو التكلفة، ولا نصائح أو توصيات استثمارية — رحاب مكة ليس جهة استثمار ولا مستشارًا ماليًا. ", "I don't give figures on profits, returns or costs, or investment advice or recommendations — Rihab Makkah isn't an investment company or a financial adviser. ") : "")
          + T2(`«استثمر في مكة» دليل تعريفي بفرص الأعمال في مكة، منها: ${titles("opp", ids)}. ${money ? "" : "رحاب مكة ليس جهة استثمار ولا مستشارًا ماليًا، فلا أذكر مبالغ أو عوائد ولا أفضّل فرصة على أخرى. "}تقدر تستكشف الفرصة وتسجّل اهتمامك أو تطلب معلومات إضافية، وتلقى ذلك في «طلباتي».`,
            `Invest in Makkah is an introductory directory of business opportunities in Makkah, including: ${titles("opp", ids)}. ${money ? "" : "Rihab Makkah isn't an investment company or a financial adviser, so I don't mention amounts or returns or rank one opportunity above another. "}You can explore an opportunity and register interest or ask for more information; you'll find it in My requests.`);
        msg.city = { kind: "opp", ids };
        msg.links = [{ label: T2("افتح «استثمر في مكة»", "Open Invest in Makkah"), to: { s: "city", tab: "invest" } }]; return msg;
      }
      return msg;
    });
    case "describe_current_user_context": {
      const p = state.profile;
      msg.text = say({ mode: p.mode ? T2(p.mode === "visitor" ? "زائر" : "ساكن في مكة", p.mode) : T2("غير محدد", "not set"), neighborhood: NB[p.nb]?.name || T2("غير محدد", "not set"),
        party: T2({ solo: "لوحدك", family: "عائلة", kids: "مع أطفال", group: "مجموعة" }[p.party], p.party), time_available: p.timeAvailable ? minutesAr(p.timeAvailable) : T2("غير محدد", "not set"),
        interests: p.interests.map((c) => CAT[c]?.name).filter(Boolean).join("، "), language: p.lang === "en" ? "English" : "العربية" });
      return msg;
    }
    case "set_user_mode_from_query": {
      /* the account type is fixed at sign-up: say so, never switch it */
      const cur = personaOf(state.profile);
      msg.text = cur
        ? T2(`حسابك ${cur === "visitor" ? "حساب زائر لمكة" : "حساب ساكن في مكة"}، ونوع الحساب يُحدَّد عند إنشائه ولا يتغيّر. ${cur === "visitor" ? "أقدر أرتّب لك رحلتك حسب اهتماماتك ووقتك." : "أقدر أساعدك فيما يحدث حولك في حيّك ومكة."}`,
          `Yours is a ${cur === "visitor" ? "Makkah visitor" : "Makkah resident"} account. The account type is set when the account is created and can't be changed. ${cur === "visitor" ? "I can shape your trip around your interests and time." : "I can help with what's happening around you in your area and across Makkah."}`)
        : T2("نوع الحساب يُحدَّد عند إنشائه ولا يتغيّر من هنا.", "The account type is set when the account is created and can't be changed here.");
      S.lastAction = { kind: "mode" };
      return msg;
    }
    case "set_neighborhood_from_query": {
      if (!E.nb) { msg.text = T2("أي حي تقصد؟ مثلًا العوالي أو العزيزية أو أجياد.", "Which neighbourhood? For example Al-Awali, Al-Aziziyah or Ajyad."); msg.clarify = true; return msg; }
      dispatch({ type: "profile", patch: { nb: E.nb } });
      msg.text = say({ neighborhood: NB[E.nb].name }); S.lastAction = { kind: "nb" }; return msg;
    }
    case "set_party_from_query": {
      if (!E.party) { msg.text = T2("مع مين بتكون؟ لوحدك، عائلة، أطفال أو مجموعة؟", "Who's with you — solo, family, kids or a group?"); msg.clarify = true; return msg; }
      dispatch({ type: "profile", patch: { party: E.party } });
      msg.text = say({ party: T2({ solo: "لوحدك", family: "عائلة", kids: "مع أطفال", group: "مجموعة" }[E.party], E.party) }); return msg;
    }
    case "set_time_available_from_query": {
      const v = typeof E.time === "number" ? E.time : null;
      if (!v) { msg.text = T2("كم وقتك المتاح؟ ساعة، ساعتان أو المساء كله؟", "How much time — an hour, two hours or the whole evening?"); msg.clarify = true; return msg; }
      dispatch({ type: "profile", patch: { timeAvailable: v } });
      const lead = say({ time_available: minutesAr(v) });
      const { items } = runAgentQuery({ maxDur: v, types: personaOf(state.profile) === "visitor" ? ["experience", "place", "event", "activity"] : undefined }, { ...ctx, timeAvailable: v }, state);
      msg.text = lead;
      if (!items.length) return msg;
      const shown = items.slice(0, 3);
      S.lastQuery = { maxDur: v }; S.ranked = items.slice(0, 8).map((x) => x.id); S.shown = shown.map((x) => x.id); S.lastObject = null; S.lastShape = "ranked_list";
      msg.text = `${lead} ${T2("ومن الآن يناسب وقتك:", "Right now these fit your time:")} ${names(shown.map((x) => x.id))}.`;
      msg.cards = shown.map((x) => ({ id: x.id, why: x.why })); msg.shape = "ranked_list";
      return msg;
    }
    case "set_language_from_query": {
      const l = E.lang || (lang === "en" ? "ar" : "en");
      dispatch({ type: "profile", patch: { lang: l } });
      msg.text = say({ language: l === "en" ? "English" : "العربية" }); return msg;
    }

    /* discovery + offers: one query model over the inventory */
    case "build_contextual_outing": return outing(ctx.timeAvailable ? ctx.timeAvailable / 60 : 3);
    case "visitor_half_day_plan": {
      const day = /(يوم واحد|يوم وحد|يوم بس|one day|a day in makkah|1 day|رتب لي اليوم|plan my day)/.test(q.n);
      const m = outing(day ? 6 : 4);
      if (day && m.outing) m.text = T2(`ليوم في مكة، رتبت لك هذا من محتوى رحاب مكة: ${m.outing.ids.map((id, i) => `${ar(i + 1)}. ${nameOf(getObj(id))}`).join(" ← ")}. ${personaOf(state.profile) === "visitor" ? "أضفها لرحلتك أو غيّر خطوة." : "عدّل أي خطوة تبغاها."}`,
        `For a day in Makkah, here's an order from Rihab Makkah's content: ${m.outing.ids.map((id, i) => `${i + 1}. ${nameOf(getObj(id))}`).join(" → ")}. ${personaOf(state.profile) === "visitor" ? "Add it to your trip or change a step." : "Change any step you like."}`);
      return m;
    }
    case "build_evening_outing": return outing(4);
    case "plan_build_around_item": {
      const o = referent() || (state.plan[0] && getObj(state.plan[0].obj));
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("حول أي شيء أرتب؟ اذكر المكان أو النشاط.", "Around what? Name the place or activity."), msg);
      return outing(ctx.timeAvailable ? ctx.timeAvailable / 60 : 3, o);
    }
    case "rank_previous_by_proximity": {
      if (!hasQuery) break;
      return runList({ ...S.lastQuery, sort: "near" });
    }
    case "plan_recommend_next": {
      const anchorP = state.plan.find((p) => ["active", "confirmed", "going", "registered", "planned", "awaiting"].includes(p.state));
      const anchor = anchorP ? getObj(anchorP.obj) : null;
      const query = { nb: anchor?.neighborhood, exclude: anchor ? [anchor.id] : [], sort: "near" };
      return runList(query, { current_item: anchor ? nameOf(anchor) : T2("خطتك", "your plan") });
    }
    case "food_order_recommendation": {
      const o = referent() || (E.objects[0] && getObj(E.objects[0]));
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("عن أي مطعم؟ اذكر اسمه أو افتح نتيجة أولًا.", "Which restaurant? Name it or open a result first."), msg);
      const ks = contributionsFor(o.id, state).filter((k) => ["recommendation", "tip", "experience_report"].includes(k.type)).slice(0, 3);
      S.lastObject = o.id;
      if (!ks.length) { msg.text = T2(`ما فيه مساهمات من المجتمع عن ${nameOf(o)} تذكر أطباقًا بعينها بعد.`, `No community contributions about ${nameOf(o)} mention specific dishes yet.`); objCard(o); return msg; }
      msg.text = say({ object: nameOf(o), order_suggestions: T2("من كلام الناس أدناه — آراء وليست معلومة رسمية", "in people's own words below — opinions, not official facts") });
      msg.contribs = ks.map((k) => k.id); objCard(o); return msg;
    }
    case "object_duration_fit": {
      const o = referent();
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("عن أي مكان أو نشاط؟", "Which place or activity?"), msg);
      S.lastObject = o.id;
      const tA = state.profile.timeAvailable;
      const fit = o.duration == null ? T2("مدته غير محددة", "its duration isn't listed") : !tA ? T2("حدد وقتك المتاح وأقولك إذا يناسب", "set your available time and I'll check the fit") : o.duration <= tA ? T2("يناسب وقتك", "it fits your time") : T2("أطول من وقتك المتاح", "it's longer than your available time");
      msg.text = say({ object: nameOf(o), duration: o.duration ? minutesAr(o.duration) : "—", time_available: tA ? minutesAr(tA) : T2("غير محدد", "not set"), fit_note: fit });
      objCard(o); return msg;
    }
    case "object_action_requirement": {
      const o = referent();
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("عن أي مكان أو نشاط؟", "Which place or activity?"), msg);
      S.lastObject = o.id;
      const note = ["book", "register"].includes(o.action) ? T2(`يكتمل لدى ${o.outbound || "مقدّم الخدمة"}، والانتقال لا يعني أن الحجز تم`, `It completes with ${partnerEn(o.outbound || "مزوّد الخدمة")}; leaving to book is not a confirmed booking`) : o.action === "join" ? T2("الانضمام يعني نية حضور فقط", "Joining only records that you're going") : T2("ما يحتاج حجزًا أو تسجيلًا مسبقًا", "No booking or registration needed beforehand");
      msg.text = say({ object: nameOf(o), action_label: AGENT_ACTION_LABEL[o.action] || o.action, action_note: note });
      objCard(o); return msg;
    }
    case "object_trust_summary": {
      const o = referent();
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("عن أي مكان؟", "Which place?"), msg);
      S.lastObject = o.id;
      const tr = objectTrust(o, state.resolved);
      const srcs = uniq(o.facts.map((f) => ({ official: T2("رسمي", "official"), provider: T2("مقدّم الخدمة", "provider"), community: T2("المجتمع", "community") }[f.cls])).filter(Boolean));
      msg.text = say({ object: nameOf(o), trust_summary: TRUST_STATE[tr.state]?.label ? D(TRUST_STATE[tr.state].label) : tr.state, sources: srcs.join("، ") || "—", field_or_general: "" });
      objCard(o); return msg;
    }
    case "offer_terms_detail": {
      let o = referent();
      let of = o ? offerFor(o) : null;
      if (!of && S.lastOffer) { of = DEAL_BY_ID[S.lastOffer]; o = getObj(of.obj); }
      if (!of && hasRanked) { const first = S.ranked.map((id) => offerFor(id)).find(Boolean); if (first) { of = first; o = getObj(of.obj); } }
      if (!o || !of) { msg.text = o ? T2(`ما فيه عرض حاليًا على ${nameOf(o)}.`, `There's no offer on ${nameOf(o)} right now.`) : T2("عن أي عرض؟ اذكر المكان أو اسأل «وش العروض؟» أولًا.", "Which offer? Name the place or ask for offers first."); if (o) objCard(o); return msg; }
      S.lastObject = o.id; S.lastOffer = of.id; S.lastShape = "offer";
      const p = offerPrice(of);
      const value = Dj([L2(of.badge), p ? tx(`${ar(p.now)} ريال بدل ${ar(p.was)}${p.pkg ? " " + PKG_NOTE[0] : ""}`, `SAR ${p.now} instead of ${p.was}${p.pkg ? " " + PKG_NOTE[1] : ""}`) : null]);
      msg.text = say({ offer: `${L2(of.title)} — ${nameOf(o)}`, offer_value: value, terms: `${L2(of.terms)} (${WHO[of.who]})`, validity: `${whenAr(of.end)} · ${offerExpiry(of)}`, redemption: REDEEM[of.redeem], source: T2("عرض عبر رحاب مكة", "Rihab Makkah offer"), terms_summary: offerSummary(of) });
      if (E.suit.includes("family") || E.party === "family" || /عائل|family/.test(q.n)) msg.text += " " + (["family", "kids"].includes(of.who) || of.kind === "package" ? T2("نعم، العرض موجّه للعائلات.", "Yes, this offer is aimed at families.") : T2(`العرض ${WHO[of.who]} وليس باقة عائلية تحديدًا.`, `The offer is for ${WHO[of.who].toLowerCase()}, not a family package as such.`));
      msg.offer = of.id; objCard(o); msg.shape = "offer"; return msg;
    }

    /* actions — each changes exactly one state and says which states did not change */
    case "action_save_object": case "action_unsave_object": case "action_join_activity": case "action_leave_activity":
    case "action_add_to_plan": case "action_remove_from_plan": case "action_open_object_detail": case "action_open_directions":
    case "action_booking_handoff": case "action_confirm_booking_by_user": {
      let o = referent();
      if (h === "action_confirm_booking_by_user" && !o) { const aw = state.plan.find((p) => p.state === "awaiting"); o = aw ? getObj(aw.obj) : null; }
      if (!o && E.ordinal != null) return noOrdinal();
      if (!o && h === "action_booking_handoff") { const bk = S.shown.map(getObj).filter((x) => x && ["book", "register", "redeem", "contact"].includes(x.action)); if (bk.length === 1) o = bk[0]; }
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("على أي عنصر؟ اذكر اسمه أو اطلب اقتراحات أولًا.", "On which item? Name it or ask for suggestions first."), msg.clarify = true, msg);
      return agentAct(h, o, { state, dispatch, lang, say, msg, S, nameOf });
    }

    /* My Plan */
    case "plan_summary": case "plan_today": case "plan_upcoming": case "plan_confirmed": case "plan_completed": {
      const items = state.plan.filter((p) => p.state !== "cancelled");
      const want = { plan_today: ["now", "today"], plan_upcoming: ["upcoming", "today"], plan_confirmed: ["confirmed"], plan_completed: ["completed"] }[h];
      const list = want ? items.filter((p) => want.includes(planBucket(p))) : items;
      S.ranked = list.map((p) => p.obj); S.lastObject = list.length === 1 ? list[0].obj : null; S.lastShape = "plan";
      if (!list.length) { msg.empty = true; msg.text = h === "plan_summary" ? T2("«خطتي» فاضية الآن. اطلب اقتراحًا وأضف ما يعجبك — الإضافة ليست حجزًا.", "My Plan is empty. Ask for a suggestion and add what you like — adding is not booking.") : T2("ما فيه عناصر بهذه الحالة في «خطتي».", "Nothing in My Plan is marked that way."); return msg; }
      const counts = {}; items.forEach((p) => { const b = planBucket(p); counts[b] = (counts[b] || 0) + 1; });
      const summary = Object.entries(counts).map(([b, n]) => `${D(PLAN_BUCKETS.find((x) => x.id === b)?.label || b)} ${ar(n)}`).join(" · ");
      msg.text = say({ plan_summary: summary, plan_items: names(list.slice(0, 4).map((p) => p.obj)) });
      msg.plan = list.slice(0, 5).map((p) => p.obj); return msg;
    }

    /* community */
    case "community_object_summary": {
      const o = referent();
      if (!o) return ambiguous() ? clarify() : (msg.text = T2("عن أي مكان تبغى رأي الناس؟", "Which place do you want people's views on?"), msg);
      S.lastObject = o.id;
      const ks = contributionsFor(o.id, state);
      if (!ks.length) { msg.text = T2(`ما فيه مساهمات عن ${nameOf(o)} بعد. تجربتك لو زرته تفيد غيرك.`, `No contributions about ${nameOf(o)} yet. Your experience would help others.`); objCard(o); return msg; }
      const byType = {}; ks.forEach((k) => { byType[k.type] = (byType[k.type] || 0) + 1; });
      msg.text = say({ object: nameOf(o), community_summary: T2(`${ar(ks.length)} مساهمات من الناس — آراء وتجارب وليست معلومات رسمية`, `${ks.length} contributions from people — opinions and experiences, not official facts`) });
      msg.contribs = ks.slice(0, 3).map((k) => k.id); objCard(o); msg.shape = "community_summary"; return msg;
    }
    case "community_active_discussions": case "community_recommendations": {
      let ks = allContributions(state).filter((k) => !k.parent);
      if (h === "community_recommendations") ks = ks.filter((k) => ["recommendation", "tip", "experience_report"].includes(k.type));
      const mine = ks.filter((k) => k.communities.some((c) => state.joinedCommunities.includes(c)));
      ks = (mine.length >= 2 ? mine : ks).sort((a, b) => new Date(b.at) - new Date(a.at)).slice(0, 3);
      msg.text = say({ discussions: T2("أحدثها أدناه", "the latest are below"), recommendations: T2("من كلام الناس أدناه", "in people's words below") });
      msg.contribs = ks.map((k) => k.id); msg.shape = "community_summary"; return msg;
    }
    case "community_find_relevant": {
      const p = state.profile;
      const list = COMMUNITIES.filter((c) => c.kind !== "family" && c.state !== "archived")
        .map((c) => ({ c, s: (c.nb === (E.nb || p.nb) ? 3 : 0) + (p.interests.includes(c.family) ? 2 : 0) + (p.mode === "visitor" && c.family === "visitors" ? 3 : 0) + (E.community === c.id ? 5 : 0) + c.members / 5000 }))
        .sort((a, b) => b.s - a.s).slice(0, 3).map((x) => x.c);
      msg.text = say({ communities: list.map((c) => D(c.name)).join("، ") });
      msg.communities = list.map((c) => c.id); return msg;
    }
    case "community_linked_activities": {
      const cid = E.community || (S.lastObject && getObj(S.lastObject)?.communities[0]) || state.joinedCommunities[0];
      const c = COM[cid];
      if (!c) { msg.text = T2("أي مجتمع تقصد؟", "Which community?"); msg.clarify = true; return msg; }
      const acts = INVENTORY.filter((o) => ["activity", "recurring", "event", "experience"].includes(o.type) && isPromotable(o) && (o.communities.includes(c.id) || (c.linked || []).includes(o.id)));
      const items = rank(acts, ctx, { limit: 6, maxPerCategory: 6 }).map((x) => ({ id: x.o.id, why: x.why.map(D) }));
      return finishList(items, { types: ["activity", "event", "experience"] }, { community: D(c.name) });
    }
    case "action_community_membership": {
      const cid = E.community;
      if (!cid) { msg.text = T2("أي مجتمع تبغى تنضم له أو تطلع منه؟ اكتب اسمه.", "Which community? Type its name."); msg.clarify = true; return msg; }
      const on = !state.joinedCommunities.includes(cid);
      dispatch({ type: "join_community", com: cid });
      msg.text = say({ membership_action: T2(on ? "الانضمام" : "المغادرة", on ? "join" : "leave"), community: D(COM[cid].name) }); return msg;
    }
    case "action_create_community_question": case "action_create_contribution": {
      const o = referent();
      msg.text = say({ community_or_object: o ? nameOf(o) : T2("المجتمع المناسب", "the right community"), question_text: text, object: o ? nameOf(o) : "—", contribution_type: T2("تجربة", "experience") });
      msg.compose = { obj: o?.id || null }; return msg;
    }

    /* follow-ups over the previous answer */
    case "followup_explain_previous_recommendation": {
      const o = referent() || (hasRanked && getObj(S.ranked[0]));
      if (!o) break;
      const why = runAgentQuery({ ...(S.lastQuery || {}), excludeIds: [] }, ctx, state).items.find((x) => x.id === o.id)?.why || scoreObject(o, ctx).why.map(D);
      S.lastObject = o.id;
      msg.text = say({ reason_summary: why.slice(0, 3).join(T2("، و", ", and ")) || T2("يطابق طلبك وسياقك", "it matches your request and context"), entity: nameOf(o) });
      objCard(o, why); return msg;
    }
    case "followup_second_ranked": case "followup_third_ranked": {
      const i = h === "followup_second_ranked" ? 1 : 2;
      const id = S.ranked[i];
      if (!id) { msg.text = T2("ما عندي خيار بهذا الترتيب في آخر نتيجة.", "The last answer didn't have that many options."); return msg; }
      const o = getObj(id);
      const why = S.lastQuery ? runAgentQuery(S.lastQuery, ctx, state).items.find((x) => x.id === id)?.why || [] : [];
      S.lastObject = id; S.lastShape = "single_entity";
      msg.text = say({ entity: nameOf(o), reason: why[0] || T2("ضمن نفس الطلب", "part of the same request") });
      objCard(o, why); msg.shape = "single_entity"; return msg;
    }
    case "followup_compare_top_two": {
      if (S.ranked.length < 2) break;
      const [a, b] = S.ranked.slice(0, 2).map(getObj);
      const from = agentFrom(S.lastQuery || {}, ctx);
      const line = (o) => Dj([nameOf(o), NB[o.neighborhood]?.name, from ? `~${ar(distanceKm(o, from))} ${T2("كم", "km")}` : null, effPrice(o) < 9e8 ? riyal(effPrice(o)) : null, offerFor(o) ? L2(offerFor(o).badge) : T2("بدون عرض", "no offer"), o.suit.includes("quiet") ? SUIT.quiet : null]);
      msg.text = say({ comparison_summary: `${line(a)} | ${line(b)}` });
      msg.cards = [{ id: a.id, why: [] }, { id: b.id, why: [] }]; msg.shape = "ranked_list"; return msg;
    }
    case "followup_expand_previous": case "followup_shorten_previous": {
      if (placeAsk) return placeAnswer();
      const o = referent() || (hasRanked && getObj(S.ranked[0]));
      if (!o) break;
      S.lastObject = o.id;
      const of = offerFor(o);
      const detail = Dj([nameOf(o), D(o.t), NB[o.neighborhood]?.name, timingLabel(o), o.duration ? minutesAr(o.duration) : null, priceLabel(o), of ? L2(of.badge) : null]);
      msg.text = say({ expanded_detail: detail + (h === "followup_expand_previous" && o.ab ? ". " + D(o.ab) : ""), short_summary: detail, entity: nameOf(o) });
      objCard(o); msg.shape = "single_entity"; return msg;
    }
    case "followup_expand_ranking": {
      if (!hasQuery) break;
      const all = runAgentQuery(S.lastQuery, ctx, state).items.filter((x) => !S.shown.includes(x.id));
      if (!all.length) { msg.text = T2("هذه كل الخيارات المطابقة في المحتوى الحالي.", "Those are all the matching options in current content."); return msg; }
      const shown = all.slice(0, 3);
      S.shown = [...S.shown, ...shown.map((x) => x.id)]; S.ranked = shown.map((x) => x.id); S.lastObject = null;
      msg.text = say({ ranked_results: names(shown.map((x) => x.id)) });
      msg.cards = shown.map((x) => ({ id: x.id, why: x.why })); return msg;
    }
    case "followup_alternative": {
      if (!hasQuery) break;
      const prev = S.lastObject || S.ranked[0];
      return runList({ ...S.lastQuery, exclude: [...(S.lastQuery.exclude || []), ...S.shown] }, { previous_entity: prev ? nameOf(getObj(prev)) : "" });
    }
    case "followup_refine_proximity": if (hasQuery) return runList({ ...applyEntities(S.lastQuery, E, true), sort: "near" }); break;
    case "followup_refine_quiet": {
      if (!hasQuery) break;
      const strict = { ...S.lastQuery, suit: uniq([...(S.lastQuery.suit || []), "quiet"]) };
      if (runAgentQuery(strict, ctx, state).items.length >= 2) return runList(strict);
      return runList({ ...S.lastQuery, sort: "quiet" }, {}, { lead: T2("قليل منها موصوف بالهدوء صراحةً؛ رتبتها بحيث الأهدأ أولًا.", "Few are explicitly described as quiet; I've put the quieter ones first.") });
    }
    case "followup_refine_price": if (hasQuery) return runList({ ...S.lastQuery, sort: "price" }); break;
    case "followup_refine_active_offer": {
      const o = S.lastObject && getObj(S.lastObject);
      if (o && !/(اللي|منهم|which|ones|only|بس)/.test(q.n)) {
        const of = offerFor(o);
        S.lastOffer = of?.id || null;
        msg.text = of ? T2(`نعم، على ${nameOf(o)} عرض: ${offerSummary(of)}.`, `Yes — ${nameOf(o)} has an offer: ${offerSummary(of)}.`) : T2(`ما عليه عرض حاليًا.`, `${nameOf(o)} has no offer right now.`);
        if (of) msg.offer = of.id;
        objCard(o); msg.shape = of ? "offer" : "single_entity"; return msg;
      }
      if (hasQuery) return runList({ ...S.lastQuery, offer: true });
      return runList({ offer: true });
    }
    case "followup_refine_family": if (hasQuery) return runList({ ...S.lastQuery, suit: uniq([...(S.lastQuery.suit || []), "family"]) }); break;
    case "followup_refine_kids": if (hasQuery) return runList({ ...S.lastQuery, suit: uniq([...(S.lastQuery.suit || []), "kids"]) }); break;
    case "followup_refine_beginner": if (hasQuery) return runList({ ...S.lastQuery, suitAny: ["beginners", "noexp"] }); break;
    case "followup_refine_accessibility": if (hasQuery) return runList({ ...S.lastQuery, suitAny: ["accessible", "stepfree"] }); break;
    case "followup_refine_category": {
      if (!hasQuery && !E.types.length) break;
      const types = E.types.length ? E.types : S.lastQuery.types;
      return runList({ ...(S.lastQuery || {}), types, cats: E.cats.length ? E.cats : null }, { category: (types || []).map((t) => T2(TYPE_NAME[t]?.[0], TYPE_NAME[t]?.[1])).join("، ") });
    }
    case "followup_repeat_with_new_area": if (hasQuery && E.nb) return runList({ ...S.lastQuery, nb: E.nb }, { neighborhood: NB[E.nb].name }); break;
    case "followup_repeat_with_new_time": if (hasQuery) { const n = applyEntities(S.lastQuery, E, true); if (/(ليله|مساء|tonight|evening)/.test(q.n)) n.when = "tonight"; return runList(n, { time_context: E.time ? (typeof E.time === "number" ? minutesAr(E.time) : T2("نهاية الأسبوع", "the weekend")) : T2("الليلة", "tonight") }); } break;
    case "followup_repeat_current_context": if (hasQuery) return runList(S.lastQuery); break;
    default: {
      const base = HANDLER_QUERY[h];
      if (base) {
        let query = applyEntities({ ...base }, E, !!base.types && !E.types.length ? false : false);
        if (base.types && E.types.length === 0) query.types = base.types;
        query.kw = agentKeyword(q.n);
        if (h === "recommend_in_area") query.nb = E.nb || ctx.nb;
        if (h === "recommend_in_area" && !query.nb) { msg.text = T2("أي حي تقصد؟ مثلًا العوالي أو العزيزية أو أجياد.", "Which neighbourhood? For example Al-Aziziyah, Al-Awali or Ajyad."); msg.clarify = true; return msg; }
        if (h === "recommend_nearby" || h === "offers_nearby") query.nb = query.nb || null;
        return runList(query, { neighborhood: NB[query.nb || ctx.nb]?.name });
      }
    }
  }
  /* a follow-up without the context it needs, or an unhandled shape */
  msg.text = T2("ما عندي سؤال سابق أبني عليه هنا. قل لي بطريقتك وش تبغى — مكان، أكل، نشاط، عرض أو شيء في «خطتي».", "I don't have a previous request to build on. Tell me what you need — a place, food, an activity, an offer or something in My Plan.");
  msg.clarify = true;
  return msg;
}

/* the one place agent actions touch app state — same reducer as the UI buttons */
function agentAct(h, o, { state, dispatch, lang, say, msg, S, nameOf }) {
  const T2 = (a, e) => (lang === "en" ? e : a);
  const it = AGENT.BY_ID[{ action_save_object: "action_save_item", action_unsave_object: "action_unsave_item", action_join_activity: "action_join_activity", action_leave_activity: "action_leave_activity", action_add_to_plan: "plan_add_item", action_remove_from_plan: "plan_remove_item", action_open_object_detail: "action_open_details", action_open_directions: "action_open_directions", action_booking_handoff: "action_start_booking_handoff", action_confirm_booking_by_user: "action_confirm_booking_explicit" }[h]];
  const sayA = (vars) => { const rs = it.r[lang] || it.r.ar; return rs[0].replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? "—"); };
  const name = nameOf(o);
  const planItem = state.plan.find((p) => p.obj === o.id);
  S.lastObject = o.id; S.lastAction = { kind: h, obj: o.id };
  msg.cards = [{ id: o.id, why: [] }];
  /* nothing to join, plan or book on something that has ended or a group that has paused */
  const life = lifecycleOf(o);
  if (NOT_RUNNING.includes(life) && ["action_join_activity", "action_add_to_plan", "action_booking_handoff"].includes(h)) {
    msg.text = ["paused", "dormant"].includes(life)
      ? T2(`${name} متوقف حاليًا ولا يوجد لقاء قادم، فما أضفته إلى «خطتي». تقدر تطلب بديلًا.`, `${name} is paused, with no upcoming meeting, so I haven't added it to My Plan. You can ask for an alternative.`)
      : T2(`${name} انتهى، فما أضفته إلى «خطتي». تقدر تطلب بديلًا.`, `${name} has ended, so I haven't added it to My Plan. You can ask for an alternative.`);
    return msg;
  }
  switch (h) {
    case "action_save_object":
      if (state.saved[o.id]) { msg.text = T2(`${name} محفوظ من قبل — ما غيّرت شيئًا.`, `${name} is already saved — nothing changed.`); return msg; }
      dispatch({ type: "save", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_unsave_object":
      if (!state.saved[o.id]) { msg.text = T2(`${name} مو محفوظ أصلًا.`, `${name} isn't saved.`); return msg; }
      dispatch({ type: "save", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_join_activity":
      if (!["join"].includes(o.action) && !["activity", "recurring"].includes(o.type)) { msg.text = T2(`${name} ما يُنضم له — إجراؤه: ${AGENT_ACTION_LABEL[o.action]}.`, `${name} isn't something you join — its action is: ${AGENT_ACTION_LABEL[o.action]}.`); return msg; }
      dispatch({ type: "join", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_leave_activity":
      if (!planItem || !["going", "registered"].includes(planItem.state)) { msg.text = T2(`ما عندك انضمام نشط لـ${name}.`, `You don't have an active join for ${name}.`); return msg; }
      dispatch({ type: "cancel", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_add_to_plan":
      if (planItem && !["saved", "interested", "cancelled"].includes(planItem.state)) { msg.text = T2(`${name} موجود في «خطتي» بحالة «${D(PLAN_STATE[planItem.state].label)}» — ما غيّرته.`, `${name} is already in My Plan as "${D(PLAN_STATE[planItem.state].label)}" — unchanged.`); return msg; }
      dispatch({ type: "plan", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_remove_from_plan":
      if (!planItem) { msg.text = T2(`${name} مو موجود في «خطتي».`, `${name} isn't in My Plan.`); return msg; }
      dispatch({ type: "remove_plan", obj: o.id }); msg.text = sayA({ object: name }); return msg;
    case "action_open_object_detail":
      msg.text = sayA({ object: name }); msg.navigate = o.id; return msg;
    case "action_open_directions":
      dispatch({ type: "directions", obj: o.id });
      msg.text = sayA({ object: name }); msg.navigate = o.id; return msg;
    case "action_booking_handoff":
      if (!["book", "register", "redeem", "contact"].includes(o.action)) { msg.text = T2(`${name} لا يحتاج حجزًا — ${AGENT_ACTION_LABEL[o.action]}.`, `${name} doesn't need booking — ${AGENT_ACTION_LABEL[o.action]}.`); return msg; }
      msg.text = sayA({ object: name }); msg.handoff = o.id; return msg;
    case "action_confirm_booking_by_user":
      if (!planItem || planItem.state !== "awaiting") { msg.text = T2(`ما انتقلت لإكمال حجز ${name} بعد، فما أقدر أحوله إلى «مؤكد».`, `You haven't continued to booking for ${name} yet, so it can't be marked Confirmed.`); return msg; }
      dispatch({ type: "book_confirm", obj: o.id, source: "user" }); msg.text = sayA({ object: name }); return msg;
    default: return msg;
  }
}

/* 0–2 contextual suggestions — optional aids, never the primary input */
function agentSuggestions(lastMsg, ctx, lang) {
  const sg = AGENT.bank.suggestions;
  const pick = (arr) => (arr || []).filter((s) => !AGENT_SESSION.mem.recentSugg.includes(s));
  let out = [];
  const visitor = ctx.mode === "visitor";
  if (!lastMsg) {
    /* the same Assistant, opened with the questions each persona actually brings */
    out = visitor
      ? (lang === "en" ? ["I have one day in Makkah — what should I do?", "We're with children — what suits us?", "A cultural experience, then a restaurant", "I only have two hours"]
        : ["عندي يوم واحد في مكة، وش أسوي؟", "أنا مع أطفال، وش يناسبنا؟", "أبغى تجربة ثقافية وبعدها مطعم", "عندي ساعتين فقط"])
      : (lang === "en" ? ["What's on this weekend?", "What's new around me?", "What's in my area?", "A family activity"]
        : ["وش فيه نهاية الأسبوع؟", "وش الجديد حولي؟", "وش فيه في حيّي؟", "أبغى نشاط للعائلة"]);
    AGENT_SESSION.mem.recentSugg = [...out, ...AGENT_SESSION.mem.recentSugg].slice(0, 6);
    return out;
  } else if (lastMsg.clarify || lastMsg.empty) {
    out = [];
  } else if (lastMsg.shape === "city") {
    out = lastMsg.intent === "city_my_requests" ? [lang === "en" ? "Homes for rent in Makkah" : "أبغى شقة للإيجار في مكة"]
      : lastMsg.intent === "city_invest" ? [lang === "en" ? "Show my requests" : "وش طلباتي؟", lang === "en" ? "An extended stay in Makkah" : "أبغى إقامة ممتدة في مكة"]
      : [lang === "en" ? "Show my requests" : "وش طلباتي؟", lang === "en" ? "Business opportunities in Makkah" : "وش فرص الأعمال في مكة؟"];
  } else {
    const shape = lastMsg.shape === "offer" ? "offer" : lastMsg.shape;
    out = pick(sg.after_answer_type[shape]?.[lang]);
    if (shape === "ranked_list" && lastMsg.cards?.length && !lastMsg.cards.some((c) => offerFor(c.id))) out = [out[0], lang === "en" ? "Any of them with an offer?" : "فيه منهم عليه عرض؟"];
    /* persona follow-ups: a visitor builds a trip, a resident stays local */
    if (shape === "ranked_list" && lastMsg.cards?.length > 1) out = visitor ? [lang === "en" ? "Add the first to my plan" : "ضف الأول لخطتي", out[0]] : [out[0], lang === "en" ? "What's in my area?" : "وش فيه في حيّي؟"];
    if (lastMsg.cards?.length === 1 && shape === "single_entity") {
      out = pick(sg.by_page["تفاصيل"][lang]).slice(1, 3);
      if (offerFor(lastMsg.cards[0].id)) out = out.map((x) => (/عرض|offer/i.test(x) ? (lang === "en" ? "What are the offer terms?" : "وش شروط العرض؟") : x));
    }
    /* no "add it to my plan" / "join" follow-up for something that has ended or paused */
    const one = lastMsg.cards?.length === 1 && getObj(lastMsg.cards[0].id);
    if (one && NOT_RUNNING.includes(lifecycleOf(one))) {
      out = out.filter((x) => x && !/خطت|plan|انضم|join|احجز|book|سجل|سجّل|register/i.test(x));
      if (!out.length) out = [lang === "en" ? "Give me an alternative" : "عطني بديل"];
    }
  }
  out = out.filter(Boolean).slice(0, 2);
  AGENT_SESSION.mem.recentSugg = [...out, ...AGENT_SESSION.mem.recentSugg].slice(0, 4);
  return out;
}

/* Home is composed per persona from one shared toolkit: the same inventory, ranking,
   cards and state — a different question answered first.
     resident · «What is happening in my Makkah?»
     visitor  · «Help me experience Makkah.» */
function buildHome(state, ctx) {
  return personaOf(state.profile) === "visitor" ? buildVisitorHome(state, ctx) : buildResidentHome(state, ctx);
}
function homeKit() {
  const used = new Set();
  const take = (list, n) => { const out = []; for (const x of list) { if (used.has(x.o.id)) continue; used.add(x.o.id); out.push(x); if (out.length >= n) break; } return out; };
  const pool = INVENTORY.filter((o) => o.type !== "offer" && isPromotable(o));
  return { used, take, pool };
}
/* midnight at the end of today, in Makkah time */
const DAY_END = mkDayStart(NOW) - TZ + DAY;
/* the coming Friday–Saturday weekend in Makkah */
const WEEKEND = (() => {
  const l = mk(NOW); const dow = l.getUTCDay();
  const toFri = dow === 6 ? -1 : (5 - dow + 7) % 7;           // on a Saturday the weekend began yesterday
  const from = Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate() + toFri) - TZ;
  return { from, to: from + 2 * DAY };
})();
const happensToday = (o) => { if (["live", "soon"].includes(lifecycleOf(o))) return true; const n = nextOccurrence(o); return !!n && +n >= t0 - HOUR && +n < DAY_END; };
const happensThisWeek = (o) => { const n = nextOccurrence(o); return !!n && +n >= t0 - HOUR && +n - t0 < 7 * DAY; };
const happensWeekend = (o) => { const n = nextOccurrence(o); return !!n && +n >= WEEKEND.from && +n < WEEKEND.to; };
/* only when committed plan items are happening now or today does Home lead with them */
function journeyModule(state) {
  const live = state.plan.filter((p) => {
    if (p.state === "active") return true;
    if (!["confirmed", "registered", "going", "awaiting"].includes(p.state)) return false;
    const o = getObj(p.obj); return !!o && happensToday(o);
  });
  return live.length ? { id: "journey", kind: "journey", items: live.slice(0, 2) } : null;
}

function buildResidentHome(state, ctx) {
  const { take, pool } = homeKit();
  const modules = [];
  const area = NB[ctx.nb];
  const areaName = area?.name;
  const near = (o) => o.neighborhood === ctx.nb || (ctx.from && distanceKm(o, ctx.from) < 3);

  const j = journeyModule(state); if (j) modules.push(j);

  /* 10.2 what's new around you — recency only where the record has a basis for it */
  const fresh = [];
  const posts = allContributions(state)
    .filter((k) => !k.parent && (k.communities.includes(ctx.nb) || k.communities.some((c) => state.joinedCommunities.includes(c))) && t0 - +new Date(k.at) < 7 * DAY)
    .sort((a, b) => new Date(b.at) - new Date(a.at)).slice(0, 2);
  const soon = rank(pool.filter((o) => ["event", "activity", "recurring"].includes(o.type) && near(o) && happensThisWeek(o)), ctx, { limit: 3, maxPerCategory: 2, maxPerNeighborhood: 3 });
  const added = rank(pool.filter((o) => o.venue && o.neighborhood === ctx.nb), ctx, { limit: 2, maxPerCategory: 1, maxPerNeighborhood: 2 });
  soon.slice(0, 2).forEach((x) => fresh.push({ kind: "obj", x, label: tx(`قادم ${whenAr(nextOccurrence(x.o))}`, `Coming up ${whenMid(nextOccurrence(x.o))}`) }));
  posts.forEach((k) => fresh.push({ kind: "post", k, label: tx(`جديد في ${COM[k.communities.find((c) => COM[c])]?.name || "مجتمعك"} — ${agoAr(k.at)}`, `New in ${COM[k.communities.find((c) => COM[c])]?.name || "your community"} — ${agoAr(k.at)}`) }));
  added.forEach((x) => fresh.push({ kind: "obj", x, label: tx("جديد على رحاب مكة", "New on Rihab Makkah") }));
  fresh.forEach((f) => f.kind === "obj" && take([f.x], 1));
  if (fresh.length) modules.push({ id: "new-around", kind: "whatsnew", title: tx("وش الجديد حولك؟", "What's new around you?"),
    sub: areaName ? tx(`في ${areaName} ومجتمعاتك — مع سبب ظهور كل عنصر`, `In ${areaName} and your communities — each with why it's here`) : tx("من مجتمعاتك وما يقترب موعده", "From your communities and what's coming up"), items: fresh.slice(0, 5) });

  /* 10.3 in your neighbourhood */
  if (areaName) {
    const here = rank(pool.filter((o) => o.neighborhood === ctx.nb), ctx, { limit: 14, maxPerCategory: 3, maxPerNeighborhood: 14 });
    const items = take(here, 6);
    if (items.length) modules.push({ id: "in-area", kind: "scroller", title: tx(`في حيّك — ${areaName}`, `In your area — ${areaName}`), sub: area.blurb, items, action: { label: tx("كل ما في الحي", "All in the area"), to: { s: "discover", nb: ctx.nb } } });
  } else modules.push({ id: "set-area", kind: "setArea" });

  /* 10.4 this week in Makkah */
  const week = rank(pool.filter((o) => ["event", "activity", "recurring"].includes(o.type) && happensThisWeek(o)), { ...ctx, timeNeutral: false }, { limit: 8, maxPerCategory: 2, maxPerNeighborhood: 3 });
  const weekItems = take(week, 4);
  if (weekItems.length) modules.push({ id: "this-week", kind: "rows", title: tx("هذا الأسبوع في مكة", "This week in Makkah"), sub: tx("مواعيد فعلية خلال الأيام السبعة القادمة", "Real dates within the next seven days"), items: weekItems, action: { label: tx("نهاية الأسبوع", "This weekend"), to: { s: "discover", intent: "weekend" } } });

  /* «فرص مكة»: homes to live in and business opportunities, opened from Home */
  modules.push({ id: "city-ops", kind: "cityOps", title: tx("فرص مكة", "Makkah Opportunities"), sub: tx("ابحث عن سكن في مكة، أو تعرّف على فرص الأعمال فيها", "Find a home in Makkah, or learn about business opportunities here") });

  /* complete the outing (8.5) — assembled from real inventory, honest about time */
  if (ctx.evening) {
    const outings = buildOutings(ctx, state, ctx.timeAvailable ? ctx.timeAvailable / 60 : 4);
    if (outings.length) modules.push({ id: "outings", kind: "outings", title: ctx.timeAvailable === 60 ? "عندك ساعة؟" : ctx.timeAvailable === 120 ? "عندك ساعتان؟" : "وش تسوي الليلة؟", sub: tx("مشوار قصير من أماكن قريبة بعضها من بعض", "A short outing from places close to each other"), items: outings });
  }

  /* 10.5 restaurants & cafés worth trying — real places, area first */
  const food = rank(pool.filter((o) => o.real && ["food", "cafe"].includes(o.category)), ctx, { limit: 12, maxPerCategory: 6, maxPerNeighborhood: 6 });
  const foodItems = take(food, 6);
  if (foodItems.length) modules.push({ id: "food", kind: "scroller", title: tx("مطاعم ومقاهٍ تستحق التجربة", "Restaurants & cafés worth trying"), sub: areaName ? tx(`من ${areaName} وما حوله`, `From ${areaName} and nearby`) : tx("من أنحاء مكة", "From across Makkah"), items: foodItems, action: { label: tx("المزيد", "More"), to: { s: "discover", cat: "food" } } });

  /* 10.6 your community */
  const hood = COM[ctx.nb];
  const hoodPosts = allContributions(state).filter((k) => !k.parent && (hood ? k.communities.includes(hood.id) : k.communities.some((c) => state.joinedCommunities.includes(c))))
    .sort((a, b) => new Date(b.at) - new Date(a.at)).slice(0, 2);
  const club = CLUBS.find((cl) => cl.state === "active" && (state.joinedCommunities.includes(cl.community) || ctx.interests.some((i) => interestMatches(getObj(cl.activity) || { suit: [], n: "", category: "" }, i, "resident"))));
  modules.push({ id: "community", kind: "communityHub", title: tx("مجتمعك", "Your community"), sub: tx("أسئلة وتوصيات ومبادرات من سكان مكة", "Questions, recommendations and initiatives from Makkah residents"), hood, posts: hoodPosts, club });

  /* 10.7 activities & hobbies — repeatable participation */
  const hobbies = rank(pool.filter((o) => ["recurring", "activity"].includes(o.type) && o.category !== "volunteer"), ctx, { limit: 10, maxPerCategory: 2 });
  const hobbyItems = take(hobbies, 5);
  if (hobbyItems.length) modules.push({ id: "hobbies", kind: "scroller", title: tx("أنشطة وهوايات", "Activities & hobbies"), sub: tx("مشاركة تتكرر — تقدر تنضم لها", "Things that repeat — you can join in"), items: hobbyItems });

  /* 10.8 initiatives & volunteering */
  const vol = rank(pool.filter((o) => o.category === "volunteer"), ctx, { limit: 6, maxPerCategory: 6 });
  const volItems = take(vol, 4);
  if (volItems.length) modules.push({ id: "initiatives", kind: "rows", title: tx("مبادرات وتطوع", "Initiatives & volunteering"), sub: tx("شارك في حيّك وفي مكة", "Take part in your area and across Makkah"), items: volItems });

  /* 10.9 everyday services — only what Rihab Makkah actually lists */
  const daily = rank(pool.filter((o) => o.type === "service" || o.category === "services" || (o.real && o.category === "market" && /بنده|بن داود|الدانوب/.test(o.n))), ctx, { limit: 6, maxPerCategory: 3 });
  const dailyItems = take(daily, 3);
  if (dailyItems.length) modules.push({ id: "daily", kind: "rows", title: tx("خدمات للحياة اليومية", "Everyday services"), sub: tx("قريبة من حيّك", "Close to your area"), items: dailyItems });
  return modules;
}

function buildVisitorHome(state, ctx) {
  const { take, pool } = homeKit();
  const modules = [];
  const p = state.profile;
  const ints = (p.interests || []).filter((i) => interestDef(i, "visitor"));

  const j = journeyModule(state); if (j) modules.push(j);

  /* 11.2 discover Makkah by your interests */
  const byInterest = ints.map((i) => ({ id: i, items: rank(pool.filter((o) => interestMatches(o, i, "visitor") && o.type !== "recurring"), ctx, { limit: 8, maxPerCategory: 8, maxPerNeighborhood: 3 }) })).filter((g) => g.items.length);
  if (byInterest.length) modules.push({ id: "by-interest", kind: "interestTabs", title: tx("اكتشف مكة حسب اهتماماتك", "Discover Makkah by your interests"), sub: tx("اخترتها عند إنشاء حسابك — غيّرها من حسابك متى شئت", "You chose these when you created your account — change them any time"), groups: byInterest });

  /* 11.3 don't miss in Makkah — an editorial selection of real places */
  const must = MUST_DO.map(getObj).filter((o) => o && isPromotable(o)).map((o) => ({ o, why: [] }));
  /* the lead card is one with its own photograph; places without one follow as rows */
  const mustItems = take(rank(must.map((x) => x.o), ctx, { limit: 12, maxPerCategory: 12, maxPerNeighborhood: 12 }).sort((a, b) => (!!b.o.pt) - (!!a.o.pt)), 6);
  if (mustItems.length) modules.push({ id: "must-do", kind: "hero+rows", title: tx("لا تفوّت في مكة", "Don't miss in Makkah"), sub: tx("مختارات رحاب مكة من معالم مكة ومتاحفها — ليست ترتيبًا حسب الشعبية", "Rihab Makkah's pick of Makkah's landmarks and museums — not a popularity ranking"), items: mustItems.slice(0, 4), kicker: tx("من الأساسيات", "An essential") });

  /* 11.4 experiences that suit you */
  const fit = rank(pool.filter((o) => ["experience", "activity", "event", "place"].includes(o.type) && !o.venue && o.type !== "recurring"), ctx, { limit: 10, maxPerCategory: 2 });
  const fitItems = take(fit, 5);
  const ctxLine = [STAY[p.stay] && tx(STAY[p.stay].ar, STAY[p.stay].en), PARTY[p.party] && tx(PARTY[p.party].ar, PARTY[p.party].en)].filter(Boolean).join(" · ");
  if (fitItems.length) modules.push({ id: "for-you", kind: "scroller", title: tx("تجارب مناسبة لك", "Experiences that suit you"), sub: ctxLine ? tx(`حسب زيارتك: ${ctxLine}`, `For your visit: ${ctxLine}`) : undefined, items: fitItems });

  /* 11.5 what to do today — dated or open-now items only */
  const today = rank(pool.filter((o) => !["stay", "services"].includes(o.category) && (happensToday(o) || (o.timing?.kind === "hours" && isOpenNow(o) === true && !o.real && o.type !== "restaurant"))), ctx, { limit: 8, maxPerCategory: 2 });
  const todayItems = take(today, 4);
  if (todayItems.length) modules.push({ id: "today", kind: "rows", title: tx("ماذا تفعل اليوم؟", "What to do today"), sub: tx("ما يحدث اليوم أو مفتوح الآن حسب بياناته", "Happening today, or open now by its listed hours"), items: todayItems });

  /* 11.6 restaurants & cafés — real places */
  const food = rank(pool.filter((o) => o.real && ["food", "cafe"].includes(o.category)), { ...ctx, nb: ctx.nb || "haram-area", from: ctx.from || { x: NB["haram-area"].x, y: NB["haram-area"].y } }, { limit: 12, maxPerCategory: 6, maxPerNeighborhood: 3 });
  const foodItems = take(food, 6);
  if (foodItems.length) modules.push({ id: "food", kind: "scroller", title: tx("مطاعم ومقاهٍ", "Restaurants & cafés"), sub: ctx.nb ? tx(`قريبة من ${NB[ctx.nb].name}`, `Near ${NB[ctx.nb].name}`) : tx("حول الحرم وفي أحياء مكة", "Around the Haram and across Makkah"), items: foodItems, action: { label: tx("المزيد", "More"), to: { s: "discover", cat: "food" } } });

  /* 11.7 Makkah culture & history */
  const culture = rank(pool.filter((o) => o.real && o.id !== "haram" && ["culture", "heritage", "nature", "learn"].includes(o.category)), ctx, { limit: 12, maxPerCategory: 6, maxPerNeighborhood: 3 });
  const cultureItems = take(culture, 6);
  if (cultureItems.length) modules.push({ id: "culture", kind: "scroller", title: tx("ثقافة وتاريخ مكة", "Makkah's culture & history"), sub: tx("متاحف ومعالم ومساجد تاريخية", "Museums, landmarks and historic mosques"), items: cultureItems });

  /* 11.8 near you now — only from an area the visitor gave; never a guessed position */
  if (ctx.nb) {
    const nearby = rank(pool.filter((o) => o.neighborhood === ctx.nb || distanceKm(o, ctx.from) < 2.5), ctx, { limit: 8, maxPerCategory: 2, maxPerNeighborhood: 8 });
    const nearItems = take(nearby, 4);
    if (nearItems.length) modules.push({ id: "nearby", kind: "rows", title: tx("قريب منك الآن", "Near you now"), sub: tx(`حول ${NB[ctx.nb].name} — المنطقة التي اخترتها، لا موقعك المباشر`, `Around ${NB[ctx.nb].name} — the area you chose, not your live location`), items: nearItems });
  } else modules.push({ id: "nearby", kind: "whereNow", title: tx("قريب منك الآن", "Near you now"), sub: tx("لا نستخدم موقعك المباشر. اختر المنطقة التي أنت فيها", "We don't use your live location. Pick the area you're in") });

  /* 11.9 build your trip — the bridge to My Plan */
  const hours = ctx.timeAvailable ? ctx.timeAvailable / 60 : 4;
  modules.push({ id: "build-trip", kind: "tripBridge", title: tx("ابنِ رحلتك", "Build your trip"), sub: tx("حوّل ما يعجبك إلى أيام مرتّبة في «خطتي»", "Turn what you like into ordered days in My Plan"), outings: buildOutings(ctx, state, hours) });

  /* «فرص مكة»: an extended stay, a move to Makkah, or a business idea */
  modules.push({ id: "city-ops", kind: "cityOps", title: tx("فرص مكة", "Makkah Opportunities"), sub: tx("للإقامات الممتدة أو الانتقال إلى مكة، وفرص الأعمال فيها", "For extended stays or a move to Makkah, and business opportunities here") });

  /* 11.10 services a visitor needs */
  const svc = rank(pool.filter((o) => o.type === "service" || o.category === "services" || o.category === "stay"), ctx, { limit: 6, maxPerCategory: 3, maxPerNeighborhood: 6 });
  const svcItems = take(svc, 3);
  if (svcItems.length) modules.push({ id: "visitor-services", kind: "rows", title: tx("خدمات يحتاجها الزائر", "Services visitors need"), sub: tx("نقل وإرشاد وإقامة — الحجز والتأكيد لدى مقدّم الخدمة", "Transport, guidance and stays — booking and confirmation stay with the provider"), items: svcItems });

  /* 11.11 tips from Makkah's community */
  const VISITOR_COMS = ["firstvisit", "visitors-en", "visitors-ur", "visitors-id", "first-umrah", "after-umrah", "accessible", "local-food", "heritage", "museums"];
  const tips = allContributions(state).filter((k) => !k.parent && ["question", "tip", "answer", "recommendation", "experience_report"].includes(k.type) && k.communities.some((c) => VISITOR_COMS.includes(c)))
    .sort((a, b) => (b.helpful || 0) - (a.helpful || 0)).slice(0, 3);
  if (tips.length) modules.push({ id: "tips", kind: "community", title: tx("نصائح من مجتمع مكة", "Tips from Makkah's community"), sub: tx("أسئلة زوار ونصائح عملية من سكان مكة", "Visitors' questions and practical advice from Makkah residents"), items: tips });
  return modules;
}

