            <button className="press" onClick={() => { if (!joined) { dispatch({ type: "join_community", com: hood.id }); toast(tx("انضممت لمجتمع حيّك", "You joined your neighbourhood community")); } else go({ s: "community", id: hood.id }); }}
              style={{ minHeight: 36, padding: "6px 13px", borderRadius: R.pill, background: joined ? T.paper : T.deep, color: joined ? T.ink : T.onDeep, border: `1px solid ${joined ? T.line : T.deep}`, fontSize: 12.5, fontWeight: 800 }}>
              {joined ? tx("افتح", "Open") : tx("انضم", "Join")}
            </button>
