/* the visitor's bridge from discovery to a day-by-day trip in My Plan */
function TripBridge({ outings }) {
  const { state, go } = useApp();
  const p = state.profile;
  const saved = state.plan.filter((x) => x.state === "saved").length + Object.keys(state.saved).filter((id) => !state.plan.some((x) => x.obj === id)).length;
  /* what the plan actually holds: items with a time during the visit, items without one */
  const g = tripGroups(state.plan, p);
  const dated = g.days.flat().length, usedDays = g.days.filter((l) => l.length).length, undated = g.undated.length, later = g.after.length;
  const total = g.now.length + dated + undated + later;
  const steps = (n) => countAr(n, "خطوة واحدة", "خطوتان", "خطوات", "خطوة");
  const summaryAr = total === 0 ? "لا شيء في خطتك بعد" : [
    `${steps(total)} في خطتك`,
    g.now.length ? `${countAr(g.now.length, "واحدة", "اثنتان", "خطوات", "خطوة")} جارية الآن` : null,
    dated ? `${dated === total ? "كلها" : countAr(dated, "واحدة", "اثنتان", "خطوات", "خطوة")} بموعد ${usedDays === 1 ? "في يوم واحد" : `على ${countAr(usedDays, "يوم واحد", "يومين", "أيام", "يومًا")}`} من رحلتك` : null,
    undated ? `${undated === total ? "كلها" : countAr(undated, "واحدة", "اثنتان", "خطوات", "خطوة")} بلا موعد محدد` : null,
    later ? `${countAr(later, "واحدة", "اثنتان", "خطوات", "خطوة")} بعد أيام رحلتك` : null,
  ].filter(Boolean).join("، ");
  const summaryEn = total === 0 ? "Nothing in your plan yet" : [
    `${plural(total, "step")} in your plan`,
    g.now.length ? `${g.now.length} happening now` : null,
    dated ? `${dated === total ? "all" : dated} with a set time ${usedDays === 1 ? "on one day" : `across ${usedDays} days`} of your trip` : null,
    undated ? `${undated === total ? "all" : undated} without a set time` : null,
    later ? `${later} after your trip's days` : null,
  ].filter(Boolean).join(", ");
  return (
    <div>
      <div style={{ padding: "0 16px" }}>
        <button data-trip-bridge data-dated={dated} data-undated={undated} data-later={later} data-now={g.now.length} className="press" onClick={() => go({ s: "plan" })}
          style={{ display: "block", width: "100%", textAlign: "start", padding: "14px", borderRadius: R.box, background: T.tint, border: `1px solid ${T.line}` }}>
          <div className="row" style={{ gap: 9 }}>
            <CalendarCheck size={18} color={T.green} />
            <span style={{ fontSize: 15, fontWeight: 800 }}>{tx("رحلتي في مكة", "My Makkah trip")}</span>
          </div>
          <div style={{ fontSize: 12.5, color: T.muted, marginTop: 6, lineHeight: 1.75 }}>
            {tx(`${summaryAr}${saved ? `. و${countAr(saved, "عنصر محفوظ", "عنصران محفوظان", "عناصر محفوظة", "عنصرًا محفوظًا")}` : ""}.`,
              `${summaryEn}${saved ? `. ${saved} saved` : ""}.`)}
          </div>
          <div className="row" style={{ gap: 6, marginTop: 9, fontSize: 13, fontWeight: 800, color: T.green }}>{tx("افتح رحلتي", "Open my trip")}<ChevronLeft size={14} /></div>
        </button>
      </div>
      {outings.length > 0 && (
        <>
          <div style={{ fontSize: 13, fontWeight: 800, padding: "14px 16px 8px" }}>{tx("أو ابدأ بمسار جاهز من أماكن قريبة بعضها من بعض", "Or start from a ready route of places close to each other")}</div>
          <OutingsRow items={outings} />
        </>
      )}
    </div>
  );
}

