const OPP_BY = byId(OPPORTUNITIES);

/* ───────── the request record ─────────
   One record per home or opportunity: { id, kind: home | opp, ref, purpose: interest | info,
   note, at (last change), first (first recorded) }. It lives on this device, per account. */
const REQUEST_KIND = {
  product: { label: ["منتج", "Product"], act: ["اطلب المنتج", "Request this product"] },
  service: { label: ["خدمة", "Service"], act: ["اطلب الخدمة", "Request this service"] },
  home: { label: ["سكن", "Home"], interest: ["سجّل اهتمامك", "Register interest"], info: ["اطلب التفاصيل", "Request details"] },
  opp: { label: ["فرصة أعمال", "Business opportunity"], interest: ["سجّل اهتمامك", "Register interest"], info: ["اطلب معلومات إضافية", "Request more information"] },
};
const REQUEST_PURPOSE = { interest: ["تسجيل اهتمام", "Registered interest"], info: ["طلب معلومات", "Information request"] };
function requestTarget(kind, ref) {
  if (kind === "product") { const p = PRODUCT[ref]; return p && { title: L2(p.n), sub: L2(p.t), photo: p.photo, to: { s: "product", id: ref } }; }
  if (kind === "service") { const o = getObj(ref); return o && { title: o.name, sub: Dj([o.typeLabel, NB[o.neighborhood]?.name]), photo: o.photo, obj: o, to: { s: "object", id: ref } }; }
  if (kind === "home") { const h = HOME_BY[ref]; return h && { title: L2(h.n), sub: Dj([L2(HOME_DEAL[h.deal].name), L2(h.kind), NB[h.nb]?.name]), photo: h.photo, to: { s: "estate", id: ref } }; }
  if (kind === "opp") { const o = OPP_BY[ref]; return o && { title: L2(o.n), sub: Dj([L2(OPP_CAT[o.cat].name), NB[o.nb]?.name]), photo: o.photo, to: { s: "opp", id: ref } }; }
  return null;
}
const requestFor = (state, kind, ref) => (state.requests || []).find((r) => r.kind === kind && r.ref === ref) || null;
const requestKey = (uid) => `rihab.makkah.requests.v1.${uid}`;
const RequestStore = {
  load(uid) { const r = store.get(requestKey(uid)); return r ? reviveDates(r.requests || []) : []; },
  save(uid, requests) { store.set(requestKey(uid), { requests }); },
  remove(uid) { store.del(requestKey(uid)); },
};

function InfoNote({ children }) {
  return (
    <div data-info-note className="row" style={{ gap: 9, alignItems: "flex-start", padding: "11px 12px", borderRadius: R.box, background: T.sand, marginTop: 14 }}>
      <Info size={15} color={T.green} style={{ flex: "0 0 15px", marginTop: 3 }} />
      <div style={{ fontSize: 12.5, color: T.ink, lineHeight: 1.8 }}>{children}</div>
    </div>
  );
}
function RequestedPill({ r }) {
  if (!r) return null;
  return <Pill tone={T.ok} bg={`${T.ok}14`} icon={Check}>{r.purpose === "info" ? tx("طلبك مسجّل", "Request recorded") : tx("اهتمامك مسجّل", "Interest registered")}</Pill>;
}
/* a detail screen's photo header, with Back */
function DetailHero({ photo, seed }) {
  const { go } = useApp();
  return (
    <div style={{ position: "relative" }}>
      <Photo kind="skyline" seed={seed} photo={photo} ratio="4 / 3" radius={0} scrim="soft" />
      <button className="press tap" onClick={() => go({ back: true })} aria-label="رجوع"
        style={{ position: "absolute", insetInlineStart: 14, top: "calc(14px + var(--safe-top))", width: 40, height: 40, borderRadius: R.pill, background: "rgba(20,24,22,.46)", color: "#F6EFE0", display: "grid", placeItems: "center", backdropFilter: "blur(6px)" }}>
        <ChevronRight size={20} />
      </button>
    </div>
  );
}
/* the two actions a home or opportunity page ends with: register interest, or ask for more */
function RequestActions({ kind, r, onOpen }) {
  const K = REQUEST_KIND[kind];
  return (
    <div style={{ position: "sticky", bottom: 0, zIndex: 40, padding: "12px 16px 14px", marginTop: "auto",
      background: "linear-gradient(180deg, rgba(249,246,236,0) 0%, rgba(249,246,236,.96) 30%, #F9F6EC 100%)" }}>
      <div data-request-hint style={{ fontSize: 11.5, color: T.muted, textAlign: "center", marginBottom: 8, lineHeight: 1.7 }}>
        {r ? tx(`سجّلته ${agoAr(r.at)} — تجده في «طلباتي»`, `Recorded ${agoAr(r.at)} — you'll find it in My requests`) : tx("تجد طلبك بعد تسجيله في «طلباتي»", "Once recorded, your request is in My requests")}
      </div>
      <div className="row" style={{ gap: 9 }}>
        <button className="press" data-request-open={kind} data-purpose="interest" onClick={() => onOpen("interest")}
          style={{ flex: 1.2, minWidth: 0, minHeight: 48, padding: "8px 10px", borderRadius: R.ctl, background: r ? T.paper : T.deep, color: r ? T.ink : T.onDeep, border: r ? `1px solid ${T.line}` : "none", fontWeight: 800, fontSize: 14 }}>
          {r ? (r.purpose === "info" ? tx("طلبك مسجّل — عدّله", "Request recorded — edit it") : tx("اهتمامك مسجّل — عدّله", "Interest registered — edit it")) : L2(K.interest)}
        </button>
        {!r && (
          <button className="press" data-request-open={kind} data-purpose="info" onClick={() => onOpen("info")}
            style={{ flex: 1, minWidth: 0, minHeight: 48, padding: "8px 10px", borderRadius: R.ctl, background: T.paper, color: T.ink, border: `1px solid ${T.line}`, fontWeight: 800, fontSize: 13.5 }}>
            {L2(K.info)}
          </button>
        )}
      </div>
    </div>
  );
}

/* Register interest or ask for details. The record stays on the device; the sheet says so before and after. */
function RequestSheet({ kind, refId, open, onClose, purpose: initialPurpose = "interest" }) {
  const { state, dispatch, go } = useApp();
  const target = requestTarget(kind, refId);
  const prior = requestFor(state, kind, refId);
  const [purpose, setPurpose] = useState(initialPurpose);
  const [qty, setQty] = useState(1);
  const [note, setNote] = useState("");
  const choose = kind === "home" || kind === "opp";
  const [done, setDone] = useState(false);
  useEffect(() => { if (open) { setPurpose(prior?.purpose || initialPurpose); setQty(prior?.qty || 1); setNote(prior?.note || ""); setDone(false); } /* eslint-disable-next-line */ }, [open]);
  if (!target) return null;
  const K = REQUEST_KIND[kind];
  const submit = () => { dispatch({ type: "request_add", kind, ref: refId, purpose: choose ? purpose : null, qty: kind === "product" ? qty : null, note: note.trim() || null }); setDone(true); };
  return (
    <Sheet open={open} onClose={onClose} title={done ? (!choose || purpose === "info" ? tx("سُجّل طلبك", "Request recorded") : tx("سُجّل اهتمامك", "Interest registered")) : prior ? tx("عدّل طلبك", "Edit your request") : !choose ? L2(K.act) : L2(purpose === "info" ? K.info : K.interest)}>
      <div data-request-sheet={kind} className="row" style={{ gap: 11, padding: "4px 0 12px", borderBottom: `1px solid ${T.lineSoft}` }}>
        <div style={{ width: 56, flex: "0 0 56px" }}><Photo kind="skyline" seed={refId} photo={target.photo} ratio="1 / 1" radius={R.ctl} scrim="none" /></div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 14.5, fontWeight: 800, lineHeight: 1.5 }}>{target.title}</div>
          <div style={{ fontSize: 12, color: T.muted, marginTop: 2 }}>{target.sub}</div>
        </div>
      </div>
      {!done ? (
        <div>
          {choose && <>
          <div style={{ fontSize: 13.5, fontWeight: 800, margin: "14px 0 8px" }}>{tx("ماذا تريد؟", "What would you like?")}</div>
          <div className="row" style={{ gap: 8, flexWrap: "wrap" }}>
            {["interest", "info"].map((p) => (
              <span key={p} data-request-purpose={p}><Chip active={purpose === p} onClick={() => setPurpose(p)} icon={p === "interest" ? Star : Info}>{L2(p === "interest" ? K.interest : K.info)}</Chip></span>
            ))}
          </div>
          </>}
          {kind === "product" && (
            <div className="row" style={{ justifyContent: "space-between", padding: "14px 0 4px" }}>
              <span style={{ fontSize: 13.5, fontWeight: 800 }}>{tx("الكمية", "Quantity")}</span>
              <div className="row" style={{ gap: 6 }}>
                <button className="press" aria-label={tx("أقل", "Fewer")} onClick={() => setQty((n) => Math.max(1, n - 1))} style={{ width: 44, height: 44, borderRadius: R.pill, border: `1px solid ${T.line}`, display: "grid", placeItems: "center" }}><Minus size={16} /></button>
                <span data-request-qty style={{ minWidth: 30, textAlign: "center", fontSize: 16, fontWeight: 800 }}>{ar(qty)}</span>
                <button className="press" aria-label={tx("أكثر", "More")} onClick={() => setQty((n) => Math.min(10, n + 1))} style={{ width: 44, height: 44, borderRadius: R.pill, border: `1px solid ${T.line}`, display: "grid", placeItems: "center" }}><Plus size={16} /></button>
              </div>
            </div>
          )}
          <label style={{ display: "block", fontSize: 13.5, fontWeight: 800, margin: "14px 0 6px" }} htmlFor="request-note">
            {kind === "opp" ? tx("ما الذي يهمك في هذه الفرصة؟ (اختياري)", "What interests you about it? (optional)") : tx("ملاحظة (اختياري)", "A note (optional)")}
          </label>
          <textarea id="request-note" value={note} onChange={(e) => setNote(e.target.value)} rows={3} dir="auto" maxLength={300}
            placeholder={kind === "home" ? tx("مثلًا: موعد الانتقال أو عدد أفراد الأسرة", "For example: when you'd move, or how many in the family") : kind === "service" ? tx("مثلًا: اليوم والوقت المناسبين، أو عدد الأشخاص", "For example: the day and time that suit you, or how many people") : kind === "product" ? tx("مثلًا: للهدية، أو تغليف خاص", "For example: it's a gift, or special wrapping") : tx("مثلًا: خبرتك في هذا المجال، أو ما تريد معرفته", "For example: your experience in this field, or what you'd like to know")}
            style={{ width: "100%", resize: "none", background: T.limestone, border: `1px solid ${T.line}`, borderRadius: R.ctl, padding: "10px 12px", fontSize: 13.5, lineHeight: 1.7, outline: "none" }} />
          <InfoNote>{L2(REQUEST_NOTE)}{kind === "opp" ? " " + tx("تسجيل الاهتمام ليس استثمارًا ولا التزامًا.", "Registering interest is not an investment or a commitment.") : " " + tx("ليس حجزًا ولا عقدًا.", "It isn't a booking or a contract.")}</InfoNote>
          <button className="press" data-request-submit onClick={submit}
            style={{ width: "100%", marginTop: 16, height: 48, borderRadius: R.ctl, background: T.deep, color: T.onDeep, fontWeight: 800, fontSize: 14.5 }}>
            {prior ? tx("حدّث الطلب", "Update the request") : !choose || purpose === "info" ? tx("سجّل الطلب", "Record the request") : tx("سجّل اهتمامي", "Register my interest")}
          </button>
        </div>
      ) : (
        <div data-request-done style={{ paddingTop: 16, textAlign: "center" }}>
          <div style={{ width: 52, height: 52, borderRadius: 99, background: `${T.ok}18`, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={24} color={T.ok} /></div>
          <div style={{ fontSize: 15, fontWeight: 800, lineHeight: 1.7 }}>{tx("أضفناه إلى «طلباتي».", "Added to My requests.")}</div>
          <div style={{ fontSize: 13, color: T.muted, lineHeight: 1.8, marginTop: 6 }}>{tx("تقدر تعدّله أو تسحبه من «طلباتي» في أي وقت.", "You can edit or withdraw it from My requests at any time.")}</div>
          <div className="row" style={{ gap: 9, marginTop: 18 }}>
            <button className="press" data-request-view onClick={() => { onClose(); go({ s: "requests" }); }} style={{ flex: 1, minHeight: 46, borderRadius: R.ctl, background: T.deep, color: T.onDeep, fontWeight: 800, fontSize: 13.5 }}>{tx("اعرض طلباتي", "View my requests")}</button>
            <button className="press" onClick={onClose} style={{ flex: 1, minHeight: 46, borderRadius: R.ctl, background: T.paper, border: `1px solid ${T.line}`, fontWeight: 800, fontSize: 13.5 }}>{tx("تم", "Done")}</button>
          </div>
        </div>
      )}
    </Sheet>
  );
}

/* a screen header for these screens: Back (when pushed), title and a line under it */
function PageHead({ title, sub, back, trailing }) {
  const { go } = useApp();
  return (
    <div style={{ padding: "14px 16px 10px", paddingTop: "calc(14px + var(--safe-top))" }}>
      <div className="row" style={{ gap: 8, justifyContent: "space-between" }}>
        <div className="row" style={{ gap: 6, minWidth: 0 }}>
          {back && <button className="press tap" onClick={() => go({ back: true })} aria-label="رجوع" style={{ width: 36, height: 36, display: "grid", placeItems: "center", marginInlineStart: -6, flex: "0 0 36px" }}><ChevronRight size={23} /></button>}
          <div style={{ fontSize: 21, fontWeight: 800, letterSpacing: "-.02em" }}>{title}</div>
        </div>
        {trailing}
      </div>
      {sub && <div style={{ fontSize: 12.5, color: T.muted, marginTop: 4, lineHeight: 1.6 }}>{sub}</div>}
    </div>
  );
}
function RequestsButton() {
  const { state, go } = useApp();
  const n = (state.requests || []).length;
  return (
    <button className="press row" data-requests-entry onClick={() => go({ s: "requests" })}
      style={{ gap: 6, minHeight: 36, padding: "6px 12px", borderRadius: R.pill, background: T.paper, border: `1px solid ${T.line}`, fontSize: 12.5, fontWeight: 800, flex: "0 0 auto" }}>
      <ClipboardList size={15} />{tx("طلباتي", "My requests")}
      {n > 0 && <span style={{ minWidth: 18, height: 18, padding: "0 5px", borderRadius: 99, background: T.clay, color: "#FFFCF6", fontSize: 10.5, display: "grid", placeItems: "center" }}>{ar(n)}</span>}
    </button>
  );
}

/* ───────── السوق ───────── */

/* a page's single action, kept above the bottom edge */
function StickyAction({ label, onClick, note, done, data }) {
  return (
    <div style={{ position: "sticky", bottom: 0, zIndex: 40, padding: "12px 16px 14px", marginTop: "auto",
      background: "linear-gradient(180deg, rgba(249,246,236,0) 0%, rgba(249,246,236,.96) 30%, #F9F6EC 100%)" }}>
      {note && <div style={{ fontSize: 11.5, color: T.muted, textAlign: "center", marginBottom: 8, lineHeight: 1.7 }}>{note}</div>}
      <button className="press" data-request-open={data} onClick={onClick}
        style={{ width: "100%", height: 48, borderRadius: R.ctl, background: done ? T.paper : T.deep, color: done ? T.ink : T.onDeep, border: done ? `1px solid ${T.line}` : "none", fontWeight: 800, fontSize: 14.5 }}>
        {label}
      </button>
    </div>
  );
}

const MARKET_TABS = [
  { id: "experiences", name: ["التجارب", "Experiences"], icon: Sparkles },
  { id: "services", name: ["الخدمات", "Services"], icon: Wrench },
  { id: "products", name: ["المنتجات", "Products"], icon: ShoppingBag },
];
/* experiences: tours, workshops, local experiences and events from the shared inventory */
const EXP_FILTERS = [
  { id: "all", name: ["الكل", "All"], test: () => true },
  { id: "tours", name: ["جولات", "Tours"], test: (o) => /(جول|مسار|مشي|مشية|زياره|زيارة)/.test(o.n) },
  { id: "workshops", name: ["ورش", "Workshops"], test: (o) => /ورش/.test(o.n) || ["craft", "learn"].includes(o.category) },
  { id: "local", name: ["تجارب محلية", "Local experiences"], test: (o) => o.type === "experience" },
  { id: "events", name: ["فعاليات", "Events"], test: (o) => o.type === "event" },
];
/* services: what a person can request — guides, transport, hospitality and stays, translation */
const SERVICE_FILTERS = [
  { id: "all", name: ["الكل", "All"], test: () => true },
  { id: "guides", name: ["إرشاد وجولات", "Guides & tours"], test: (o) => /مرشد/.test(o.n) },
  { id: "transport", name: ["نقل", "Transport"], test: (o) => /نقل/.test(o.n) },
  { id: "hospitality", name: ["ضيافة وإقامة", "Hospitality & stays"], test: (o) => o.category === "stay" || /ضياف/.test(o.n) },
  { id: "translation", name: ["ترجمة", "Translation"], test: (o) => /ترجم/.test(o.n) },
  { id: "other", name: ["خدمات أخرى", "Other services"], test: (o) => !/(مرشد|نقل|ضياف|ترجم)/.test(o.n) && o.category !== "stay" },
];
const HOSTED_EXPERIENCE = "x-family-host";   // hosted by a Makkan family: hospitality you can book
const marketExperiences = () => INVENTORY.filter((o) => ["experience", "event", "activity"].includes(o.type) && !o.real && isPromotable(o) && !NOT_RUNNING.includes(lifecycleOf(o)));
const marketServices = () => INVENTORY.filter((o) => (o.type === "service" || (o.category === "stay" && !o.real) || o.id === HOSTED_EXPERIENCE) && isPromotable(o));

function ScreenMarket({ params }) {
  const { state, ctx, go } = useApp();
  const [tab, setTab] = useViewState("marketTab", params?.tab || "experiences");
  const [filter, setFilter] = useViewState("marketFilter", "all");
  const pickTab = (t) => { setTab(t); setFilter("all"); };
  const open = (state.requests || []).length;
  const filters = tab === "experiences" ? EXP_FILTERS : tab === "services" ? SERVICE_FILTERS : [{ id: "all", name: ["الكل", "All"] }, ...PRODUCT_CATS];
  const list = useMemo(() => {
    if (tab === "products") return PRODUCTS.filter((p) => filter === "all" || p.cat === filter);
    const f = filters.find((x) => x.id === filter) || filters[0];
    const pool = (tab === "experiences" ? marketExperiences() : marketServices()).filter((o) => f.test(o));
    return rank(pool, ctx, { limit: 40, maxPerCategory: 40, maxPerNeighborhood: 40 });
  }, [tab, filter, ctx]);   // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="screen scroll" data-market style={{ paddingBottom: 96 }}>
      <PageHead back={!!params?.pushed} title={tx("السوق", "Market")} sub={tx("تجارب وخدمات ومنتجات من مكة — احجزها أو اطلبها", "Experiences, services and products from Makkah — book or request them")}
        trailing={(
          <button className="press row" data-requests-entry onClick={() => go({ s: "requests" })}
            style={{ gap: 6, minHeight: 36, padding: "6px 12px", borderRadius: R.pill, background: T.paper, border: `1px solid ${T.line}`, fontSize: 12.5, fontWeight: 800, flex: "0 0 auto" }}>
            <ClipboardList size={15} />{tx("طلباتي", "My requests")}
            {open > 0 && <span style={{ minWidth: 18, height: 18, padding: "0 5px", borderRadius: 99, background: T.clay, color: T.onDeep, fontSize: 10.5, display: "grid", placeItems: "center" }}>{ar(open)}</span>}
          </button>
        )} />
      <div className="row" style={{ gap: 8, padding: "0 16px 12px" }}>
        {MARKET_TABS.map((t) => {
          const on = t.id === tab; const Icon = t.icon;
          return (
            <button key={t.id} className="press" data-market-tab={t.id} aria-pressed={on ? "true" : "false"} onClick={() => pickTab(t.id)}
              style={{ flex: 1, minWidth: 0, minHeight: 64, padding: "9px 4px", borderRadius: R.box, background: on ? T.deep : T.paper, color: on ? T.onDeep : T.ink,
                border: `1px solid ${on ? T.deep : T.line}`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 5 }}>
              <Icon size={19} strokeWidth={2} />
              <span style={{ fontSize: 13, fontWeight: 800 }}>{L2(t.name)}</span>
            </button>
          );
        })}
      </div>
      <div className="rail scroll" style={{ paddingBottom: 12 }}>
        {filters.map((f) => <Chip key={f.id} active={filter === f.id} onClick={() => setFilter(f.id)}>{L2(f.name)}</Chip>)}
      </div>
      {tab === "products" ? (
        <div style={{ padding: "0 16px" }}>
          <div style={{ fontSize: 12.5, color: T.muted, lineHeight: 1.7, marginBottom: 12 }}>{tx("منتجات محلية تطلبها من داخل التطبيق: تمور وهدايا وحرف وعطور.", "Local products you can request in the app: dates, gifts, crafts and perfumes.")}</div>
          <div data-product-grid style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            {list.map((p) => <ProductCard key={p.id} p={p} />)}
          </div>
        </div>
      ) : (
        <div style={{ padding: "0 16px" }}>
          <div style={{ fontSize: 12.5, color: T.muted, lineHeight: 1.7, marginBottom: 4 }}>
            {tab === "experiences" ? tx("جولات وورش وتجارب محلية وفعاليات — الحجز والانضمام من صفحة كل تجربة.", "Tours, workshops, local experiences and events — book or join from each one's page.")
              : tx("مرشدون ونقل وضيافة وترجمة وخدمات أخرى — اطلب الخدمة من صفحتها.", "Guides, transport, hospitality, translation and more — request each service from its page.")}
          </div>
          {list.length ? list.map((x) => <RowCard key={x.o.id} x={x} showWhy={false} kindPill />)
            : <EmptyState title={tx("لا شيء هنا الآن", "Nothing here right now")} body={tx("جرّب تصنيفًا آخر.", "Try another category.")} />}
        </div>
      )}
    </div>
  );
}

function ProductCard({ p }) {
  const { state, go } = useApp();
  const r = requestFor(state, "product", p.id);
  return (
    <button className="lift" data-product={p.id} onClick={() => go({ s: "product", id: p.id })} style={{ textAlign: "start", minWidth: 0 }}>
      <Photo kind="market" seed={p.id} photo={p.photo} ratio="1 / 1" radius={R.box} scrim="none" />
      <div style={{ fontSize: 14, fontWeight: 800, lineHeight: 1.45, marginTop: 7 }}>{L2(p.n)}</div>
      <div style={{ fontSize: 12, color: T.muted, marginTop: 2, lineHeight: 1.5 }}>{L2(p.t)}</div>
      <div className="row" style={{ gap: 6, marginTop: 5, flexWrap: "wrap" }}>
        <span style={{ fontSize: 13, fontWeight: 800, color: T.green }}>{riyal(p.price)}{p.unit ? ` ${L2(p.unit)}` : ""}</span>
        <RequestedPill r={r} />
      </div>
    </button>
  );
}

function ScreenProduct({ id }) {
  const { state } = useApp();
  const p = PRODUCT[id];
  const [open, setOpen] = useState(false);
  if (!p) return <EmptyState title={tx("لم نعد نجد هذا المنتج", "We can't find this product")} body={tx("ربما أُزيل من السوق.", "It may have been removed from the Market.")} />;
  const r = requestFor(state, "product", p.id);
  const more = PRODUCTS.filter((x) => x.id !== p.id && x.cat === p.cat).concat(PRODUCTS.filter((x) => x.cat !== p.cat)).slice(0, 4);
  return (
    <div className="screen scroll" data-product-page={p.id} style={{ display: "flex", flexDirection: "column", minHeight: "100%" }}>
      <DetailHero photo={p.photo} seed={p.id} />
      <div style={{ padding: "16px 16px 0" }}>
        <div className="row" style={{ gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
          <Pill tone={T.green} bg={T.tint}>{L2(PRODUCT_CAT[p.cat].name)}</Pill>
          <RequestedPill r={r} />
        </div>
        <div style={{ fontSize: 23, fontWeight: 800, lineHeight: 1.35 }}>{L2(p.n)}</div>
        <div style={{ fontSize: 14, color: T.muted, marginTop: 4 }}>{L2(p.t)}</div>
        <div className="row" style={{ gap: 8, marginTop: 10, flexWrap: "wrap" }}>
          <span data-product-price style={{ fontSize: 19, fontWeight: 800, color: T.green }}>{riyal(p.price)}{p.unit ? ` ${L2(p.unit)}` : ""}</span>
          <span style={{ fontSize: 11.5, color: T.muted, fontWeight: 700 }}>{tx("سعر تقديري", "Indicative price")}</span>
        </div>
        <div style={{ fontSize: 14.5, lineHeight: 1.95, marginTop: 12 }}>{L2(p.ab)}</div>
      </div>
      {p.facts.length > 0 && (
        <div style={{ padding: "18px 16px 0" }}>
          <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 4 }}>{tx("تفاصيل المنتج", "Product details")}</div>
          {p.facts.map(([l, v]) => <FactRow key={l[0]} label={L2(l)} value={L2(v)} />)}
        </div>
      )}
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{tx("لا يتم البيع أو الدفع عبر التطبيق. يُحفظ طلبك في «طلباتي»، وتقدر تعدّله أو تسحبه في أي وقت.", "Nothing is sold or paid for in the app. Your request is saved in My requests, where you can edit or withdraw it at any time.")}</InfoNote>
      </div>
      <div style={{ padding: "24px 0 0" }}>
        <SectionTitle title={tx("من السوق أيضًا", "More from the Market")} />
        <div className="rail scroll">
          {more.map((x) => <div key={x.id} style={{ width: "var(--rail-tile)", flex: "0 0 auto" }}><ProductCard p={x} /></div>)}
        </div>
      </div>
      <StickyAction data="product" label={r ? tx("عدّل طلبك", "Edit your request") : L2(REQUEST_KIND.product.act)} done={!!r} onClick={() => setOpen(true)} />
      <RequestSheet kind="product" refId={p.id} open={open} onClose={() => setOpen(false)} />
    </div>
  );
}

/* ───────── طلباتي ───────── */

function ScreenRequests() {
  const { state, dispatch, go, toast } = useApp();
  const [kind, setKind] = useViewState("requestsKind", "all");
  const all = (state.requests || []).slice().sort((a, b) => new Date(b.at) - new Date(a.at));
  const list = all.filter((r) => kind === "all" || r.kind === kind);
  const count = (k) => all.filter((r) => r.kind === k).length;
  return (
    <div className="screen scroll" data-requests style={{ paddingBottom: 96 }}>
      <PageHead back title={tx("طلباتي", "My requests")} sub={tx("الطلبات والاهتمامات التي سجّلتها في السوق وفرص مكة.", "The requests and interest you've recorded in the Market and Makkah Opportunities.")} />
      <div className="rail scroll" style={{ paddingBottom: 4 }}>
        {[["all", tx("الكل", "All"), all.length], ["product", tx("المنتجات", "Products"), count("product")], ["service", tx("الخدمات", "Services"), count("service")], ["home", tx("السكن", "Homes"), count("home")], ["opp", tx("فرص الأعمال", "Business opportunities"), count("opp")]].filter(([k, , n]) => k === "all" || n > 0 || k === kind).map(([k, l, n]) => (
          <span key={k} data-requests-filter={k}><Chip active={kind === k} onClick={() => setKind(k)}>{l} · {ar(n)}</Chip></span>
        ))}
      </div>
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{L2(REQUEST_NOTE)}</InfoNote>
        {!list.length ? (
          <EmptyState icon={ClipboardList} title={tx("لا طلبات بعد", "No requests yet")}
            body={tx("اطلب منتجًا أو خدمة من «السوق»، أو سجّل اهتمامك بسكن أو فرصة في «فرص مكة»، وستجده هنا.", "Request a product or a service in the Market, or register interest in a home or an opportunity in Makkah Opportunities, and you'll find it here.")}
            action={["home", "opp"].includes(kind) ? tx("افتح فرص مكة", "Open Makkah Opportunities") : tx("تصفّح السوق", "Browse the Market")}
            onAction={() => (["home", "opp"].includes(kind) ? go({ s: "city", tab: kind === "opp" ? "invest" : "live" }) : go({ s: "market", pushed: true, tab: kind === "service" ? "services" : kind === "product" ? "products" : "experiences" }))} />
        ) : list.map((r) => {
          const t = requestTarget(r.kind, r.ref);
          if (!t) return null;
          return (
            <div key={r.id} data-request-row={r.kind} data-request-ref={r.ref} className="row" style={{ gap: 11, alignItems: "flex-start", padding: "14px 0", borderBottom: `1px solid ${T.lineSoft}` }}>
              <button className="lift" onClick={() => go(t.to)} aria-label={t.title} style={{ width: 64, flex: "0 0 64px" }}>
                <Photo kind="skyline" seed={r.ref} photo={t.photo} ratio="1 / 1" radius={R.ctl} scrim="none" />
              </button>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div className="row" style={{ gap: 6, flexWrap: "wrap", marginBottom: 4 }}>
                  <Pill tone={T.green} bg={T.tint}>{L2(REQUEST_KIND[r.kind].label)}</Pill>
                  {["home", "opp"].includes(r.kind) && <Pill tone={T.muted} bg={T.sand}>{L2(REQUEST_PURPOSE[r.purpose] || REQUEST_PURPOSE.interest)}</Pill>}
                </div>
                <button className="press" onClick={() => go(t.to)} style={{ textAlign: "start", fontSize: 14.5, fontWeight: 800, lineHeight: 1.5 }}>{t.title}</button>
                <div style={{ fontSize: 12, color: T.muted, marginTop: 2, lineHeight: 1.6 }}>{Dj([t.sub, r.qty ? tx(`الكمية: ${ar(r.qty)}`, `Quantity: ${r.qty}`) : null])}</div>
                <div data-request-status className="row" style={{ gap: 5, marginTop: 6, fontSize: 12, fontWeight: 700, color: T.ok, flexWrap: "wrap", lineHeight: 1.6 }}>
                  <Check size={13} style={{ flex: "0 0 13px" }} /><span>{tx("مسجّل", "Recorded")}</span>
                  <span style={{ color: T.muted, fontWeight: 600 }}>· {r.first && +new Date(r.first) !== +new Date(r.at) ? tx(`حُدّث ${agoAr(r.at)}`, `updated ${agoAr(r.at)}`) : agoAr(r.at)}</span>
                </div>
                {r.note && <div dir="auto" style={{ fontSize: 12.5, marginTop: 5, lineHeight: 1.7, color: T.ink }} translate="no">«{r.note}»</div>}
              </div>
              <button className="press tap" data-request-withdraw onClick={() => { dispatch({ type: "request_remove", id: r.id }); toast(tx("سحبنا الطلب من «طلباتي»", "Removed from My requests")); }}
                style={{ fontSize: 12.5, fontWeight: 800, color: T.warn, minHeight: 36, paddingInline: 6, flex: "0 0 auto" }}>{tx("اسحب", "Withdraw")}</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ───────── فرص مكة ───────── */

/* the Home section: two doors, visibly different, one for living here and one for business */
function CityOpsCards() {
  const { go, state } = useApp();
  const visitor = personaOf(state.profile) === "visitor";
  const cards = [
    { id: "live", photo: "home_living_bright", tone: "rgba(36,70,56,.92)", icon: Home, title: tx("عِش في مكة", "Live in Makkah"),
      sub: visitor ? tx("إقامات ممتدة وسكن مفروش، وشقق وفلل", "Extended stays, furnished homes, apartments and villas") : tx("شقق وفلل للإيجار والتمليك، وإقامات ممتدة", "Apartments and villas to rent or own, and extended stays") },
    { id: "invest", photo: "opp_construction", tone: "rgba(92,62,24,.93)", icon: Briefcase, title: tx("استثمر في مكة", "Invest in Makkah"),
      sub: tx("دليل تعريفي بفرص الأعمال والشراكات", "A directory of business and partnership opportunities") },
  ];
  return (
    <div className="row" style={{ gap: 10, padding: "0 16px", alignItems: "stretch" }}>
      {cards.map((c) => {
        const Icon = c.icon;
        return (
          <button key={c.id} className="lift" data-city-card={c.id} onClick={() => go({ s: "city", tab: c.id })} style={{ flex: 1, minWidth: 0, textAlign: "start", borderRadius: R.media, overflow: "hidden", position: "relative", minHeight: 214 }}>
            <Photo kind="skyline" seed={c.id} photo={c.photo} ratio="4 / 5" radius={R.media} scrim="none" style={{ position: "absolute", inset: 0, height: "100%", aspectRatio: "auto" }}>
              <div style={{ position: "absolute", inset: 0, background: `linear-gradient(180deg, rgba(0,0,0,0) 18%, ${c.tone} 62%)` }} />
            </Photo>
            <div style={{ position: "relative", display: "flex", flexDirection: "column", justifyContent: "flex-end", height: "100%", minHeight: 214, padding: "12px 11px 13px", color: "#F6EFE0" }}>
              <div style={{ width: 32, height: 32, borderRadius: 99, background: "rgba(246,239,224,.18)", display: "grid", placeItems: "center", marginBottom: 8 }}><Icon size={17} color="#E3C78C" /></div>
              <div style={{ fontSize: 16, fontWeight: 800, lineHeight: 1.35 }}>{c.title}</div>
              <div style={{ fontSize: 11.5, lineHeight: 1.6, marginTop: 4, color: "rgba(246,239,224,.9)" }}>{c.sub}</div>
            </div>
          </button>
        );
      })}
    </div>
  );
}

function ScreenCity({ params }) {
  const [tab, setTab] = useViewState("cityTab", params?.tab === "invest" ? "invest" : "live");
  return (
    <div className="screen scroll" data-city={tab} style={{ paddingBottom: 96 }}>
      <PageHead back title={tx("فرص مكة", "Makkah Opportunities")} sub={tx("سكن في مكة، وفرص أعمال تتعرّف عليها.", "Homes in Makkah, and business opportunities to learn about.")} trailing={<RequestsButton />} />
      <div className="row" style={{ gap: 8, padding: "0 16px 14px" }}>
        {[["live", tx("عِش في مكة", "Live in Makkah"), Home], ["invest", tx("استثمر في مكة", "Invest in Makkah"), Briefcase]].map(([id, label, Icon]) => {
          const on = id === tab;
          return (
            <button key={id} className="press row" data-city-tab={id} aria-pressed={on ? "true" : "false"} onClick={() => setTab(id)}
              style={{ flex: 1, minWidth: 0, justifyContent: "center", gap: 7, minHeight: 46, padding: "6px 8px", borderRadius: R.ctl, background: on ? T.deep : T.paper, color: on ? T.onDeep : T.ink, border: `1px solid ${on ? T.deep : T.line}`, fontSize: 13.5, fontWeight: 800 }}>
              <Icon size={16} style={{ flex: "0 0 16px" }} />{label}
            </button>
          );
        })}
      </div>
      {tab === "live" ? <LiveInMakkah /> : <InvestInMakkah />}
    </div>
  );
}

function AreaNote({ nb }) {
  const { go } = useApp();
  const n = NB[nb];
  if (!n || !n.blurb) return null;
  return (
    <div data-area-note style={{ margin: "0 16px 12px", padding: "12px 13px", borderRadius: R.box, background: T.paper, border: `1px solid ${T.line}` }}>
      <div style={{ fontSize: 13.5, fontWeight: 800 }}>{tx(`عن ${n.name}`, `About ${n.name}`)}</div>
      <div style={{ fontSize: 12.5, color: T.muted, lineHeight: 1.75, marginTop: 4 }}>{n.blurb}</div>
      <button className="press tap" onClick={() => go({ s: "discover", nb })} style={{ fontSize: 12.5, fontWeight: 800, color: T.green, minHeight: 36, marginTop: 2 }}>{tx("اكتشف الحي", "Explore the area")}</button>
    </div>
  );
}

function LiveInMakkah() {
  const { state } = useApp();
  const visitor = personaOf(state.profile) === "visitor";
  const [deal, setDeal] = useViewState("homeDeal", "all");
  const [attrs, setAttrs] = useViewState("homeAttrs", []);
  const [area, setArea] = useViewState("homeArea", "all");
  const areas = uniq(HOMES.map((h) => h.nb));
  const toggle = (id) => setAttrs((a) => (a.includes(id) ? a.filter((x) => x !== id) : [...a, id]));
  /* a visitor is most likely to need an extended stay, so those come first */
  const order = (h) => (visitor && h.deal === "stay" ? 0 : 1);
  const list = HOMES.filter((h) => (deal === "all" || h.deal === deal) && (area === "all" || h.nb === area)
    && attrs.every((id) => HOME_ATTRS.find((x) => x.id === id).test(h))).sort((a, b) => order(a) - order(b));
  const clear = () => { setDeal("all"); setAttrs([]); setArea("all"); };
  return (
    <div data-live>
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{tx("شقق وفلل للإيجار والتمليك، وإقامات ممتدة في أحياء مكة. سجّل اهتمامك أو اطلب التفاصيل، وتابع طلبك من «طلباتي».",
          "Apartments and villas to rent or own, and extended stays across Makkah. Register interest or request details, and follow your request in My requests.")}</InfoNote>
      </div>
      <div className="rail scroll" style={{ padding: "14px 0 8px" }}>
        {[{ id: "all", name: ["الكل", "All"] }, ...HOME_DEALS].map((d) => <span key={d.id} data-home-deal={d.id}><Chip active={deal === d.id} onClick={() => setDeal(d.id)}>{L2(d.name)}</Chip></span>)}
      </div>
      <div className="rail scroll" style={{ paddingBottom: 8 }}>
        {HOME_ATTRS.map((a) => <span key={a.id} data-home-attr={a.id}><Chip active={attrs.includes(a.id)} icon={attrs.includes(a.id) ? Check : undefined} onClick={() => toggle(a.id)}>{L2(a.name)}</Chip></span>)}
      </div>
      <div className="rail scroll" style={{ paddingBottom: 12 }}>
        {["all", ...areas].map((a) => <span key={a} data-home-area={a}><Chip icon={a === "all" ? undefined : MapPin} active={area === a} onClick={() => setArea(a)}>{a === "all" ? tx("كل الأحياء", "All areas") : NB[a].name}</Chip></span>)}
      </div>
      {area !== "all" && <AreaNote nb={area} />}
      <div data-result-count style={{ padding: "0 16px 10px", fontSize: 12.5, color: T.muted, fontWeight: 700 }}>
        {tx(countAr(list.length, "سكن واحد", "سكنان", "خيارات سكن", "خيار سكن"), `${list.length} ${list.length === 1 ? "home" : "homes"}`)}
      </div>
      <div style={{ padding: "0 16px", display: "grid", gap: 16 }}>
        {list.length ? list.map((h) => <HomeCard key={h.id} h={h} />)
          : <EmptyState icon={Home} title={tx("لا يوجد سكن بهذا الاختيار", "No homes match this choice")} body={tx("جرّب نوعًا آخر أو حيًّا آخر، أو أزل بعض الخيارات.", "Try another type or area, or remove some options.")} action={tx("أزل الخيارات", "Clear the options")} onAction={clear} />}
      </div>
    </div>
  );
}

const roomsAr = (n) => (n === 1 ? "غرفة واحدة" : n === 2 ? "غرفتان" : `${ar(n)} غرف`);
const bathsAr = (n) => (n === 1 ? "دورة مياه" : n === 2 ? "دورتا مياه" : `${ar(n)} دورات مياه`);
const homeFacts = (h) => [tx(roomsAr(h.rooms), `${h.rooms} ${h.rooms > 1 ? "rooms" : "room"}`), tx(bathsAr(h.baths), `${h.baths} ${h.baths > 1 ? "bathrooms" : "bathroom"}`), tx(`${ar(h.size)} م²`, `${h.size} m²`)].join(" · ");

function HomeCard({ h, compact }) {
  const { state, go } = useApp();
  const r = requestFor(state, "home", h.id);
  if (compact) return (
    <button className="lift" data-home-tile={h.id} onClick={() => go({ s: "estate", id: h.id })} style={{ textAlign: "start", width: "100%" }}>
      <Photo kind="skyline" seed={h.id} photo={h.photo} ratio="4 / 3" radius={R.box} scrim="none" />
      <div style={{ fontSize: 13.5, fontWeight: 800, lineHeight: 1.45, marginTop: 7 }}>{L2(h.n)}</div>
      <div style={{ fontSize: 12, color: T.muted, marginTop: 2 }}>{L2(HOME_DEAL[h.deal].name)}</div>
    </button>
  );
  return (
    <button className="lift" data-home={h.id} onClick={() => go({ s: "estate", id: h.id })} style={{ textAlign: "start", width: "100%" }}>
      <Photo kind="skyline" seed={h.id} photo={h.photo} ratio="16 / 9" radius={R.media} scrim="none">
        <div className="row" style={{ position: "absolute", insetInlineStart: 9, top: 9, gap: 6 }}>
          <Pill tone={T.ink} bg={ON_PHOTO_BG} strong>{L2(HOME_DEAL[h.deal].name)}</Pill>
        </div>
      </Photo>
      <div style={{ fontSize: 15.5, fontWeight: 800, lineHeight: 1.45, marginTop: 8 }}>{L2(h.n)}</div>
      <div className="row" style={{ gap: 5, fontSize: 12.5, color: T.muted, marginTop: 3, lineHeight: 1.6 }}><MapPin size={13} style={{ flex: "0 0 13px" }} />{Dj([NB[h.nb]?.name, L2(h.kind), h.furnished ? tx("مفروشة", "Furnished") : tx("غير مفروشة", "Unfurnished")])}</div>
      <div className="row" style={{ gap: 8, marginTop: 4, flexWrap: "wrap" }}>
        <span style={{ fontSize: 12.5, fontWeight: 700 }}>{homeFacts(h)}</span>
        <RequestedPill r={r} />
      </div>
    </button>
  );
}

function ScreenEstate({ id }) {
  const { state } = useApp();
  const h = HOME_BY[id];
  const [open, setOpen] = useState(false);
  const [purpose, setPurpose] = useState("interest");
  if (!h) return <EmptyState title={tx("لم نعد نجد هذا السكن", "We can't find this home")} body={tx("ربما أُزيل من القسم.", "It may have been removed.")} />;
  const r = requestFor(state, "home", h.id);
  const more = HOMES.filter((x) => x.id !== h.id && x.deal === h.deal).concat(HOMES.filter((x) => x.deal !== h.deal)).slice(0, 4);
  return (
    <div className="screen scroll" data-estate={h.id} style={{ display: "flex", flexDirection: "column", minHeight: "100%" }}>
      <DetailHero photo={h.photo} seed={h.id} />
      <div style={{ padding: "16px 16px 0" }}>
        <div className="row" style={{ gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
          <Pill tone={T.green} bg={T.tint}>{L2(HOME_DEAL[h.deal].name)}</Pill>
          <RequestedPill r={r} />
        </div>
        <div style={{ fontSize: 23, fontWeight: 800, lineHeight: 1.35 }}>{L2(h.n)}</div>
        <div className="row" style={{ gap: 5, fontSize: 13.5, color: T.muted, marginTop: 5 }}><MapPin size={14} />{NB[h.nb]?.name}</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 8, marginTop: 14 }}>
          {[[BedDouble, h.rooms === 1 ? tx("غرفة", "Room") : tx("غرف", "Rooms"), ar(h.rooms)], [Bath, tx("دورات المياه", "Bathrooms"), ar(h.baths)], [Ruler, tx("المساحة", "Area"), tx(`${ar(h.size)} م²`, `${h.size} m²`)]].map(([Icon, l, v]) => (
            <div key={l} style={{ padding: "10px 6px", borderRadius: R.box, background: T.paper, border: `1px solid ${T.line}`, textAlign: "center", minWidth: 0 }}>
              <Icon size={17} color={T.green} />
              <div style={{ fontSize: 15, fontWeight: 800, marginTop: 3 }}>{v}</div>
              <div style={{ fontSize: 11, color: T.muted, fontWeight: 700 }}>{l}</div>
            </div>
          ))}
        </div>
        <div style={{ fontSize: 14.5, lineHeight: 1.95, marginTop: 14 }}>{L2(h.ab)}</div>
      </div>
      <div style={{ padding: "18px 16px 0" }}>
        <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 4 }}>{tx("تفاصيل السكن", "Home details")}</div>
        <FactRow label={tx("النوع", "Type")} value={L2(h.kind)} />
        <FactRow label={tx("العرض", "Offered")} value={Dj([L2(HOME_DEAL[h.deal].name), L2(h.term)])} />
        <FactRow label={tx("الطابق", "Floor")} value={L2(h.floor)} />
        <FactRow label={tx("التأثيث", "Furnishing")} value={h.furnished ? tx("مفروشة", "Furnished") : tx("غير مفروشة", "Unfurnished")} />
        <FactRow label={tx("يناسب", "Suits")} value={L2(h.suits)} />
        <div className="row" style={{ gap: 7, flexWrap: "wrap", marginTop: 12 }}>
          {h.feats.map((f) => <Pill key={f[0]} tone={T.green} bg={T.tint}>{L2(f)}</Pill>)}
        </div>
      </div>
      <AreaNoteSpaced nb={h.nb} />
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{tx("رحاب مكة ليس وسيطًا عقاريًا. سجّل اهتمامك أو اطلب التفاصيل، ويُحفظ طلبك في «طلباتي».", "Rihab Makkah is not a property broker. Register interest or request details, and your request is saved in My requests.")}</InfoNote>
      </div>
      <div style={{ padding: "22px 0 4px" }}>
        <SectionTitle title={tx("سكن آخر", "More homes")} />
        <div className="rail scroll">
          {more.map((x) => <div key={x.id} style={{ width: "var(--rail-tile)", flex: "0 0 auto" }}><HomeCard h={x} compact /></div>)}
        </div>
      </div>
      <RequestActions kind="home" r={r} onOpen={(p) => { setPurpose(p); setOpen(true); }} />
      <RequestSheet kind="home" refId={h.id} open={open} purpose={purpose} onClose={() => setOpen(false)} />
    </div>
  );
}
function AreaNoteSpaced({ nb }) {
  if (!NB[nb]?.blurb) return null;
  return <div style={{ marginTop: 20 }}><AreaNote nb={nb} /></div>;
}

const INVEST_NOTE = ["دليل تعريفي بفرص الأعمال في مكة. رحاب مكة ليس جهة استثمار ولا مستشارًا ماليًا ولا وسيطًا، ولا يعرض مبالغ أو عوائد أو تقييمات.",
  "An introductory directory of business opportunities in Makkah. Rihab Makkah is not an investment company, financial adviser or broker, and shows no amounts, returns or ratings."];

function InvestInMakkah() {
  const [cat, setCat] = useViewState("oppCat", "all");
  const [area, setArea] = useViewState("oppArea", "all");
  const areas = uniq(OPPORTUNITIES.map((o) => o.nb));
  const list = OPPORTUNITIES.filter((o) => (cat === "all" || o.cat === cat) && (area === "all" || o.nb === area));
  return (
    <div data-invest>
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{L2(INVEST_NOTE)}</InfoNote>
      </div>
      <div className="rail scroll" style={{ padding: "14px 0 8px" }}>
        {[{ id: "all", name: ["الكل", "All"] }, ...OPP_CATS].map((c) => <span key={c.id} data-opp-cat={c.id}><Chip active={cat === c.id} onClick={() => setCat(c.id)}>{L2(c.name)}</Chip></span>)}
      </div>
      <div className="rail scroll" style={{ paddingBottom: 12 }}>
        {["all", ...areas].map((a) => <span key={a} data-opp-area={a}><Chip icon={a === "all" ? undefined : MapPin} active={area === a} onClick={() => setArea(a)}>{a === "all" ? tx("كل المواقع", "All locations") : NB[a].name}</Chip></span>)}
      </div>
      <div data-result-count style={{ padding: "0 16px 10px", fontSize: 12.5, color: T.muted, fontWeight: 700 }}>
        {tx(countAr(list.length, "فرصة واحدة", "فرصتان", "فرص", "فرصة"), `${list.length} ${list.length === 1 ? "opportunity" : "opportunities"}`)}
      </div>
      <div style={{ padding: "0 16px", display: "grid", gap: 16 }}>
        {list.length ? list.map((o) => <OppCard key={o.id} o={o} />)
          : <EmptyState icon={Briefcase} title={tx("لا فرص بهذا الاختيار", "No opportunities for this choice")} body={tx("جرّب تصنيفًا آخر أو موقعًا آخر.", "Try another category or location.")} action={tx("اعرض الكل", "Show all")} onAction={() => { setCat("all"); setArea("all"); }} />}
      </div>
    </div>
  );
}

function OppCard({ o }) {
  const { state, go } = useApp();
  const [open, setOpen] = useState(false);
  const r = requestFor(state, "opp", o.id);
  return (
    <div data-opp={o.id} style={{ background: T.paper, border: `1px solid ${T.line}`, borderRadius: R.media, overflow: "hidden" }}>
      <button className="lift" onClick={() => go({ s: "opp", id: o.id })} style={{ display: "block", width: "100%", textAlign: "start" }}>
        <Photo kind="skyline" seed={o.id} photo={o.photo} ratio="16 / 9" radius={0} scrim="none">
          <div className="row" style={{ position: "absolute", insetInlineStart: 9, top: 9, gap: 6 }}>
            <Pill tone={T.ink} bg={ON_PHOTO_BG} strong>{L2(OPP_CAT[o.cat].name)}</Pill>
          </div>
        </Photo>
        <div style={{ padding: "11px 13px 0" }}>
          <div style={{ fontSize: 15.5, fontWeight: 800, lineHeight: 1.45 }}>{L2(o.n)}</div>
          <div className="row" style={{ gap: 5, fontSize: 12.5, color: T.muted, marginTop: 3, alignItems: "flex-start" }}><MapPin size={13} style={{ flex: "0 0 13px", marginTop: 4 }} /><span>{L2(o.loc)}</span></div>
          <div className="clamp2" style={{ fontSize: 13, lineHeight: 1.75, marginTop: 6 }}>{L2(o.ab)}</div>
          {r && <div style={{ marginTop: 8 }}><RequestedPill r={r} /></div>}
        </div>
      </button>
      <div className="row" style={{ gap: 8, padding: "12px 13px 13px" }}>
        <button className="press" data-opp-explore onClick={() => go({ s: "opp", id: o.id })} style={{ flex: 1, minWidth: 0, minHeight: 44, borderRadius: R.ctl, background: T.paper, border: `1px solid ${T.line}`, fontSize: 13, fontWeight: 800 }}>{tx("استكشف الفرصة", "Explore opportunity")}</button>
        <button className="press" data-opp-interest onClick={() => setOpen(true)} style={{ flex: 1, minWidth: 0, minHeight: 44, borderRadius: R.ctl, background: r ? `${T.ok}14` : T.deep, color: r ? T.ok : T.onDeep, fontSize: 13, fontWeight: 800 }}>
          {r ? (r.purpose === "info" ? tx("طلبك مسجّل", "Request recorded") : tx("اهتمامك مسجّل", "Interest registered")) : tx("سجّل اهتمامك", "Register interest")}
        </button>
      </div>
      <RequestSheet kind="opp" refId={o.id} open={open} onClose={() => setOpen(false)} />
    </div>
  );
}

function ScreenOpp({ id }) {
  const { state, go } = useApp();
  const o = OPP_BY[id];
  const [open, setOpen] = useState(false);
  const [purpose, setPurpose] = useState("interest");
  if (!o) return <EmptyState title={tx("لم نعد نجد هذه الفرصة", "We can't find this opportunity")} body={tx("ربما أُزيلت من الدليل.", "It may have been removed from the directory.")} />;
  const r = requestFor(state, "opp", o.id);
  const more = OPPORTUNITIES.filter((x) => x.id !== o.id && x.cat === o.cat).concat(OPPORTUNITIES.filter((x) => x.cat !== o.cat)).slice(0, 3);
  return (
    <div className="screen scroll" data-opp-page={o.id} style={{ display: "flex", flexDirection: "column", minHeight: "100%" }}>
      <DetailHero photo={o.photo} seed={o.id} />
      <div style={{ padding: "16px 16px 0" }}>
        <div className="row" style={{ gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
          <Pill tone={T.green} bg={T.tint}>{L2(OPP_CAT[o.cat].name)}</Pill>
          <RequestedPill r={r} />
        </div>
        <div style={{ fontSize: 23, fontWeight: 800, lineHeight: 1.35 }}>{L2(o.n)}</div>
        <div className="row" style={{ gap: 5, fontSize: 13.5, color: T.muted, marginTop: 5, alignItems: "flex-start" }}><MapPin size={14} style={{ flex: "0 0 14px", marginTop: 4 }} /><span>{L2(o.loc)}</span></div>
        <div style={{ fontSize: 14.5, lineHeight: 1.95, marginTop: 12 }}>{L2(o.ab)}</div>
      </div>
      <div style={{ padding: "18px 16px 0" }}>
        <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 4 }}>{tx("ملف الفرصة", "Opportunity profile")}</div>
        <FactRow label={tx("التصنيف", "Category")} value={L2(OPP_CAT[o.cat].name)} />
        <FactRow label={tx("الموقع", "Location")} value={L2(o.loc)} />
        <FactRow label={tx("طبيعة المشاركة", "Kind of involvement")} value={L2(o.model)} />
        <FactRow label={tx("تناسب", "Suits")} value={L2(o.audience)} />
        <FactRow label={tx("المرحلة", "Stage")} value={L2(OPP_STAGE)} />
      </div>
      <div style={{ padding: "18px 16px 0" }}>
        <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 8 }}>{tx("عن الفرصة", "About the opportunity")}</div>
        {o.points.map((p) => (
          <div key={p[0]} className="row" style={{ gap: 9, alignItems: "flex-start", padding: "7px 0" }}>
            <Check size={15} color={T.green} style={{ flex: "0 0 15px", marginTop: 4 }} />
            <span style={{ fontSize: 13.5, lineHeight: 1.75 }}>{L2(p)}</span>
          </div>
        ))}
      </div>
      <div style={{ padding: "0 16px" }}>
        <InfoNote>{L2(INVEST_NOTE)} {tx("تسجيل اهتمامك أو طلب المعلومات يُحفظ في «طلباتي».", "Registering interest or asking for information is saved in My requests.")}</InfoNote>
      </div>
      <div style={{ padding: "22px 16px 4px" }}>
        <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 10 }}>{tx("فرص أخرى", "Other opportunities")}</div>
        {more.map((x) => {
          const t = requestTarget("opp", x.id);
          return (
            <button key={x.id} className="press" data-opp-more={x.id} onClick={() => go({ s: "opp", id: x.id })} style={{ display: "flex", gap: 10, width: "100%", textAlign: "start", padding: "9px 0", borderBottom: `1px solid ${T.lineSoft}`, alignItems: "center" }}>
              <div style={{ width: 52, flex: "0 0 52px" }}><Photo kind="skyline" seed={x.id} photo={x.photo} ratio="1 / 1" radius={R.ctl} scrim="none" /></div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13.5, fontWeight: 800, lineHeight: 1.5 }}>{t.title}</div>
                <div style={{ fontSize: 12, color: T.muted, lineHeight: 1.5 }}>{t.sub}</div>
              </div>
              <ChevronLeft size={16} color={T.muted} />
            </button>
          );
        })}
      </div>
      <RequestActions kind="opp" r={r} onOpen={(p) => { setPurpose(p); setOpen(true); }} />
      <RequestSheet kind="opp" refId={o.id} open={open} purpose={purpose} onClose={() => setOpen(false)} />
    </div>
  );
}


/* ═══════════════════════════════════════════════════════════════════════════
   SHELL — four jobs in the bottom nav: الرئيسية · اكتشف · المجتمع · خطتي
   Profile lives behind the avatar. No AI tab: AI is horizontal.
   ═══════════════════════════════════════════════════════════════════════════ */

const TABS = [
  { id: "home", label: "الرئيسية", icon: Home },
  { id: "discover", label: "اكتشف", icon: Compass },
  { id: "market", label: "السوق", icon: ShoppingBag },
  { id: "community", label: "المجتمع", icon: Users },
  { id: "plan", label: "خطتي", icon: CalendarCheck },
];

/* On a phone the app owns the whole viewport; on a desktop it is presented inside
   a device frame at true phone width. */
/* Horizontal rails: mark which edges have more content (for the CSS edge fades) and,
   on first layout, bring an already-selected chip into view. Runs for every rail in
   the phone frame, including rails inside sheets, and follows DOM changes. */
function useRailFades(rootRef) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root || typeof MutationObserver === "undefined") return;
    let raf = 0;
    /* how much of the item crossing a rail edge is visible: the fade covers exactly that
       peek, so a partly shown card or chip is always faded, never hard-cut */
    const peekAt = (rail, end) => {
      const rr = rail.getBoundingClientRect();
      const rtl = getComputedStyle(rail).direction === "rtl";
      const x = end !== rtl ? rr.right : rr.left;
      for (const c of rail.children) {
        const cr = c.getBoundingClientRect();
        if (cr.left < x - 1 && cr.right > x + 1) return end === rtl ? cr.right - x : x - cr.left;
      }
      return 0;
    };
    const fadeFor = (w) => `${Math.round(Math.min(150, Math.max(20, w ? w + 8 : 20)))}px`;
    const update = (rail) => {
      const max = rail.scrollWidth - rail.clientWidth;
      if (max <= 2) { if (rail.hasAttribute("data-fade")) rail.removeAttribute("data-fade"); return; }
      const pos = Math.abs(rail.scrollLeft);
      const next = pos <= 2 ? "end" : pos >= max - 2 ? "start" : "both";
      if (rail.getAttribute("data-fade") !== next) rail.setAttribute("data-fade", next);
      if (next !== "start") rail.style.setProperty("--fade-end", fadeFor(peekAt(rail, true)));
      if (next !== "end") rail.style.setProperty("--fade-start", fadeFor(peekAt(rail, false)));
    };
    const all = () => root.querySelectorAll(".rail").forEach((rail) => {
      if (!rail.dataset.seen) {
        rail.dataset.seen = "1";
        const on = rail.querySelector('[aria-pressed="true"]');
        if (on) {
          const rr = rail.getBoundingClientRect(), cr = on.getBoundingClientRect();
          if (cr.left < rr.left + 16) rail.scrollLeft -= rr.left + 16 - cr.left;
          else if (cr.right > rr.right - 16) rail.scrollLeft += cr.right - (rr.right - 16);
        }
      }
      update(rail);
    });
    const schedule = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(all); };
    const onScroll = (e) => { const t = e.target; if (t && t.classList && t.classList.contains("rail")) update(t); };
    root.addEventListener("scroll", onScroll, true);
    const mo = new MutationObserver(schedule);
    mo.observe(root, { childList: true, subtree: true });
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null;
    if (ro) ro.observe(root);
    schedule();
    return () => { root.removeEventListener("scroll", onScroll, true); mo.disconnect(); if (ro) ro.disconnect(); cancelAnimationFrame(raf); };
  }, [rootRef]);
}

function useDeviceViewport() {
  const read = () => (typeof window === "undefined" ? false : window.innerWidth <= 560 || window.innerHeight <= 720);
  const [device, setDevice] = useState(read);
  useEffect(() => {
    const on = () => setDevice(read());
    window.addEventListener("resize", on);
    window.addEventListener("orientationchange", on);
    return () => { window.removeEventListener("resize", on); window.removeEventListener("orientationchange", on); };
  }, []);
  return device;
}

function BottomNav({ tab, onTab, planCount, safeBottom = "0px" }) {
  return (
    <div style={{
      position: "absolute", insetInline: 0, bottom: 0, zIndex: 50,
      background: "rgba(255,252,246,.94)", backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)",
      borderTop: `1px solid ${T.line}`, paddingTop: 8, paddingBottom: `calc(8px + ${safeBottom})`,
      paddingInline: 6, display: "flex",
    }}>
      {TABS.map((t) => {
        const on = tab === t.id;
        const Icon = t.icon;
        return (
          <button key={t.id} className="press" data-nav={t.id} onClick={() => onTab(t.id)} aria-current={on ? "page" : undefined}
            style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3, padding: "6px 0 4px", minHeight: 50, position: "relative" }}>
            <div style={{ position: "relative", display: "grid", placeItems: "center", width: 44, height: 26, borderRadius: R.pill, background: on ? T.tint : "transparent", transition: "background .18s" }}>
              <Icon size={20} color={on ? T.green : T.muted} strokeWidth={on ? 2.4 : 1.8} />
              {t.id === "plan" && planCount > 0 && (
                <span style={{ position: "absolute", top: -4, insetInlineEnd: -7, minWidth: 15, height: 15, padding: "0 3px", borderRadius: 99, background: T.clay, color: "#FFF8EA", fontSize: 9.5, fontWeight: 800, display: "grid", placeItems: "center" }}>
                  {ar(planCount)}
                </span>
              )}
            </div>
            <span style={{ fontSize: 10.5, fontWeight: on ? 800 : 600, color: on ? T.green : T.muted }}>{t.label}</span>
          </button>
        );
      })}
    </div>
  );
}

const TAB_OF = { home: "home", discover: "discover", market: "market", community: "community", family: "community", club: "community", thread: "community", plan: "plan" };

/* A real app fails sometimes; the product should say so and offer a way out. */
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidUpdate(prev) { if (prev.viewKey !== this.props.viewKey && this.state.error) this.setState({ error: null }); }
  render() {
    if (!this.state.error) return this.props.children;
    return (
      <div style={{ padding: "60px 26px", textAlign: "center" }}>
        <div style={{ width: 54, height: 54, borderRadius: 18, background: `${T.warn}18`, display: "grid", placeItems: "center", margin: "0 auto 14px" }}>
          <AlertTriangle size={24} color={T.warn} />
        </div>
        <div style={{ fontSize: 16.5, fontWeight: 800, marginBottom: 6 }}>تعذّر عرض هذه الشاشة</div>
        <div style={{ fontSize: 13.5, color: T.muted, lineHeight: 1.8 }}>
          حدث خطأ غير متوقع. خطتك ومساهماتك لم تتأثر.
        </div>
        <button className="press" onClick={() => { this.setState({ error: null }); this.props.onReset && this.props.onReset(); }}
          style={{ marginTop: 16, background: T.deep, color: T.onDeep, padding: "11px 20px", borderRadius: R.ctl, fontSize: 13.5, fontWeight: 800 }}>
          رجوع إلى الرئيسية
        </button>
      </div>
    );
  }
}

function resetAgentSession() {
  AGENT_SESSION.messages = [];
  Object.assign(AGENT_SESSION.mem, { turn: 0, lastIntent: null, lastQuery: null, ranked: [], shown: [], offset: 0, lastObject: null, lastOffer: null, lastOuting: null, lastAction: null, lastEntities: null, lastShape: null, recentSugg: [] });
}

export default function RihabMakkahApp() {
  const [state, dispatch] = useReducer(reducer, undefined, () => {
    const s = initialState();
    const saved = store.get(LANG_KEY);
    if (saved === "ar" || saved === "en") s.profile.lang = saved;
    return s;
  });
  const [stack, setStack] = useState([{ s: "home" }]);
  /* entry: landing → language → login ⇄ createAccount / signupEmail / phone / forgot → profileSetup → app.
     The app shell is not rendered at all until entry === "app". */
  const [auth, setAuth] = useState(() => { const ses = readSession(); return ses ? { status: "restoring", session: ses } : { status: "signedOut", session: null }; });
  const [entry, setEntry] = useState(() => (readSession() ? "restoring" : "rihab"));
  useEffect(() => { if (["rihab", "landing", "language", "login", "createAccount", "signupEmail", "phone", "forgot"].includes(entry)) goRihab(); }, [entry]);
  const [loginNotice, setLoginNotice] = useState(null);
  const [loginEmail, setLoginEmail] = useState("");
  const [phonePurpose, setPhonePurpose] = useState("login");
  const [createReturn, setCreateReturn] = useState("login");
  const [setup, setSetup] = useState({ initial: {}, busy: false, error: null });
  const [toastMsg, setToastMsg] = useState(null);
  const scrollRef = useRef(null);
  const phoneRef = useRef(null);
  const authRef = useRef(auth);
  authRef.current = auth;
  const stateRef = useRef(state);
  stateRef.current = state;
  const [resetToken, setResetToken] = useState(null);
  useRailFades(phoneRef);
  const view = stack[stack.length - 1];
  const ctx = useMemo(() => deriveContext(state), [state]);
  const toast = useCallback((m) => setToastMsg(m), []);
  const langNow = state.profile.lang || "ar";
  useEffect(() => { store.set(LANG_KEY, langNow); }, [langNow]);

  const enterApp = useCallback(() => { setStack([{ s: "home" }]); setEntry("app"); }, []);
  /* restore the account's My Plan; a plan that was never created gets the starter plan once */
  const enterWithPlan = useCallback((uid, prof) => {
    /* a ready account receives its prepared history once per device (PREPARED_ACCOUNTS) */
    const prep = PREPARED_ACCOUNTS[uid];
    if (prep && (PlanStore.load(uid)?.prepared || 0) < PREPARED_VERSION) {
      const p = prep();
      PlanStore.save(uid, { plan: p.plan, saved: p.saved, seeded: true, prepared: PREPARED_VERSION });
      CommunityStore.save(uid, p.community);
      RequestStore.save(uid, p.requests);
    }
    dispatch({ type: "restore_requests", requests: RequestStore.load(uid) });
    dispatch({ type: "restore_community", ...(CommunityStore.load(uid) || {}) });
    const rec = PlanStore.load(uid);
    if (rec && (rec.seeded || rec.plan.length)) {
      dispatch({ type: "restore_plan", plan: rec.plan, saved: rec.saved });
    } else {
      const cur = stateRef.current;
      const patch = {};
      for (const k of ACCOUNT_FIELDS) if (k !== "lang") patch[k] = prof[k] ?? null;
      const starter = buildStarterPlan({ ...cur, plan: [], profile: { ...cur.profile, ...patch } });
      const saved = (rec && rec.saved) || {};
      dispatch({ type: "restore_plan", plan: starter, saved });
      PlanStore.save(uid, { plan: starter, saved, seeded: true });
    }
    enterApp();
  }, [enterApp]);
  const applyAccount = useCallback((prof, withLang) => {
    const patch = {};
    for (const k of ACCOUNT_FIELDS) if (k !== "lang") patch[k] = prof[k] ?? null;
    if (withLang && (prof.lang === "ar" || prof.lang === "en")) { patch.lang = prof.lang; setLang(prof.lang); }
    dispatch({ type: "profile", patch });
  }, []);
  const lastSaved = useRef(null);
  const accountSig = (p) => JSON.stringify(ACCOUNT_FIELDS.map((k) => p[k] ?? null));

  /* after any confirmed sign-in: load the account profile, or ask for it */
  const afterSignIn = useCallback(async (res) => {
    const session = res.session;
    writeSession(session);
    setAuth({ status: "signedIn", session });
    setLoginNotice(null);
    setEntry("loadingAccount");
    let prof = null;
    try { prof = await ProfileStore.load(session); }
    catch (e) {
      clearSession();
      setAuth({ status: "signedOut", session: null });
      setLoginNotice({ tone: "error", text: authMessage(e.code, langNow) });
      setEntry("login");
      return;
    }
    if (profileComplete(prof)) {
      applyAccount(prof, false);
      lastSaved.current = null;
      enterWithPlan(session.uid, prof);
    } else {
      setSetup({ busy: false, error: null, initial: rihabPrefill(session.uid, { ...(prof || {}), firstName: (prof && prof.firstName) || res.names?.firstName || "", lastName: (prof && prof.lastName) || res.names?.lastName || "" }) });
      setEntry("profileSetup");
    }
  }, [applyAccount, enterWithPlan, langNow]);

  const completeSetup = useCallback(async (profile) => {
    setSetup((st) => ({ ...st, busy: true, error: null }));
    try {
      const ses = await freshSession(authRef.current.session);
      setAuth({ status: "signedIn", session: ses });
      const saved = await ProfileStore.save(ses, { ...profile, lang: langNow });
      Auth.updateDisplayName(ses, `${profile.firstName} ${profile.lastName}`).catch(() => {});
      applyAccount(saved, false);
      lastSaved.current = accountSig(saved);
      setSetup({ initial: {}, busy: false, error: null });
      enterWithPlan(ses.uid, saved);
    } catch (e) {
      setSetup((st) => ({ ...st, busy: false, error: authMessage(e.code, langNow) }));
    }
  }, [applyAccount, enterWithPlan, langNow]);

  const endSession = useCallback((notice) => {
    const ses = authRef.current.session;
    if (ses && !ses.local) store.del(profileKey(ses.uid));   // on-device accounts keep their profile for the next sign-in
    clearSession();
    resetAgentSession();
    setAuth({ status: "signedOut", session: null });
    dispatch({ type: "reset", lang: langNow });
    setStack([{ s: "home" }]);
    lastSaved.current = null;
    setLoginNotice(notice ? { tone: "success", text: notice } : null);
    setEntry("login");
  }, [langNow]);
  const signOut = useCallback(async () => { endSession(tx("سجّلت الخروج من حسابك.", "You've signed out.")); }, [endSession]);
  const deleteAccount = useCallback(async () => {
    const ses = await freshSession(authRef.current.session);
    await ProfileStore.remove(ses);
    await Auth.deleteAccount(ses);
    PlanStore.remove(ses.uid);
    RequestStore.remove(ses.uid);
    CommunityStore.remove(ses.uid);
    endSession(tx("حُذف حسابك وبياناتك الشخصية.", "Your account and personal details were deleted."));
  }, [endSession]);
  const saveProfile = useCallback(async (next) => {
    const errs = { ...profileErrors(next), ...personaErrors(next) };
    if (Object.keys(errs).length) throw new AuthError("invalid_profile");
    const ses = await freshSession(authRef.current.session);
    if (ses !== authRef.current.session) setAuth({ status: "signedIn", session: ses });
    const saved = await ProfileStore.save(ses, { ...next, lang: langNow });
    lastSaved.current = accountSig(saved);
    applyAccount(saved, false);
  }, [applyAccount, langNow]);
  const resendVerification = useCallback(async () => {
    const ses = await freshSession(authRef.current.session);
    await Auth.sendEmailVerification(ses);
  }, []);

  /* restore a saved session on launch */
  useEffect(() => {
    if (auth.status !== "restoring") return undefined;
    let alive = true;
    (async () => {
      const stored = auth.session;
      /* Rihab: the session comes from the Rihab sign-in, so the on-device accounts (and the
         demo accounts' city profiles) are made ready before the profile is read */
      if (Auth.mode === "local") LocalAuth.db();
      try {
        const ses = await freshSession(stored);
        let prof;
        try { prof = await ProfileStore.load(ses); } catch { prof = ProfileStore.local(ses.uid); }
        if (!alive) return;
        setAuth({ status: "signedIn", session: ses });
        if (ses.provider === "password") Auth.lookup(ses).then((u) => { if (u && alive) setAuth((a) => (a.session ? { ...a, session: { ...a.session, emailVerified: !!u.emailVerified } } : a)); }).catch(() => {});
        if (profileComplete(prof)) { applyAccount(prof, false); lastSaved.current = accountSig(prof); enterWithPlan(ses.uid, prof); }
        else { setSetup({ initial: rihabPrefill(ses.uid, prof), busy: false, error: null }); setEntry("profileSetup"); }
      } catch (e) {
        if (!alive) return;
        const cached = ProfileStore.local(stored.uid);
        if (e.code === "network" && profileComplete(cached)) {
          setAuth({ status: "signedIn", session: stored });
          applyAccount(cached, false);
          lastSaved.current = accountSig(cached);
          enterWithPlan(stored.uid, cached);
          return;
        }
        clearSession();
        setAuth({ status: "signedOut", session: null });
        setEntry("landing");
      }
    })();
    return () => { alive = false; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* account fields changed elsewhere (language, the Assistant) follow the account */
  const sig = auth.status === "signedIn" && entry === "app" ? accountSig(state.profile) : null;
  useEffect(() => {
    if (!sig || sig === lastSaved.current) return undefined;
    const prof = Object.fromEntries(ACCOUNT_FIELDS.map((k) => [k, state.profile[k] ?? null]));
    if (!profileComplete(prof)) return undefined;
    const id = setTimeout(async () => {
      try {
        const ses = await freshSession(authRef.current.session);
        if (ses !== authRef.current.session) setAuth({ status: "signedIn", session: ses });
        await ProfileStore.save(ses, prof);
        lastSaved.current = sig;
      } catch { /* kept on the device; saved again with the next change */ }
    }, 600);
    return () => clearTimeout(id);
  }, [sig]); // eslint-disable-line react-hooks/exhaustive-deps
  /* My Plan is kept with the account */
  const planUid = auth.status === "signedIn" && entry === "app" ? auth.session.uid : null;
  useEffect(() => {
    if (!planUid) return;
    PlanStore.save(planUid, { plan: state.plan, saved: state.saved, seeded: true });
  }, [planUid, state.plan, state.saved]);
  /* «طلباتي» follows the account too, kept apart from My Plan */
  useEffect(() => { if (planUid) RequestStore.save(planUid, state.requests || []); }, [planUid, state.requests]);
  useEffect(() => { if (planUid) CommunityStore.save(planUid, state); }, [planUid, state.joinedCommunities, state.followedCommunities, state.contributions, state.helpful]);   // eslint-disable-line react-hooks/exhaustive-deps

  /* links and codes delivered to this device */
  useEffect(() => Inbox.onAction((act) => {
    if (act.type === "reset") {
      if (authRef.current.status === "signedIn") return;
      setResetToken(act.token);
      setEntry("resetPassword");
    }
    if (act.type === "verify") {
      try {
        const uid = LocalAuth.confirmEmail(act.token);
        setAuth((a) => (a.session && a.session.uid === uid ? { ...a, session: { ...a.session, emailVerified: true } } : a));
        const ses = readSession();
        if (ses && ses.uid === uid) writeSession({ ...ses, emailVerified: true });
        setToastMsg(tx("تم تأكيد بريدك الإلكتروني.", "Your email is confirmed."));
      } catch { setToastMsg(tx("رابط التأكيد غير صالح.", "That confirmation link isn't valid.")); }
    }
  }), []);
  const account = { status: auth.status, session: auth.session, signOut, deleteAccount, saveProfile, resendVerification };

  const go = useCallback((next) => {
    if (next?.back) { setStack((st) => (st.length > 1 ? st.slice(0, -1) : st)); return; }
    setStack((st) => [...st, next]);
  }, []);
  const setTab = useCallback((t) => setStack([{ s: t }]), []);

  /* each stack entry keeps its own screen state and scroll position, so Back returns to
     exactly where the person was; a newly opened screen starts at the top */
  const viewMems = useRef(new WeakMap());
  if (!viewMems.current.has(view)) viewMems.current.set(view, {});
  const viewMem = viewMems.current.get(view);
  useLayoutEffect(() => {
    const el = scrollRef.current; if (!el) return;
    el.scrollTop = viewMem.scrollTop || 0;
    /* horizontal rails come back to where they were too */
    if (viewMem.rails) el.querySelectorAll(".rail").forEach((r, i) => { if (viewMem.rails[i] != null) r.scrollLeft = viewMem.rails[i]; });
    /* content that lays out a frame later (images, fonts) — try once more */
    const id = requestAnimationFrame(() => { if (viewMem.scrollTop && Math.abs(el.scrollTop - viewMem.scrollTop) > 2) el.scrollTop = viewMem.scrollTop; });
    return () => cancelAnimationFrame(id);
  }, [view]);

  const [dismissTarget, setDismissTarget] = useState(null);
  const askDismiss = useCallback((o) => setDismissTarget(o), []);
  const api = { state, dispatch, ctx, go, setTab, toast, askDismiss, account, viewMem };
  const planCount = state.plan.filter((p) => ["planned", "going", "registered", "confirmed", "active", "awaiting"].includes(p.state)).length;
  const tab = TAB_OF[view.s] || (["object", "search", "assistant", "profile", "account", "password", "notifications", "provider", "product", "city", "estate", "opp", "requests"].includes(view.s) ? TAB_OF[stack[0]?.s] || "home" : "home");
  const hideNav = ["search", "thread", "object", "assistant", "account", "password", "product", "estate", "opp"].includes(view.s);
  const ts = state.profile.textScale || 1;
  const device = useDeviceViewport();
  const lang = state.profile.lang || "ar";
  setLang(lang);                                        // formatting helpers follow the language
  const persona = entry === "app" ? personaOf(state.profile) : null;
  applyTheme(persona);                                  // the account's accent theme, inside the app only
  const dir = lang === "ar" ? "rtl" : "ltr";
  const safeBottom = "env(safe-area-inset-bottom, 0px)";
  const depth = stack.length;
  const prevDepth = useRef(depth);
  const [anim, setAnim] = useState("fade");
  useEffect(() => {
    setAnim(depth > prevDepth.current ? "push" : depth < prevDepth.current ? "fade" : "fade");
    prevDepth.current = depth;
  }, [depth, view.s, view.id]);

  const render = () => {
    switch (view.s) {
      case "home": return <ScreenHome />;
      case "discover": return <ScreenDiscover params={view} />;
      case "community": return view.id ? <ScreenCommunityDetail id={view.id} /> : <ScreenCommunity />;
      case "family": return <ScreenFamily id={view.id} />;
      case "club": return <ScreenClub id={view.id} />;
      case "thread": return <ScreenThread id={view.id} />;
      case "plan": return <ScreenPlan />;
      case "object": return <ScreenObject id={view.id} />;
      case "search": return <ScreenSearch />;
      case "assistant": return <ScreenAssistant params={view} />;
      case "profile": return <ScreenProfile />;
      case "account": return <ScreenAccountEdit />;
      case "password": return <ScreenChangePassword />;
      case "notifications": return <ScreenNotifications />;
      case "provider": return <ScreenProvider />;
      case "city": return <ScreenCity params={view} />;
      case "estate": return <ScreenEstate id={view.id} />;
      case "opp": return <ScreenOpp id={view.id} />;
      case "market": return <ScreenMarket params={view} />;
      case "product": return <ScreenProduct id={view.id} />;
      case "requests": return <ScreenRequests />;
      default: return <ScreenHome />;
    }
  };

  return (
    <App.Provider value={api}>
      <style>{CSS}</style>
      <div className="em" data-app data-persona={persona || "entry"} style={{
        ...themeVars(),
        minHeight: "100dvh", background: device ? T.limestone : `radial-gradient(1200px 700px at 50% -10%, #FBF8EF 0%, #EFE8D8 52%, ${T.sandDeep} 100%)`,
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: device ? 0 : "22px 12px",
      }} dir={dir}>
        <div style={{ width: device ? "100%" : 390, maxWidth: "100%" }}>
          <div data-phone ref={phoneRef} style={{
            "--safe-top": device ? "env(safe-area-inset-top, 0px)" : "0px",
            "--safe-bottom": device ? "env(safe-area-inset-bottom, 0px)" : "0px",
            position: "relative",
            height: device ? "100dvh" : 844,
            maxHeight: device ? "none" : "calc(100dvh - 44px)",
            borderRadius: device ? 0 : 38,
            overflow: "hidden", background: T.limestone,
            boxShadow: device ? "none" : "0 30px 70px -26px rgba(38,28,16,.45)",
            border: device ? "none" : `1px solid ${T.line}`,
          }}>
            {entry === "app" ? (<>
            {/* text size works the way a device setting does: content reflows to a
                narrower box and is scaled up, so nothing is clipped. */}
            <div ref={scrollRef} className="scroll" key={`${stack.length}:${view.s}${view.id || ""}`}
              onScroll={(e) => { viewMem.scrollTop = e.currentTarget.scrollTop; }}
              onScrollCapture={(e) => {
                const r = e.target;
                if (!r.classList?.contains("rail")) return;
                const i = [...e.currentTarget.querySelectorAll(".rail")].indexOf(r);
                if (i > -1) (viewMem.rails = viewMem.rails || {})[i] = r.scrollLeft;
              }}
              data-screen aria-hidden={entry !== "app" ? "true" : undefined}
              style={{
                position: "absolute", inset: 0, overflowY: "auto", overflowX: "clip",
                paddingBottom: hideNav ? 0 : `calc(66px + ${safeBottom})`,
                zoom: ts === 1 ? undefined : ts,
                width: ts === 1 ? undefined : `${100 / ts}%`,
                height: ts === 1 ? undefined : `${100 / ts}%`,
              }}>
              <ErrorBoundary viewKey={view.s + (view.id || "")} onReset={() => setStack([{ s: "home" }])}>
                <div className={anim} style={{ "--push": dir === "rtl" ? "-18px" : "18px" }}>
                  <Localize>{render()}</Localize>
                </div>
              </ErrorBoundary>
            </div>
            <Localize>
              {!hideNav && <BottomNav tab={tab} onTab={setTab} planCount={planCount} safeBottom={safeBottom} />}
              <DismissSheet o={dismissTarget} onClose={() => setDismissTarget(null)} />
            </Localize>
            </>) : (
              <div data-entry={entry} style={{ position: "absolute", inset: 0, zIndex: 120, background: T.deep }}>
                {(entry === "restoring" || entry === "loadingAccount") && <ScreenAccountLoading lang={lang} label={entry} />}
                {entry === "landing" && <ScreenLanding lang={lang} onEnter={() => setEntry((e) => (e === "landing" ? "language" : e))} />}
                {entry === "language" && (
                  <ScreenLanguage onPick={(l) => { dispatch({ type: "profile", patch: { lang: l } }); setLang(l); setEntry("login"); }} />
                )}
                {entry === "login" && (
                  <ScreenLogin lang={lang} notice={loginNotice?.tone === "success" ? loginNotice.text : null} error={loginNotice?.tone === "error" ? loginNotice.text : null}
                    prefillEmail={loginEmail} onDone={afterSignIn}
                    onCreate={() => { setLoginNotice(null); setCreateReturn("login"); setEntry("createAccount"); }}
                    onForgot={(em) => { setLoginNotice(null); setLoginEmail(em); setEntry("forgot"); }}
                    onPhone={(p) => { setLoginNotice(null); setPhonePurpose(p); setEntry("phone"); }}
                  />
                )}
                {entry === "createAccount" && (
                  <ScreenCreateAccount lang={lang} onBack={() => setEntry(createReturn)} onDone={afterSignIn}
                    onEmail={() => setEntry("signupEmail")} onPhone={(p) => { setPhonePurpose(p); setEntry("phone"); }} />
                )}
                {entry === "signupEmail" && (
                  <ScreenEmailSignup lang={lang} onBack={() => setEntry("createAccount")} onDone={afterSignIn}
                    onSignIn={(em) => { setLoginEmail(em); setEntry("login"); }} />
                )}
                {entry === "phone" && (
                  <ScreenPhoneAuth lang={lang} purpose={phonePurpose} onDone={afterSignIn}
                    onBack={() => setEntry(phonePurpose === "signup" ? "createAccount" : "login")} />
                )}
                {entry === "forgot" && (
                  <ScreenForgotPassword lang={lang} initialEmail={loginEmail} onBack={(em) => { if (em) setLoginEmail(em); setEntry("login"); }} />
                )}
                {entry === "resetPassword" && (
                  <ScreenResetPassword lang={lang} token={resetToken} onBack={() => setEntry("login")}
                    onDone={(em) => { setLoginEmail(em); setResetToken(null); setLoginNotice({ tone: "success", text: tx("حُدّثت كلمة المرور. سجّل الدخول بها الآن.", "Your password was updated. Sign in with it now.") }); setEntry("login"); }} />
                )}
                {entry === "profileSetup" && (
                  <ScreenProfileSetup lang={lang} initial={setup.initial} busy={setup.busy} error={setup.error}
                    onSubmit={completeSetup} onCancel={() => endSession(null)} />
                )}
              </div>
            )}
            <DeviceMessages lang={lang} />
            {/* toasts are written in Arabic like the rest of the UI and read in the app's language */}
            <Localize><Toast msg={toastMsg} onDone={() => setToastMsg(null)} /></Localize>
          </div>
        </div>
      </div>
    </App.Provider>
  );
}


/* debug surface used by scripts/dbg.mjs — tree-shaken out of the app bundle */
export const __debug = { INVENTORY, COMMUNITIES, CONTRIBUTIONS, buildOutings, buildHome, deriveContext, initialState, rank, scoreObject, lifecycleOf, objectTrust, searchAll, CLUBS, getObj, NEIGHBORHOODS, CATEGORIES };
